// Meanings for the Viṣṇu Sahasranāmam — shown by the "Meaning" button on each śloka.
// Written fresh in plain words (English, Telugu, Hindi), following the traditional (Śaṅkara) reading of the names.
// Key = the śloka's key in the app: vsn_<section>_<n>.  names: [IAST name, Telugu name, English, Telugu, Hindi]
window.MEANINGS = Object.assign(window.MEANINGS || {}, {
"vsn_preamble_1": { "en": "One should meditate on Viṣṇu — dressed in white, bright as the moon, with four arms and a gracious, smiling face — so that every obstacle is removed.", "te": "తెల్లని వస్త్రాలు ధరించినవాడు, చంద్రుని వంటి కాంతి గలవాడు, నాలుగు భుజాలు గలవాడు, ప్రసన్నమైన ముఖం గలవాడు అయిన విష్ణువును — సర్వ విఘ్నాలు తొలగిపోవడానికి — ధ్యానించాలి.", "hi": "श्वेत वस्त्र धारण करने वाले, चंद्रमा जैसी कांति वाले, चार भुजाओं वाले, प्रसन्न मुख वाले विष्णु का — सब विघ्नों की शांति के लिए — ध्यान करना चाहिए।" },
"vsn_preamble_2": { "en": "I take refuge in Viṣvaksena, whose hundreds of attendants — led by the elephant-faced one — constantly destroy every obstacle.", "te": "గజముఖుడు మొదలైన వందలాది పరివారం ఎల్లప్పుడూ విఘ్నాలను నశింపజేస్తుందో, ఆ విష్వక్సేనుని నేను ఆశ్రయిస్తాను.", "hi": "जिनके गजमुख आदि सैकड़ों पार्षद निरंतर विघ्नों का नाश करते हैं, उन विष्वक्सेन की मैं शरण लेता हूँ।" },
"vsn_purva_3": { "en": "I bow to Vyāsa — great-grandson of Vasiṣṭha, grandson of Śakti, son of Parāśara, father of Śuka — the spotless one, a treasure of tapas.", "te": "వసిష్ఠుని మునిమనుమడు, శక్తి మహర్షి మనుమడు, పరాశరుని కుమారుడు, శుకుని తండ్రి, నిర్మలుడు, తపోనిధి అయిన వ్యాసునికి నమస్కరిస్తున్నాను.", "hi": "वसिष्ठ के प्रपौत्र, शक्ति के पौत्र, पराशर के पुत्र, शुकदेव के पिता, निष्कलंक और तप के भंडार व्यास को मैं प्रणाम करता हूँ।" },
"vsn_purva_4": { "en": "Salutations again and again to Vyāsa, who is Viṣṇu in form, and to Viṣṇu, who took the form of Vyāsa — the treasure-house of the Veda, born in Vasiṣṭha's line.", "te": "విష్ణు స్వరూపుడైన వ్యాసునికి, వ్యాస రూపంలో ఉన్న విష్ణువుకు, వేదనిధి అయిన వసిష్ఠ వంశీయునికి మళ్ళీ మళ్ళీ నమస్కారం.", "hi": "विष्णु-स्वरूप व्यास को, और व्यास-रूप धारण करने वाले विष्णु को — वेद के निधि, वसिष्ठ-वंशी को — बार-बार नमस्कार।" },
"vsn_purva_5": { "en": "Salutations to Viṣṇu — who never changes, who is pure, eternal, the Supreme Self, always of one same nature, and victorious over all.", "te": "మార్పు లేనివాడు, శుద్ధుడు, నిత్యుడు, పరమాత్మ, ఎప్పుడూ ఒకే స్వరూపంలో ఉండేవాడు, అందరినీ జయించేవాడు అయిన విష్ణువుకు నమస్కారం.", "hi": "जो निर्विकार, शुद्ध, नित्य, परमात्मा, सदा एक ही स्वरूप वाले और सबको जीतने वाले हैं, उन विष्णु को नमस्कार।" },
"vsn_purva_6": { "en": "Salutations to the all-powerful Viṣṇu, by merely remembering whom a person is freed from the bondage of birth and worldly life.", "te": "కేవలం స్మరించినంత మాత్రాన జనన మరణ సంసార బంధం నుండి విముక్తి కలిగించే సర్వ సమర్థుడైన విష్ణువుకు నమస్కారం.", "hi": "जिनके केवल स्मरण से मनुष्य जन्म और संसार के बंधन से छूट जाता है, उन सर्वसमर्थ विष्णु को नमस्कार।" },
"vsn_purva_7": { "en": "Vaiśampāyana said: Having heard all the dharmas in full, and every means of purification, Yudhiṣṭhira again asked Bhīṣma, the son of Śantanu:", "te": "వైశంపాయనుడు అన్నాడు: ధర్మాలన్నిటినీ, పవిత్రం చేసే మార్గాలన్నిటినీ పూర్తిగా విన్న తర్వాత ధర్మరాజు శంతను కుమారుడైన భీష్ముణ్ణి మళ్ళీ ఇలా అడిగాడు:", "hi": "वैशंपायन बोले: सब धर्मों और पवित्र करने वाले सब उपायों को पूरी तरह सुनकर युधिष्ठिर ने शांतनु-पुत्र भीष्म से फिर पूछा:" },
"vsn_purva_8": { "en": "Yudhiṣṭhira asked: Who is the one God in the world? What is the one highest refuge? Praising whom, and worshipping whom, do people attain what is good?", "te": "ధర్మరాజు అడిగాడు: లోకంలో ఒక్కడైన దైవం ఎవరు? ఒక్కటైన పరమ ఆశ్రయం ఏది? ఎవరిని స్తుతిస్తే, ఎవరిని పూజిస్తే మనుషులకు శుభం కలుగుతుంది?", "hi": "युधिष्ठिर ने पूछा: संसार में एक ही देवता कौन है? एक ही परम आश्रय क्या है? किसकी स्तुति और किसकी पूजा करके मनुष्य कल्याण पाते हैं?" },
"vsn_purva_9": { "en": "Which dharma do you hold to be the highest of all dharmas? By chanting what is a living being freed from the bondage of birth and worldly life?", "te": "అన్ని ధర్మాలలో మీరు ఏ ధర్మాన్ని పరమ ధర్మంగా భావిస్తారు? దేనిని జపిస్తే జీవి జనన సంసార బంధం నుండి విముక్తుడవుతాడు?", "hi": "सब धर्मों में आप किस धर्म को सबसे श्रेष्ठ मानते हैं? किसका जप करके जीव जन्म और संसार के बंधन से मुक्त होता है?" },
"vsn_purva_10": { "en": "Bhīṣma said: One who, always ready and alert, praises with these thousand names the Lord of the world, God of gods, the endless one, the Supreme Person —", "te": "భీష్ముడు అన్నాడు: జగత్తుకు ప్రభువు, దేవదేవుడు, అనంతుడు, పురుషోత్తముడు అయినవానిని ఎల్లప్పుడూ ఉత్సాహంగా సహస్ర నామాలతో స్తుతించేవాడు —", "hi": "भीष्म बोले: जो मनुष्य सदा तत्पर रहकर जगत के प्रभु, देवों के देव, अनंत पुरुषोत्तम की सहस्र नामों से स्तुति करता है —" },
"vsn_purva_11": { "en": "— and who daily worships that same imperishable Person with devotion, meditating on Him, praising Him, bowing to Him and offering worship to Him alone —", "te": "— ఆ అవ్యయుడైన పురుషుణ్ణే ప్రతిరోజూ భక్తితో పూజిస్తూ, ధ్యానిస్తూ, స్తుతిస్తూ, నమస్కరిస్తూ, ఆయనకే ఆరాధన చేసేవాడు —", "hi": "— और उसी अविनाशी पुरुष की नित्य भक्ति से पूजा करता है, उनका ध्यान, स्तुति और नमस्कार करता है, उन्हीं का यजन करता है —" },
"vsn_purva_12": { "en": "— praising daily Viṣṇu, who has no beginning or end, the great Lord of all worlds and the overseer of the world, crosses beyond all sorrow.", "te": "— ఆది అంతం లేనివాడు, సర్వలోకాలకు మహేశ్వరుడు, లోకాన్ని పర్యవేక్షించేవాడు అయిన విష్ణువును నిత్యం స్తుతించేవాడు అన్ని దుఃఖాలనూ దాటిపోతాడు.", "hi": "— आदि-अंत रहित, सब लोकों के महेश्वर, लोकों के अध्यक्ष विष्णु की नित्य स्तुति करने वाला सब दुःखों से पार हो जाता है।" },
"vsn_purva_13": { "en": "He is devoted to the Veda and to dharma, knows every dharma, increases the fame of the worlds; He is the Lord of the world, the great Being, the source of every being.", "te": "ఆయన వేదానికీ ధర్మానికీ హితుడు, సర్వ ధర్మాలూ తెలిసినవాడు, లోకాల కీర్తిని పెంచేవాడు, లోకనాథుడు, మహత్తర భూతం, సర్వ ప్రాణుల పుట్టుకకు మూలం.", "hi": "वे वेद और धर्म के हितैषी, सब धर्मों के ज्ञाता, लोकों की कीर्ति बढ़ाने वाले, लोकनाथ, महान सत्ता और सब प्राणियों की उत्पत्ति के मूल हैं।" },
"vsn_purva_14": { "en": "Of all dharmas, this I hold to be the greatest: that a person should always worship the lotus-eyed Lord with devotion, through hymns of praise.", "te": "అన్ని ధర్మాలలో ఇదే అత్యున్నత ధర్మం అని నా అభిప్రాయం: మనిషి ఎల్లప్పుడూ భక్తితో, స్తోత్రాలతో పుండరీకాక్షుణ్ణి పూజించడం.", "hi": "सब धर्मों में मैं इसे सबसे श्रेष्ठ धर्म मानता हूँ कि मनुष्य सदा भक्ति से, स्तोत्रों द्वारा कमलनयन भगवान की पूजा करे।" },
"vsn_purva_15": { "en": "He is the supreme light, the supreme tapas, the supreme Brahman, the supreme refuge.", "te": "ఆయనే పరమ తేజస్సు, పరమ తపస్సు, పరబ్రహ్మ, పరమ ఆశ్రయం.", "hi": "वही परम तेज हैं, वही परम तप हैं, वही परम ब्रह्म हैं, वही परम आश्रय हैं।" },
"vsn_purva_16": { "en": "He is the purest of all that purifies, the most auspicious of all that is auspicious, the God of gods, and the undying father of all beings.", "te": "పవిత్రమైనవాటిలో అత్యంత పవిత్రుడు, మంగళకరమైనవాటిలో అత్యంత మంగళకరుడు, దేవతలకే దైవం, సర్వ ప్రాణులకూ నాశనం లేని తండ్రి.", "hi": "वे पवित्रों में भी पवित्र, मंगलों में भी मंगल, देवताओं के भी देवता और सब प्राणियों के अविनाशी पिता हैं।" },
"vsn_purva_17": { "en": "From Him all beings come forth at the start of a cosmic age, and into Him they dissolve again when the age ends.", "te": "యుగారంభంలో సర్వ ప్రాణులూ ఆయన నుండే పుడతాయి; యుగాంతంలో మళ్ళీ ఆయనలోనే లయమవుతాయి.", "hi": "युग के आरंभ में सब प्राणी उन्हीं से उत्पन्न होते हैं और युग के अंत में फिर उन्हीं में लीन हो जाते हैं।" },
"vsn_purva_18": { "en": "O king, hear from me the thousand names of Viṣṇu — the foremost in the world, Lord of the universe — which remove sin and fear.", "te": "రాజా! లోకాలకు ప్రధానుడు, జగన్నాథుడు అయిన విష్ణువు సహస్ర నామాలను — పాపాన్నీ భయాన్నీ పోగొట్టేవాటిని — నా నుండి విను.", "hi": "हे राजन! लोकों में प्रधान, जगन्नाथ विष्णु के सहस्र नाम — जो पाप और भय को दूर करते हैं — मुझसे सुनो।" },
"vsn_purva_19": { "en": "Those names of the great one that arise from His qualities, that are well known and were sung by the ṛṣis — I shall tell them, for the good of all.", "te": "ఆ మహాత్ముని గుణాల నుండి పుట్టినవి, ప్రసిద్ధమైనవి, ఋషులు గానం చేసినవి అయిన నామాలను — అందరి శ్రేయస్సు కోసం — చెబుతాను.", "hi": "उन महात्मा के गुणों से बने, प्रसिद्ध, ऋषियों द्वारा गाए गए नामों को मैं सबके कल्याण के लिए कहूँगा।" },
"vsn_purva_20": { "en": "Of this hymn of a thousand names, the ṛṣi (seer) is the great sage Veda Vyāsa, the metre is anuṣṭubh, and the deity is the Lord, the son of Devakī.", "te": "ఈ సహస్రనామ స్తోత్రానికి ఋషి మహాముని వేదవ్యాసుడు, ఛందస్సు అనుష్టుప్, దేవత దేవకీ సుతుడైన భగవానుడు.", "hi": "इस सहस्रनाम के ऋषि महामुनि वेदव्यास हैं, छंद अनुष्टुप् है, और देवता देवकी-नंदन भगवान हैं।" },
"vsn_purva_21": { "en": "Its seed (bīja) is 'amṛtāṃśūdbhava', its power (śakti) is 'Devakīnandana', its heart is 'trisāmā'; it is chanted for peace.", "te": "దీనికి బీజం ‘అమృతాంశూద్భవః’, శక్తి ‘దేవకీనందనః’, హృదయం ‘త్రిసామా’; శాంతి కోసం దీనిని పఠిస్తారు.", "hi": "इसका बीज 'अमृतांशूद्भव', शक्ति 'देवकीनंदन' और हृदय 'त्रिसामा' है; शांति के लिए इसका पाठ किया जाता है।" },
"vsn_purva_22": { "en": "I bow to the Supreme Person — Viṣṇu, the victorious, the great Viṣṇu, the all-powerful, the great Lord, who takes many forms and destroys the demons.", "te": "విష్ణువు, జిష్ణువు (జయశీలుడు), మహావిష్ణువు, ప్రభవిష్ణువు, మహేశ్వరుడు, అనేక రూపాలు ధరించేవాడు, రాక్షసులను అంతం చేసేవాడు అయిన పురుషోత్తమునికి నమస్కరిస్తున్నాను.", "hi": "विष्णु, जिष्णु (विजयी), महाविष्णु, प्रभविष्णु, महेश्वर, अनेक रूपों वाले और दैत्यों का अंत करने वाले पुरुषोत्तम को मैं नमस्कार करता हूँ।" },
"vsn_dhyanam_1": { "en": "On the shore of the milk ocean, on sands sparkling with pure gems, seated on a throne of pearl garlands, His body adorned with crystal-like pearls, with white clouds above showering nectar — may Mukunda, holding discus, mace and conch, full of bliss, purify us.", "te": "పాలసముద్ర తీరంలో, నిర్మలమైన మణులతో మెరిసే ఇసుకపై, ముత్యాల మాలలతో అల్లిన ఆసనం మీద కూర్చుని, స్ఫటికాల వంటి ముత్యాలతో అలంకరించబడి, పైన అమృతాన్ని కురిపించే తెల్లని మేఘాలతో ఆనందంగా ఉన్న — చక్రం, గద, శంఖం ధరించిన — ముకుందుడు మమ్మల్ని పవిత్రం చేయుగాక.", "hi": "क्षीर-सागर के तट पर, शुद्ध मणियों से चमकती रेत पर, मोतियों की मालाओं से बने आसन पर बैठे, स्फटिक जैसे मोतियों से सजे, ऊपर अमृत बरसाते श्वेत बादलों के बीच आनंदमय — चक्र, गदा और शंख धारी — मुकुंद हमें पवित्र करें।" },
"vsn_dhyanam_2": { "en": "The earth is His feet, the sky His navel, the wind His breath, the moon and sun His eyes, the directions His ears, heaven His head, fire His mouth, the ocean His belly; within Him the whole universe of gods, humans, birds, cattle, serpents, gandharvas and daityas plays in wonder — I bow to Viṣṇu, the Lord whose body is the three worlds.", "te": "భూమి ఆయన పాదాలు, ఆకాశం నాభి, వాయువు ప్రాణం, చంద్రసూర్యులు కన్నులు, దిక్కులు చెవులు, స్వర్గం శిరస్సు, అగ్ని ముఖం, సముద్రం ఉదరం; దేవతలు, మనుషులు, పక్షులు, పశువులు, సర్పాలు, గంధర్వులు, దైత్యులతో కూడిన విశ్వమంతా ఆయనలోనే అద్భుతంగా విహరిస్తుంది — త్రిలోకాలే శరీరంగా గల ఈశ్వరుడైన విష్ణువుకు నమస్కరిస్తున్నాను.", "hi": "पृथ्वी जिनके चरण हैं, आकाश नाभि, वायु प्राण, चंद्र-सूर्य नेत्र, दिशाएँ कान, स्वर्ग सिर, अग्नि मुख और समुद्र उदर है; देवता, मनुष्य, पक्षी, पशु, सर्प, गंधर्व और दैत्यों सहित सारा विश्व जिनके भीतर अद्भुत रूप से रमता है — तीनों लोक जिनका शरीर हैं, उन ईश्वर विष्णु को मैं नमस्कार करता हूँ।" },
"vsn_dhyanam_3": { "en": "I bow to Viṣṇu — peaceful in form, resting on the serpent, with a lotus at His navel, Lord of the gods, support of the universe, vast as the sky, dark as a rain cloud, with auspicious limbs, beloved of Lakṣmī, lotus-eyed, reached by yogīs in meditation in their hearts, remover of the fear of worldly life, the one Lord of all worlds.", "te": "శాంత స్వరూపుడు, శేషశయనుడు, పద్మనాభుడు, దేవతల ప్రభువు, విశ్వానికి ఆధారం, ఆకాశం వంటివాడు, మేఘ వర్ణుడు, మంగళకరమైన అవయవాలు గలవాడు, లక్ష్మీకాంతుడు, కమలనయనుడు, యోగుల హృదయాలలో ధ్యానంతో అందేవాడు, సంసార భయాన్ని హరించేవాడు, సర్వలోకాలకు ఏకైక నాథుడు అయిన విష్ణువుకు నమస్కరిస్తున్నాను.", "hi": "शांत स्वरूप, शेषनाग पर शयन करने वाले, पद्मनाभ, देवताओं के स्वामी, विश्व के आधार, आकाश के समान व्यापक, मेघ के समान श्यामवर्ण, शुभ अंगों वाले, लक्ष्मीपति, कमलनयन, योगियों के हृदय में ध्यान से प्राप्त होने वाले, संसार-भय हरने वाले, सब लोकों के एकमात्र नाथ विष्णु को मैं वंदन करता हूँ।" },
"vsn_dhyanam_4": { "en": "I bow to Viṣṇu, the one Lord of all worlds — dark as a cloud, dressed in yellow silk, marked with the Śrīvatsa, His body shining with the Kaustubha gem, full of goodness, with long lotus eyes.", "te": "మేఘం వలె శ్యామ వర్ణుడు, పసుపు పట్టు వస్త్రం ధరించినవాడు, శ్రీవత్స చిహ్నం గలవాడు, కౌస్తుభ మణితో ప్రకాశించే శరీరం గలవాడు, పుణ్యమూర్తి, విశాలమైన కమల నయనాలు గలవాడు, సర్వలోకాలకు ఏకైక నాథుడు అయిన విష్ణువుకు నమస్కరిస్తున్నాను.", "hi": "मेघ के समान श्याम, पीले रेशमी वस्त्र पहने, श्रीवत्स चिह्न वाले, कौस्तुभ मणि से चमकते अंगों वाले, पुण्यमय, कमल जैसे विशाल नेत्रों वाले, सब लोकों के एकमात्र नाथ विष्णु को मैं वंदन करता हूँ।" },
"vsn_dhyanam_5": { "en": "Salutations to Viṣṇu, the all-powerful — the first being among all beings, the bearer of the earth, whose forms are many.", "te": "సర్వ ప్రాణులకూ ఆది అయినవాడు, భూమిని ధరించేవాడు, అనేక రూపాలు గలవాడు, సర్వ సమర్థుడు అయిన విష్ణువుకు నమస్కారం.", "hi": "सब प्राणियों के आदि, पृथ्वी को धारण करने वाले, अनेक रूपों वाले, सर्वसमर्थ विष्णु को नमस्कार।" },
"vsn_dhyanam_6": { "en": "With my head bowed I salute four-armed Viṣṇu — with conch and discus, crown and earrings, dressed in yellow, lotus-eyed, the Kaustubha gem shining on His garlanded chest.", "te": "శంఖ చక్రాలు, కిరీట కుండలాలు, పసుపు వస్త్రాలు ధరించినవాడు, పద్మాల వంటి కన్నులు గలవాడు, హారాలతో అలంకరించిన వక్షస్థలంపై కౌస్తుభం మెరిసేవాడు, నాలుగు భుజాలు గలవాడు అయిన విష్ణువుకు శిరస్సు వంచి నమస్కరిస్తున్నాను.", "hi": "शंख-चक्र, किरीट-कुंडल और पीतांबर धारण किए, कमलनयन, हारों से सजे वक्ष पर कौस्तुभ से सुशोभित, चतुर्भुज विष्णु को मैं सिर झुकाकर नमस्कार करता हूँ।" },
"vsn_dhyanam_7": { "en": "Seated on a golden throne in the shade of the Pārijāta tree, dark as a rain cloud, with long eyes, richly adorned —", "te": "పారిజాత వృక్షపు నీడలో బంగారు సింహాసనం మీద కూర్చున్నవాడు, మేఘం వలె శ్యామ వర్ణుడు, విశాల నేత్రుడు, అలంకారాలతో శోభిల్లేవాడు —", "hi": "पारिजात वृक्ष की छाया में स्वर्ण सिंहासन पर विराजमान, मेघ के समान श्याम, विशाल नेत्रों वाले, अलंकारों से सुशोभित —" },
"vsn_dhyanam_8": { "en": "— moon-faced, four-armed, His chest marked with the Śrīvatsa, together with Rukmiṇī and Satyabhāmā — in that Kṛṣṇa I take refuge.", "te": "— చంద్రుని వంటి ముఖం, నాలుగు భుజాలు, శ్రీవత్స చిహ్నం గల వక్షస్థలం గలవాడు, రుక్మిణీ సత్యభామలతో కూడినవాడు అయిన శ్రీకృష్ణుని నేను ఆశ్రయిస్తున్నాను.", "hi": "— चंद्रमुख, चतुर्भुज, श्रीवत्स-चिह्नित वक्ष वाले, रुक्मिणी और सत्यभामा सहित श्रीकृष्ण की मैं शरण लेता हूँ।" },
"vsn_1_1": { "en": "The Lord who is the whole universe, who pervades it, and who rules past, present and future.", "te": "విశ్వమంతా తానే అయి, అంతటా వ్యాపించి, భూత భవిష్యత్ వర్తమానాలను పాలించే ప్రభువు.", "hi": "जो स्वयं सारा विश्व हैं, सबमें व्याप्त हैं, और भूत, भविष्य, वर्तमान के स्वामी हैं।", "names": [["viśvam", "విశ్వం", "The whole universe — all that exists is He", "విశ్వమంతా తానే అయినవాడు", "जो स्वयं संपूर्ण विश्व हैं"], ["viṣṇuḥ", "విష్ణుః", "The all-pervading one", "అంతటా వ్యాపించినవాడు", "जो सर्वत्र व्याप्त हैं"], ["vaṣaṭkāraḥ", "వషట్కారః", "The one for whom the sacred call 'vaṣaṭ' is made in yajña", "యజ్ఞంలో ‘వషట్’ అని ఎవరికి హవిస్సు అర్పిస్తారో ఆయన", "यज्ञ में जिनके लिए 'वषट्' कहकर आहुति दी जाती है"], ["bhūta-bhavya-bhavat-prabhuḥ", "భూతభవ్యభవత్ప్రభుః", "Lord of past, future and present", "భూత, భవిష్యత్, వర్తమానాలకు ప్రభువు", "भूत, भविष्य और वर्तमान के स्वामी"], ["bhūtakṛt", "భూతకృత్", "Creator of all beings", "సర్వ ప్రాణులను సృష్టించినవాడు", "सब प्राणियों के रचयिता"], ["bhūtabhṛt", "భూతభృత్", "Sustainer of all beings", "సర్వ ప్రాణులను పోషించేవాడు", "सब प्राणियों का पालन करने वाले"], ["bhāvaḥ", "భావః", "Pure existence — the being of all that is", "సమస్తమూ తానై ఉన్న సత్తా", "शुद्ध सत्ता — सबका अस्तित्व"], ["bhūtātmā", "భూతాత్మా", "The inner Self of all beings", "సర్వ ప్రాణులకూ అంతరాత్మ", "सब प्राणियों की अंतरात्मा"], ["bhūtabhāvanaḥ", "భూతభావనః", "The one who brings beings into being and nurtures them", "ప్రాణులను పుట్టించి వృద్ధిపరిచేవాడు", "प्राणियों को उत्पन्न करके बढ़ाने वाले"]] },
"vsn_2_2": { "en": "The pure Self, the supreme Self, the final goal of the liberated — the witness within who never perishes.", "te": "పవిత్రమైన ఆత్మ, పరమాత్మ, ముక్తులకు చివరి గమ్యం — ఎన్నటికీ నశించని అంతర్ సాక్షి.", "hi": "शुद्ध आत्मा, परमात्मा, मुक्तों की परम गति — भीतर का साक्षी जो कभी नष्ट नहीं होता।", "names": [["pūtātmā", "పూతాత్మా", "The pure Self, untouched by any impurity", "ఏ మాలిన్యమూ అంటని పవిత్ర ఆత్మ", "जिन्हें कोई मल नहीं छूता, ऐसे शुद्ध आत्मा"], ["paramātmā", "పరమాత్మా", "The Supreme Self", "పరమాత్మ — అన్నిటికంటే ఉన్నతమైన ఆత్మ", "परमात्मा — सर्वोच्च आत्मा"], ["muktānāṃ paramā gatiḥ", "ముక్తానాం పరమాగతిః", "The highest goal of the liberated", "ముక్తులు చేరే అత్యున్నత గమ్యం", "मुक्त आत्माओं की परम गति"], ["avyayaḥ", "అవ్యయః", "The one who never decays", "క్షయం లేనివాడు", "जिनका कभी क्षय नहीं होता"], ["puruṣaḥ", "పురుషః", "The one who dwells in every body (pura)", "ప్రతి శరీరమనే పురంలో నివసించేవాడు", "हर शरीर रूपी पुर में निवास करने वाले"], ["sākṣī", "సాక్షీ", "The witness who sees everything", "అన్నిటినీ చూసే సాక్షి", "सब कुछ देखने वाले साक्षी"], ["kṣetrajñaḥ", "క్షేత్రజ్ఞః", "Knower of the field — the body and mind", "క్షేత్రాన్ని (దేహాన్ని, మనసును) తెలిసినవాడు", "क्षेत्र (शरीर और मन) को जानने वाले"], ["akṣaraḥ", "అక్షరః", "The Imperishable", "నాశనం లేనివాడు", "अविनाशी"]] },
"vsn_3_3": { "en": "He is yoga itself and the leader of yogīs, Lord of nature and spirit, who took the form of Narasiṃha, the glorious Keśava, the highest of beings.", "te": "యోగమే తానైనవాడు, యోగవేత్తలకు నాయకుడు, ప్రకృతి పురుషులకు ఈశ్వరుడు, నరసింహ రూపం ధరించినవాడు, శ్రీమంతుడైన కేశవుడు, పురుషోత్తముడు.", "hi": "जो स्वयं योग हैं, योगियों के नेता हैं, प्रकृति और पुरुष के ईश्वर हैं, नरसिंह रूप धारी, श्रीमान केशव, पुरुषोत्तम।", "names": [["yogaḥ", "యోగః", "Yoga itself — the means of reaching Him", "యోగమే తానైనవాడు — ఆయనను చేరే మార్గం", "स्वयं योग — उन्हें पाने का साधन"], ["yogavidāṃ netā", "యోగవిదాం నేతా", "Leader and guide of those who know yoga", "యోగవేత్తలకు నాయకుడు, మార్గదర్శి", "योग जानने वालों के नेता और मार्गदर्शक"], ["pradhāna-puruṣeśvaraḥ", "ప్రధానపురుషేశ్వరః", "Lord of matter (prakṛti) and of souls", "ప్రకృతికీ జీవులకూ ఈశ్వరుడు", "प्रकृति और जीवों के स्वामी"], ["nārasiṃhavapuḥ", "నారసింహవపుః", "The one who took the man-lion form", "నరసింహ రూపం ధరించినవాడు", "नरसिंह रूप धारण करने वाले"], ["śrīmān", "శ్రీమాన్", "The one with whom Śrī (Lakṣmī) ever dwells", "శ్రీ (లక్ష్మీదేవి) ఎల్లప్పుడూ తనతో ఉండేవాడు", "जिनके साथ श्री (लक्ष्मी) सदा रहती हैं"], ["keśavaḥ", "కేశవః", "The one with beautiful hair; also, Lord of Brahmā and Śiva", "అందమైన కేశాలు గలవాడు; బ్రహ్మ రుద్రులకు ప్రభువు", "सुंदर केशों वाले; ब्रह्मा और शिव के भी स्वामी"], ["puruṣottamaḥ", "పురుషోత్తమః", "The highest of all beings", "పురుషులందరిలో ఉత్తముడు", "सब पुरुषों में उत्तम"]] },
"vsn_4_4": { "en": "He is everything and the destroyer of all, the auspicious one, the unmoving, the source of beings, the treasure that never runs out. He manifests Himself, sustains all and rules all.", "te": "సమస్తమూ తానే, అన్నిటినీ లయం చేసేవాడు, మంగళకరుడు, స్థిరుడు, ప్రాణులకు మూలం, ఎన్నటికీ తరగని నిధి. తనను తాను వ్యక్తం చేసుకుని, అన్నిటినీ భరించి, పాలించేవాడు.", "hi": "वे सब कुछ हैं, सबका संहार करने वाले, मंगलमय, अचल, प्राणियों के आदि कारण, कभी न घटने वाला कोष। स्वयं प्रकट होने वाले, सबका भरण करने वाले और सबके शासक।", "names": [["sarvaḥ", "సర్వః", "All — everything that is", "సమస్తమూ తానే అయినవాడు", "जो सब कुछ हैं"], ["śarvaḥ", "శర్వః", "The one who withdraws all at the end", "ప్రళయంలో అన్నిటినీ లయం చేసేవాడు", "प्रलय में सबका संहार करने वाले"], ["śivaḥ", "శివః", "The auspicious, the pure", "మంగళకరుడు, నిర్మలుడు", "मंगलमय, शुद्ध"], ["sthāṇuḥ", "స్థాణుః", "The firm, unmoving one", "స్థిరంగా, అచలంగా ఉండేవాడు", "स्थिर, अचल"], ["bhūtādiḥ", "భూతాదిః", "The origin of all beings", "సర్వ భూతాలకూ ఆది", "सब भूतों के आदि कारण"], ["nidhir avyayaḥ", "నిధిరవ్యయః", "The imperishable treasure", "ఎన్నటికీ తరగని నిధి", "अक्षय निधि"], ["sambhavaḥ", "సంభవః", "The one who is born of His own will (as avatāras)", "తన ఇష్టంతో అవతారాలుగా పుట్టేవాడు", "अपनी इच्छा से अवतार लेने वाले"], ["bhāvanaḥ", "భావనః", "The giver of the fruits of action", "కర్మ ఫలాలను ఇచ్చేవాడు", "कर्मों का फल देने वाले"], ["bhartā", "భర్తా", "The supporter of all", "అన్నిటినీ భరించేవాడు", "सबका भरण-पोषण करने वाले"], ["prabhavaḥ", "ప్రభవః", "The source from which everything comes", "సమస్తమూ పుట్టిన మూలం", "जिनसे सब उत्पन्न होता है"], ["prabhuḥ", "ప్రభుః", "The all-powerful master", "సర్వ సమర్థుడైన ప్రభువు", "सर्वशक्तिमान स्वामी"], ["īśvaraḥ", "ఈశ్వరః", "The ruler of all", "అన్నిటినీ శాసించేవాడు", "सबके शासक ईश्वर"]] },
"vsn_5_5": { "en": "Self-existent, the giver of joy, the radiant sun, lotus-eyed, with a mighty voice; without beginning or end, the creator and arranger of all — the best of all supports.", "te": "తనంతట తానే ఉన్నవాడు, సుఖాన్ని ఇచ్చేవాడు, సూర్యుని వలె ప్రకాశించేవాడు, పద్మాల వంటి కన్నులు గలవాడు, గంభీరమైన నాదం గలవాడు; ఆది అంతం లేనివాడు, సృష్టికర్త, విధాత — ఆధారాలన్నిటిలో ఉత్తముడు.", "hi": "स्वयंभू, सुख देने वाले, सूर्य के समान प्रकाशमान, कमल-नयन, महान नाद वाले; आदि-अंत रहित, सृष्टिकर्ता और विधाता — सब आधारों में श्रेष्ठ।", "names": [["svayambhūḥ", "స్వయంభూః", "Self-existent — born of no one", "ఎవరి వల్లా పుట్టక తనంతట తానే ఉన్నవాడు", "स्वयं से प्रकट, किसी से उत्पन्न नहीं"], ["śambhuḥ", "శంభుః", "The one who brings happiness to devotees", "భక్తులకు సుఖం కలిగించేవాడు", "भक्तों को सुख देने वाले"], ["ādityaḥ", "ఆదిత్యః", "The golden being in the sun; son of Aditi as Vāmana", "సూర్యమండలంలోని దివ్య పురుషుడు; వామనుడిగా అదితి కుమారుడు", "सूर्यमंडल के दिव्य पुरुष; वामन रूप में अदिति के पुत्र"], ["puṣkarākṣaḥ", "పుష్కరాక్షః", "Lotus-eyed", "పద్మాల వంటి కన్నులు గలవాడు", "कमल जैसे नेत्रों वाले"], ["mahāsvanaḥ", "మహాస్వనః", "The one whose great sound is the Veda", "వేదమే గొప్ప నాదంగా గలవాడు", "जिनका महान नाद वेद है"], ["anādi-nidhanaḥ", "అనాదినిధనః", "Without beginning or end", "ఆది అంతం లేనివాడు", "आदि और अंत से रहित"], ["dhātā", "ధాతా", "The supporter of the world", "లోకాన్ని ధరించేవాడు", "जगत को धारण करने वाले"], ["vidhātā", "విధాతా", "The one who ordains — who gives each action its result", "కర్మలకు ఫలాన్ని నిర్ణయించేవాడు", "कर्मों का फल विधान करने वाले"], ["dhātur uttamaḥ", "ధాతురుత్తమః", "Greater even than Brahmā, the creator", "సృష్టికర్త అయిన బ్రహ్మ కంటే ఉత్తముడు", "सृष्टिकर्ता ब्रह्मा से भी श्रेष्ठ"]] },
"vsn_6_6": { "en": "The immeasurable Lord of the senses, lotus-navelled master of the gods; the maker and shaper of the world, vast, ancient and unchanging.", "te": "కొలతకు అందనివాడు, ఇంద్రియాలకు ప్రభువు, పద్మనాభుడు, దేవతల ప్రభువు; విశ్వాన్ని సృష్టించి తీర్చిదిద్దేవాడు, అతి విశాలుడు, సనాతనుడు, స్థిరుడు.", "hi": "अप्रमेय, इंद्रियों के स्वामी, पद्मनाभ, देवताओं के प्रभु; विश्व के रचयिता और गढ़ने वाले, विराट, सनातन और अचल।", "names": [["apramēyaḥ", "అప్రమేయః", "Beyond all measure and proof", "ఏ ప్రమాణానికీ అందనివాడు", "किसी प्रमाण से न मापे जा सकने वाले"], ["hṛṣīkēśaḥ", "హృషీకేశః", "Lord of the senses", "ఇంద్రియాలకు ప్రభువు", "इंद्रियों के स्वामी"], ["padmanābhaḥ", "పద్మనాభః", "The one from whose navel the lotus of creation grows", "నాభిలో సృష్టి పద్మం గలవాడు", "जिनकी नाभि से सृष्टि-कमल निकला"], ["amaraprabhuḥ", "అమరప్రభుః", "Master of the immortals (gods)", "దేవతలకు ప్రభువు", "देवताओं के स्वामी"], ["viśvakarmā", "విశ్వకర్మా", "Maker of the universe", "విశ్వాన్ని సృష్టించినవాడు", "विश्व के रचयिता"], ["manuḥ", "మనుః", "The thinker; the one who holds the Veda in mind", "మననం చేసేవాడు", "मनन करने वाले"], ["tvaṣṭā", "త్వష్టా", "The one who shapes all forms (and dissolves them)", "రూపాలను తీర్చిదిద్దేవాడు", "सब रूपों को गढ़ने वाले"], ["sthaviṣṭhaḥ", "స్థవిష్ఠః", "The most vast", "అతి స్థూలుడు, అతి విశాలుడు", "अत्यंत विशाल"], ["sthaviraḥ dhruvaḥ", "స్థవిరః ధ్రువః", "The ancient, the ever-steady", "పురాతనుడు, స్థిరుడు", "प्राचीन और अचल"]] },
"vsn_7_7": { "en": "He cannot be grasped by the senses; eternal, dark and all-attractive, red-eyed, the destroyer at the end; full of glory, the support of the three worlds, the purifier, the highest auspiciousness.", "te": "ఇంద్రియాలకు అందనివాడు; శాశ్వతుడు, కృష్ణుడు, ఎర్రని కన్నులవాడు, ప్రళయంలో సంహరించేవాడు; ఐశ్వర్యంతో నిండినవాడు, మూడు లోకాలకు ఆధారం, పవిత్రుడు, పరమ మంగళం.", "hi": "इंद्रियों से न पकड़े जाने वाले; शाश्वत, कृष्ण, लाल नेत्रों वाले, प्रलय में संहार करने वाले; ऐश्वर्य से परिपूर्ण, तीनों लोकों के आधार, पवित्र और परम मंगल।", "names": [["agrāhyaḥ", "అగ్రాహ్యః", "The one the senses cannot grasp", "ఇంద్రియాలకు అందనివాడు", "इंद्रियों की पकड़ से परे"], ["śāśvataḥ", "శాశ్వతః", "The eternal", "శాశ్వతుడు", "शाश्वत"], ["kṛṣṇaḥ", "కృష్ణః", "The dark one; also, existence and bliss together", "నల్లనివాడు; సచ్చిదానందుడు", "श्याम वर्ण वाले; सत्-आनंद स्वरूप"], ["lōhitākṣaḥ", "లోహితాక్షః", "Red-eyed", "ఎర్రని కన్నులవాడు", "लाल नेत्रों वाले"], ["pratardanaḥ", "ప్రతర్దనః", "Destroyer at the time of dissolution", "ప్రళయంలో సంహరించేవాడు", "प्रलय में संहार करने वाले"], ["prabhūtaḥ", "ప్రభూతః", "Full of every greatness", "అన్ని మహిమలతో నిండినవాడు", "सब ऐश्वर्यों से पूर्ण"], ["trikakubdhāma", "త్రికకుబ్ధామ", "Support of the three regions (above, middle, below)", "మూడు దిక్కులకు (లోకాలకు) ఆధారం", "तीनों दिशाओं (लोकों) के आधार"], ["pavitram", "పవిత్రం", "The purifier", "పవిత్రం చేసేవాడు", "पवित्र करने वाले"], ["maṅgaḻaṃ param", "మంగళం పరం", "The highest auspiciousness", "పరమ మంగళం", "परम मंगल"]] },
"vsn_8_8": { "en": "The ruler of all, giver of life and life itself; the eldest, the best, lord of creatures; the golden womb of creation and the womb of the earth; Lakṣmī's lord, the slayer of Madhu.", "te": "అందరినీ శాసించేవాడు, ప్రాణం ఇచ్చేవాడు, ప్రాణమే తానైనవాడు; జ్యేష్ఠుడు, శ్రేష్ఠుడు, ప్రజాపతి; హిరణ్యగర్భుడు, భూమిని గర్భంలో ధరించినవాడు; లక్ష్మీపతి, మధు అనే రాక్షసుణ్ణి సంహరించినవాడు.", "hi": "सबके शासक, प्राण देने वाले और स्वयं प्राण; सबसे ज्येष्ठ, सबसे श्रेष्ठ, प्रजापति; हिरण्यगर्भ, पृथ्वी को गर्भ में धारण करने वाले; लक्ष्मीपति, मधु दैत्य के संहारक।", "names": [["īśānaḥ", "ఈశానః", "The ruler of all", "అన్నిటినీ శాసించేవాడు", "सबके शासक"], ["prāṇadaḥ", "ప్రాణదః", "Giver of life", "ప్రాణం ఇచ్చేవాడు", "प्राण देने वाले"], ["prāṇaḥ", "ప్రాణః", "Life itself", "ప్రాణమే తానైనవాడు", "स्वयं प्राण"], ["jyēṣṭhaḥ", "జ్యేష్ఠః", "The eldest", "అందరికంటే పెద్దవాడు", "सबसे ज्येष्ठ"], ["śrēṣṭhaḥ", "శ్రేష్ఠః", "The best, most praiseworthy", "అత్యంత శ్రేష్ఠుడు", "सबसे श्रेष्ठ"], ["prajāpatiḥ", "ప్రజాపతిః", "Lord of all creatures", "సర్వ ప్రాణులకు పతి", "सब प्राणियों के स्वामी"], ["hiraṇyagarbhaḥ", "హిరణ్యగర్భః", "The golden womb from which creation comes", "సృష్టి పుట్టే బంగారు గర్భం", "स्वर्णिम गर्भ, जिससे सृष्टि होती है"], ["bhūgarbhaḥ", "భూగర్భః", "The one who holds the earth within Him", "భూమిని తనలో ధరించినవాడు", "पृथ्वी को अपने भीतर धारण करने वाले"], ["mādhavaḥ", "మాధవః", "Lord of Mā (Lakṣmī); also, known through silent meditation", "లక్ష్మీపతి; మౌన ధ్యానంతో తెలియబడేవాడు", "लक्ष्मीपति; मौन ध्यान से जाने जाने वाले"], ["madhusūdanaḥ", "మధుసూదనః", "Slayer of the demon Madhu", "మధు రాక్షసుణ్ణి సంహరించినవాడు", "मधु दैत्य का वध करने वाले"]] },
"vsn_9_9": { "en": "The all-powerful Lord, valiant archer, wise; the one whose stride covered the worlds, who pervades all; unsurpassed, unconquerable, grateful, the very action, and the master of Himself.", "te": "సర్వ సమర్థుడైన ఈశ్వరుడు, పరాక్రమశాలి, ధనుర్ధారి, మేధావి; లోకాలను అడుగులతో కొలిచినవాడు, అంతటా వ్యాపించినవాడు; సాటిలేనివాడు, జయించశక్యం కానివాడు, కృతజ్ఞుడు, కర్మ స్వరూపుడు, ఆత్మవంతుడు.", "hi": "सर्वसमर्थ ईश्वर, पराक्रमी धनुर्धर, मेधावी; जिनके पगों ने लोकों को नापा, जो सर्वत्र व्याप्त हैं; अनुपम, अजेय, कृतज्ञ, कर्म-स्वरूप और आत्मवान।", "names": [["īśvaraḥ", "ఈశ్వరః", "The all-powerful Lord", "సర్వ సమర్థుడైన ఈశ్వరుడు", "सर्वसमर्थ ईश्वर"], ["vikramī", "విక్రమీ", "Full of valour", "పరాక్రమశాలి", "पराक्रमी"], ["dhanvī", "ధన్వీ", "The archer (as Rāma)", "ధనుస్సు ధరించినవాడు (శ్రీరాముడు)", "धनुर्धर (श्रीराम)"], ["mēdhāvī", "మేధావీ", "Of great intelligence", "గొప్ప మేధ గలవాడు", "महान बुद्धि वाले"], ["vikramaḥ", "విక్రమః", "The one who strode across the worlds (as Vāmana)", "లోకాలను అడుగులతో కొలిచినవాడు (వామనుడు)", "लोकों को पगों से नापने वाले (वामन)"], ["kramaḥ", "క్రమః", "The one who pervades everything", "అంతటా వ్యాపించినవాడు", "सबमें व्याप्त"], ["anuttamaḥ", "అనుత్తమః", "The one with none higher", "తనకంటే ఉత్తముడు లేనివాడు", "जिनसे उत्तम कोई नहीं"], ["durādharṣaḥ", "దురాధర్షః", "The one no one can overpower", "ఎవరూ ఎదిరించలేనివాడు", "जिन्हें कोई दबा न सके"], ["kṛtajñaḥ", "కృతజ్ఞః", "Knower of all deeds; grateful even for a small offering", "చేసినది గుర్తుంచుకునేవాడు; చిన్న అర్పణకూ కృతజ్ఞుడు", "किए हुए को जानने वाले; छोटी भेंट से भी प्रसन्न"], ["kṛtiḥ", "కృతిః", "Action itself; the effort behind every deed", "కర్మ స్వరూపుడు", "स्वयं कर्म-स्वरूप"], ["ātmavān", "ఆత్మవాన్", "Established in His own glory", "తన మహిమలోనే నిలిచినవాడు", "अपनी ही महिमा में स्थित"]] },
"vsn_10_10": { "en": "Lord of the gods, the refuge, bliss itself, seed of the universe and source of all creatures; He is the day, the year, the serpent hard to grasp, knowledge itself, and the one who sees all.", "te": "దేవతల ప్రభువు, శరణం, ఆనంద స్వరూపుడు, విశ్వానికి బీజం, ప్రజల పుట్టుకకు కారణం; ఆయనే పగలు, సంవత్సరం, పట్టుకోలేని సర్పం, జ్ఞాన స్వరూపం, అన్నిటినీ చూసేవాడు.", "hi": "देवताओं के स्वामी, शरण, आनंद-स्वरूप, विश्व के बीज, प्रजा के उत्पत्ति-स्थान; वही दिन हैं, वर्ष हैं, पकड़ में न आने वाले सर्प हैं, ज्ञान-स्वरूप और सब कुछ देखने वाले हैं।", "names": [["surēśaḥ", "సురేశః", "Lord of the gods", "దేవతల ప్రభువు", "देवताओं के स्वामी"], ["śaraṇam", "శరణం", "The refuge of all in distress", "ఆపదలో ఉన్నవారికి శరణం", "दुःखियों की शरण"], ["śarma", "శర్మ", "Supreme bliss", "పరమానందం", "परम आनंद"], ["viśvarētāḥ", "విశ్వరేతాః", "Seed of the universe", "విశ్వానికి బీజం", "विश्व के बीज"], ["prajābhavaḥ", "ప్రజాభవః", "The one from whom all creatures arise", "ప్రాణులు పుట్టే మూలం", "जिनसे सब प्रजा उत्पन्न होती है"], ["ahaḥ", "అహః", "The day — bright like daylight", "పగటి వలె ప్రకాశించేవాడు", "दिन के समान प्रकाशमान"], ["saṃvatsaraḥ", "సంవత్సరః", "The year — the form of time", "కాల స్వరూపుడైన సంవత్సరం", "काल-रूप वर्ष"], ["vyāḻaḥ", "వ్యాళః", "Like a great serpent, impossible to grasp", "పట్టుకోలేని మహాసర్పం వంటివాడు", "पकड़ में न आने वाले महासर्प जैसे"], ["pratyayaḥ", "ప్రత్యయః", "Knowledge itself; the one who can be trusted", "జ్ఞాన స్వరూపుడు; నమ్మదగినవాడు", "ज्ञान-स्वरूप; विश्वसनीय"], ["sarvadarśanaḥ", "సర్వదర్శనః", "The one whose eyes are everywhere", "అంతటా కన్నులు గలవాడు", "सर्वत्र दृष्टि वाले"]] },
"vsn_11_11": { "en": "Unborn Lord of all, perfect and the goal of all striving, the beginning of all and never falling from His nature; the bearer of dharma, immeasurable, reached through every path of yoga.", "te": "పుట్టుక లేనివాడు, సర్వేశ్వరుడు, సిద్ధుడు, సిద్ధి (ఫలం) తానే, అందరికీ ఆది, తన స్వరూపం నుండి జారనివాడు; ధర్మ స్వరూపుడు, అపరిమితుడు, అన్ని యోగ మార్గాలతో చేరదగినవాడు.", "hi": "अजन्मा, सर्वेश्वर, सिद्ध, स्वयं सिद्धि (फल), सबके आदि, अपने स्वरूप से कभी न गिरने वाले; धर्म-स्वरूप, अपरिमेय, सब योग-मार्गों से प्राप्त होने वाले।", "names": [["ajaḥ", "అజః", "Unborn", "పుట్టుక లేనివాడు", "अजन्मा"], ["sarvēśvaraḥ", "సర్వేశ్వరః", "Lord of all lords", "సర్వేశ్వరుడు", "सबके ईश्वर"], ["siddhaḥ", "సిద్ధః", "Ever perfect, already accomplished", "నిత్య సిద్ధుడు", "नित्य सिद्ध"], ["siddhiḥ", "సిద్ధిః", "The fulfilment, the goal itself", "సిద్ధి — ఫలమే తానైనవాడు", "स्वयं सिद्धि — परम फल"], ["sarvādiḥ", "సర్వాదిః", "The beginning of everything", "అన్నిటికీ ఆది", "सबके आदि"], ["achyutaḥ", "అచ్యుతః", "The one who never falls from His glory", "తన మహిమ నుండి ఎన్నడూ జారనివాడు", "जो अपनी महिमा से कभी च्युत नहीं होते"], ["vṛṣākapiḥ", "వృషాకపిః", "The one who is dharma and who lifted the earth (as Varāha)", "ధర్మ స్వరూపుడు, భూమిని ఉద్ధరించినవాడు (వరాహుడు)", "धर्म-स्वरूप, पृथ्वी के उद्धारक (वराह)"], ["amēyātmā", "అమేయాత్మా", "Whose nature cannot be measured", "కొలవలేని స్వరూపం గలవాడు", "जिनका स्वरूप मापा नहीं जा सकता"], ["sarvayōgavinissṛtaḥ", "సర్వయోగవినిస్సృతః", "Known through every path of yoga; free of all ties", "అన్ని యోగాలతో తెలియబడేవాడు; అన్ని బంధాలకు అతీతుడు", "सब योगों से जाने जाने वाले; सब बंधनों से मुक्त"]] },
"vsn_12_12": { "en": "He dwells in all and all dwell in Him; generous-minded, truth itself, the same in all, measured and yet beyond measure; His acts are never in vain; lotus-eyed, dharma in deed and dharma in form.", "te": "అందరిలో నివసించేవాడు, అందరూ ఆయనలో నివసిస్తారు; ఉదార మనస్కుడు, సత్య స్వరూపుడు, అందరిలో సమంగా ఉండేవాడు; ఆయన కర్మలు ఎప్పుడూ వ్యర్థం కావు; కమల నయనుడు, ధర్మమే కర్మగా, ధర్మమే రూపంగా గలవాడు.", "hi": "जो सबमें बसते हैं और सब जिनमें बसते हैं; उदार मन वाले, सत्य-स्वरूप, सबमें सम; जिनके कर्म कभी व्यर्थ नहीं होते; कमलनयन, धर्म ही जिनका कर्म और धर्म ही जिनका रूप है।", "names": [["vasuḥ", "వసుః", "The one who dwells in all, and in whom all dwell", "అందరిలో వసించేవాడు; అందరూ ఆయనలో వసిస్తారు", "जो सबमें बसते हैं, सब जिनमें बसते हैं"], ["vasumanāḥ", "వసుమనాః", "Rich-hearted, of generous mind", "ఉదార మనస్కుడు", "उदार मन वाले"], ["satyaḥ", "సత్యః", "Truth itself", "సత్య స్వరూపుడు", "स्वयं सत्य"], ["samātmā", "సమాత్మా", "The same Self in all", "అందరిలో ఒకే ఆత్మగా ఉన్నవాడు", "सबमें एक समान आत्मा"], ["sammitaḥ", "సమ్మితః", "Known and measured by the scriptures", "శాస్త్రాలతో తెలియబడేవాడు", "शास्त्रों से जाने जाने वाले"], ["samaḥ", "సమః", "Always even, undisturbed", "ఎప్పుడూ సమంగా ఉండేవాడు", "सदा सम, अविचलित"], ["amōghaḥ", "అమోఘః", "The one whose acts never fail", "ఎన్నడూ వ్యర్థం కాని కర్మలు గలవాడు", "जिनके कर्म कभी विफल नहीं होते"], ["puṇḍarīkākṣaḥ", "పుండరీకాక్షః", "Lotus-eyed; seen in the lotus of the heart", "కమలాల వంటి కన్నులవాడు; హృదయ కమలంలో దర్శనమిచ్చేవాడు", "कमलनयन; हृदय-कमल में दिखने वाले"], ["vṛṣakarmā", "వృషకర్మా", "Whose every act is dharma", "ధర్మమే కర్మగా గలవాడు", "जिनका हर कर्म धर्म है"], ["vṛṣākṛtiḥ", "వృషాకృతిః", "Who takes form to uphold dharma", "ధర్మం కోసం రూపం ధరించేవాడు", "धर्म के लिए रूप धारण करने वाले"]] },
"vsn_13_13": { "en": "He makes the wicked weep, has countless heads, bears the worlds, is the source of the universe and of pure renown; immortal, eternal and unmoving, the best of goals, of mighty tapas.", "te": "దుష్టులను ఏడిపించే రుద్రుడు, అనేక శిరస్సులవాడు, లోకాలను భరించేవాడు, విశ్వానికి మూలం, పవిత్రమైన కీర్తి గలవాడు; అమృతుడు, శాశ్వతుడు, స్థిరుడు, శ్రేష్ఠమైన గమ్యం, మహాతపస్వి.", "hi": "दुष्टों को रुलाने वाले रुद्र, अनेक सिरों वाले, लोकों का भरण करने वाले, विश्व के मूल, पवित्र कीर्ति वाले; अमृत, शाश्वत और अचल, श्रेष्ठ गंतव्य, महान तपस्वी।", "names": [["rudraḥ", "రుద్రః", "The one who makes all weep at the end; who removes sorrow", "ప్రళయంలో అందరినీ ఏడిపించేవాడు; దుఃఖాన్ని పోగొట్టేవాడు", "प्रलय में सबको रुलाने वाले; दुःख हरने वाले"], ["bahuśirāḥ", "బహుశిరాః", "Many-headed", "అనేక శిరస్సులు గలవాడు", "अनेक सिरों वाले"], ["babhruḥ", "బభ్రుః", "The one who bears the worlds", "లోకాలను భరించేవాడు", "लोकों का भरण करने वाले"], ["viśvayōniḥ", "విశ్వయోనిః", "Source of the universe", "విశ్వానికి మూలం", "विश्व के उद्गम"], ["śuchiśravāḥ", "శుచిశ్రవాః", "Whose names are pure to hear", "వినడానికి పవిత్రమైన నామాలు గలవాడు", "जिनके नाम सुनने में पवित्र हैं"], ["amṛtaḥ", "అమృతః", "Deathless", "మరణం లేనివాడు", "अमर"], ["śāśvatasthāṇuḥ", "శాశ్వతస్థాణుః", "Eternal and unmoving", "శాశ్వతుడు, స్థిరుడు", "शाश्वत और अचल"], ["varārōhaḥ", "వరారోహః", "The highest goal to climb to", "అత్యుత్తమ గమ్యం", "सर्वोत्तम गंतव्य"], ["mahātapāḥ", "మహాతపాః", "Of great tapas (knowledge and power)", "గొప్ప తపస్సు గలవాడు", "महान तप वाले"]] },
"vsn_14_14": { "en": "He goes everywhere and knows everything, shining like the sun; leader of the hosts, the one devotees pray to; He is the Veda and its knower, flawless, with the Vedāṅgas as His limbs, the seer.", "te": "అంతటా ఉండేవాడు, అన్నీ తెలిసినవాడు, సూర్యుని వలె ప్రకాశించేవాడు; సేనలను నడిపించేవాడు, భక్తులు ప్రార్థించేవాడు; వేదమే తానై, వేదాన్ని తెలిసినవాడు, లోపం లేనివాడు, వేదాంగాలే అవయవాలుగా గలవాడు, కవి.", "hi": "सर्वत्र जाने वाले, सब कुछ जानने वाले, सूर्य के समान प्रकाशमान; सेनाओं के नायक, भक्त जिनसे प्रार्थना करते हैं; स्वयं वेद, वेद के ज्ञाता, दोष-रहित, वेदांग जिनके अंग हैं, कवि।", "names": [["sarvagaḥ", "సర్వగః", "Present everywhere", "అంతటా ఉండేవాడు", "सर्वत्र विद्यमान"], ["sarvavit", "సర్వవిత్", "All-knowing", "సర్వజ్ఞుడు", "सर्वज्ञ"], ["bhānuḥ", "భానుః", "The shining one", "ప్రకాశించేవాడు", "प्रकाशमान"], ["viṣvaksēnaḥ", "విష్వక్సేనః", "Before whom the enemy armies scatter", "ఆయన ఎదుట శత్రు సేనలు చెల్లాచెదురవుతాయి", "जिनके सामने शत्रु-सेना बिखर जाती है"], ["janārdanaḥ", "జనార్దనః", "The one people pray to; who punishes the wicked", "ప్రజలు ప్రార్థించేవాడు; దుష్టులను శిక్షించేవాడు", "जिनसे लोग याचना करते हैं; दुष्टों को दंड देने वाले"], ["vēdaḥ", "వేదః", "The Veda itself", "వేదమే తానైనవాడు", "स्वयं वेद"], ["vēdavit", "వేదవిత్", "Knower of the Veda", "వేదాన్ని తెలిసినవాడు", "वेद के ज्ञाता"], ["avyaṅgaḥ", "అవ్యంగః", "Without any defect", "ఏ లోపమూ లేనివాడు", "किसी कमी से रहित"], ["vēdāṅgaḥ", "వేదాంగః", "Whose limbs are the Vedāṅgas", "వేదాంగాలే అవయవాలుగా గలవాడు", "वेदांग जिनके अंग हैं"], ["vēdavit", "వేదవిత్", "The one who reflects on the Veda's meaning", "వేదార్థాన్ని విచారించేవాడు", "वेद के अर्थ का विचार करने वाले"], ["kaviḥ", "కవిః", "The seer who sees all", "అన్నిటినీ చూసే కవి (ద్రష్ట)", "सब कुछ देखने वाले कवि (द्रष्टा)"]] },
"vsn_15_15": { "en": "He oversees the worlds, the gods and dharma; He is both cause and effect; four in self, four in manifestation, four-tusked and four-armed.", "te": "లోకాలనూ దేవతలనూ ధర్మాన్నీ పర్యవేక్షించేవాడు; కార్యమూ కారణమూ తానే; నాలుగు ఆత్మ రూపాలు, నాలుగు వ్యూహాలు, నాలుగు కోరలు, నాలుగు భుజాలు గలవాడు.", "hi": "लोकों, देवताओं और धर्म के अध्यक्ष; कारण और कार्य दोनों वही; चार आत्म-रूपों वाले, चार व्यूहों वाले, चार दाढ़ों वाले और चतुर्भुज।", "names": [["lōkādhyakṣaḥ", "లోకాధ్యక్షః", "Overseer of the worlds", "లోకాలను పర్యవేక్షించేవాడు", "लोकों के अध्यक्ष"], ["surādhyakṣaḥ", "సురాధ్యక్షః", "Overseer of the gods", "దేవతలను పర్యవేక్షించేవాడు", "देवताओं के अध्यक्ष"], ["dharmādhyakṣaḥ", "ధర్మాధ్యక్షః", "Overseer of dharma, who rewards right and wrong", "ధర్మాధర్మాలకు ఫలమిచ్చే సాక్షి", "धर्म-अधर्म के फलदाता साक्षी"], ["kṛtākṛtaḥ", "కృతాకృతః", "Both the effect and the cause", "కార్యమూ కారణమూ తానే", "कार्य और कारण दोनों"], ["chaturātmā", "చతురాత్మా", "The one with four aspects (creation, protection, dissolution and more)", "నాలుగు ఆత్మ రూపాలు గలవాడు", "चार आत्म-रूपों वाले"], ["chaturvyūhaḥ", "చతుర్వ్యూహః", "Manifest as Vāsudeva, Saṅkarṣaṇa, Pradyumna, Aniruddha", "వాసుదేవ, సంకర్షణ, ప్రద్యుమ్న, అనిరుద్ధులుగా వ్యక్తమైనవాడు", "वासुदेव, संकर्षण, प्रद्युम्न, अनिरुद्ध रूप में प्रकट"], ["chaturdaṃṣṭraḥ", "చతుర్దంష్ట్రః", "Four-tusked (as Narasiṃha)", "నాలుగు కోరలు గలవాడు (నరసింహుడు)", "चार दाढ़ों वाले (नरसिंह)"], ["chaturbhujaḥ", "చతుర్భుజః", "Four-armed", "నాలుగు భుజాలు గలవాడు", "चतुर्भुज"]] },
"vsn_16_16": { "en": "Radiant, He is the food and the one who enjoys it; patient, first-born in the world; sinless, victorious and conquering, source of the universe, who dwells again and again in beings.", "te": "ప్రకాశించేవాడు, ఆహారమూ తానే, అనుభవించేవాడూ తానే; ఓర్పు గలవాడు, జగత్తుకు ముందే పుట్టినవాడు; పాపం లేనివాడు, విజయుడు, జయించేవాడు, విశ్వానికి మూలం, మళ్ళీ మళ్ళీ దేహాలలో నివసించేవాడు.", "hi": "प्रकाशमान, स्वयं भोजन और भोक्ता; सहनशील, जगत के आदि में प्रकट; निष्पाप, विजयी और विजेता, विश्व के मूल, बार-बार देहों में बसने वाले।", "names": [["bhrājiṣṇuḥ", "భ్రాజిష్ణుః", "Pure radiance", "ప్రకాశ స్వరూపుడు", "प्रकाश-स्वरूप"], ["bhōjanam", "భోజనం", "That which is enjoyed — food, the world", "అనుభవించబడేది — ఆహారం, ప్రపంచం", "भोग्य — अन्न, जगत"], ["bhōktā", "భోక్తా", "The enjoyer", "అనుభవించేవాడు", "भोक्ता"], ["sahiṣṇuḥ", "సహిష్ణుః", "The patient one; who overpowers foes", "ఓర్పు గలవాడు; శత్రువులను అణచేవాడు", "सहनशील; शत्रुओं को दबाने वाले"], ["jagadādijaḥ", "జగదాదిజః", "Born at the very beginning of the world", "జగత్తు ఆదిలో పుట్టినవాడు", "जगत के आरंभ में प्रकट"], ["anaghaḥ", "అనఘః", "Sinless", "పాపం లేనివాడు", "निष्पाप"], ["vijayaḥ", "విజయః", "Victory itself", "విజయమే తానైనవాడు", "स्वयं विजय"], ["jētā", "జేతా", "The conqueror of all", "అందరినీ జయించేవాడు", "सबको जीतने वाले"], ["viśvayōniḥ", "విశ్వయోనిః", "Womb of the universe", "విశ్వానికి గర్భం", "विश्व की योनि (उद्गम)"], ["punarvasuḥ", "పునర్వసుః", "The one who dwells again and again in bodies", "మళ్ళీ మళ్ళీ దేహాలలో వసించేవాడు", "बार-बार देहों में बसने वाले"]] },
"vsn_17_17": { "en": "Younger brother of Indra, the dwarf who grew tall; never failing, pure and mighty; beyond Indra, the gatherer at dissolution and the creation itself; steady in Himself, the one who rules and restrains.", "te": "ఇంద్రునికి తమ్ముడు (ఉపేంద్రుడు), వామనుడు, ఆకాశమంత ఎత్తుకు ఎదిగినవాడు; వ్యర్థం కానివాడు, పవిత్రుడు, మహాబలుడు; ఇంద్రుని మించినవాడు, ప్రళయంలో అన్నిటినీ ఇముడ్చుకునేవాడు, సృష్టి స్వరూపుడు; స్థిరమైన ఆత్మ గలవాడు, నియమించేవాడు, శాసించేవాడు.", "hi": "इंद्र के छोटे भाई (उपेंद्र), वामन, आकाश तक ऊँचे हुए; कभी विफल न होने वाले, पवित्र और बलशाली; इंद्र से भी बढ़कर, प्रलय में सबको समेटने वाले, स्वयं सृष्टि; स्थिर आत्मा, नियम में रखने वाले और शासक।", "names": [["upēndraḥ", "ఉపేంద్రః", "Younger brother of Indra (born of Aditi as Vāmana)", "ఇంద్రుని తమ్ముడు (అదితి కుమారుడైన వామనుడు)", "इंद्र के अनुज (अदिति-पुत्र वामन)"], ["vāmanaḥ", "వామనః", "The dwarf who came to Bali", "బలి దగ్గరకు వచ్చిన వామనుడు", "बलि के पास आए वामन"], ["prāṃśuḥ", "ప్రాంశుః", "The one who grew immensely tall", "అమాంతం ఎత్తుగా పెరిగినవాడు", "अत्यंत ऊँचे हो जाने वाले"], ["amōghaḥ", "అమోఘః", "Whose acts never fail", "వ్యర్థం కాని కర్మలు గలవాడు", "जिनके कर्म अमोघ हैं"], ["śuchiḥ", "శుచిః", "Pure and purifying", "పవిత్రుడు, పవిత్రం చేసేవాడు", "पवित्र और पवित्र करने वाले"], ["ūrjitaḥ", "ఊర్జితః", "Of great strength", "మహాబలుడు", "महान बल वाले"], ["atīndraḥ", "అతీంద్రః", "Greater than Indra", "ఇంద్రుని మించినవాడు", "इंद्र से भी श्रेष्ठ"], ["saṅgrahaḥ", "సంగ్రహః", "The one who gathers all into Himself at dissolution", "ప్రళయంలో అన్నిటినీ తనలో ఇముడ్చుకునేవాడు", "प्रलय में सबको अपने में समेटने वाले"], ["sargaḥ", "సర్గః", "Creation itself", "సృష్టి స్వరూపుడు", "स्वयं सृष्टि"], ["dhṛtātmā", "ధృతాత్మా", "Steady in His own nature", "తన స్వరూపంలో స్థిరుడు", "अपने स्वरूप में स्थिर"], ["niyamaḥ", "నియమః", "The one who appoints all to their duties", "అందరినీ వారి పనులలో నియమించేవాడు", "सबको उनके कर्तव्य में नियुक्त करने वाले"], ["yamaḥ", "యమః", "The inner controller", "లోపలి నుండి శాసించేవాడు", "अंतर्यामी शासक"]] },
"vsn_18_18": { "en": "He is to be known, the knower of all learning, ever in yoga, slayer of the mighty wicked; Lakṣmī's lord, sweet as honey; beyond the senses, of great māyā, great zeal and great strength.", "te": "తెలుసుకోదగినవాడు, అన్ని విద్యలూ తెలిసినవాడు, నిత్య యోగి, దుష్ట వీరులను సంహరించేవాడు; లక్ష్మీపతి, మధువు వంటి మధురుడు; ఇంద్రియాలకు అతీతుడు, గొప్ప మాయ గలవాడు, గొప్ప ఉత్సాహం, గొప్ప బలం గలవాడు.", "hi": "जानने योग्य, सब विद्याओं के ज्ञाता, सदा योगी, दुष्ट वीरों के संहारक; लक्ष्मीपति, मधु के समान मधुर; इंद्रियों से परे, महामाया वाले, महान उत्साह और महाबल वाले।", "names": [["vēdyaḥ", "వేద్యః", "The one to be known", "తెలుసుకోదగినవాడు", "जानने योग्य"], ["vaidyaḥ", "వైద్యః", "Knower of all learning; the healer", "అన్ని విద్యలూ తెలిసినవాడు; వైద్యుడు", "सब विद्याओं के ज्ञाता; वैद्य"], ["sadāyōgī", "సదాయోగీ", "Always in yoga, ever awake", "ఎల్లప్పుడూ యోగంలో ఉండేవాడు", "सदा योग में स्थित"], ["vīrahā", "వీరహా", "Slayer of mighty demons", "బలవంతులైన రాక్షసులను సంహరించేవాడు", "बलवान असुरों के संहारक"], ["mādhavaḥ", "మాధవః", "Lord of knowledge; Lakṣmī's lord", "విద్యకు పతి; లక్ష్మీపతి", "विद्या के स्वामी; लक्ष्मीपति"], ["madhuḥ", "మధుః", "Sweet as honey to devotees", "భక్తులకు తేనె వంటి మధురుడు", "भक्तों के लिए मधु जैसे मधुर"], ["atīndriyaḥ", "అతీంద్రియః", "Beyond the senses", "ఇంద్రియాలకు అతీతుడు", "इंद्रियों से परे"], ["mahāmāyaḥ", "మహామాయః", "Master of great māyā", "మహామాయకు అధిపతి", "महामाया के स्वामी"], ["mahōtsāhaḥ", "మహోత్సాహః", "Of great zeal", "గొప్ప ఉత్సాహం గలవాడు", "महान उत्साह वाले"], ["mahābalaḥ", "మహాబలః", "Of great strength", "మహాబలుడు", "महाबली"]] },
"vsn_19_19": { "en": "Of great wisdom, valour, power and splendour; His form cannot be described; glorious, of immeasurable Self, the one who held up the great mountain.", "te": "మహాబుద్ధి, మహావీర్యం, మహాశక్తి, మహాతేజస్సు గలవాడు; వర్ణించలేని రూపం గలవాడు; శ్రీమంతుడు, కొలవలేని ఆత్మ గలవాడు, మహాపర్వతాన్ని ఎత్తినవాడు.", "hi": "महाबुद्धि, महावीर्य, महाशक्ति और महातेज वाले; जिनका रूप बताया नहीं जा सकता; श्रीमान, अपरिमेय आत्मा, महापर्वत को धारण करने वाले।", "names": [["mahābuddhiḥ", "మహాబుద్ధిః", "Of supreme wisdom", "మహాబుద్ధి గలవాడు", "परम बुद्धिमान"], ["mahāvīryaḥ", "మహావీర్యః", "Of great power", "మహావీర్యం గలవాడు", "महावीर्य वाले"], ["mahāśaktiḥ", "మహాశక్తిః", "Of great might", "మహాశక్తి గలవాడు", "महाशक्ति वाले"], ["mahādyutiḥ", "మహాద్యుతిః", "Of great splendour", "మహాతేజస్సు గలవాడు", "महातेजस्वी"], ["anirdēśyavapuḥ", "అనిర్దేశ్యవపుః", "Whose form cannot be pointed out", "ఇదీ అని చూపలేని రూపం గలవాడు", "जिनके रूप का निर्देश नहीं हो सकता"], ["śrīmān", "శ్రీమాన్", "Full of glory and grace", "శ్రీమంతుడు", "श्रीमान"], ["amēyātmā", "అమేయాత్మా", "Of immeasurable intelligence", "కొలవలేని ప్రజ్ఞ గలవాడు", "अपरिमेय बुद्धि वाले"], ["mahādridhṛk", "మహాద్రిధృక్", "Bearer of the great mountains — Mandara and Govardhana", "మందర, గోవర్ధన పర్వతాలను ధరించినవాడు", "मंदराचल और गोवर्धन को धारण करने वाले"]] },
"vsn_20_20": { "en": "The great archer, the upholder of the earth, abode of Śrī, refuge of the good; unstoppable, the joy of the gods, Govinda, the lord of those who know.", "te": "మహా ధనుర్ధారి, భూమిని భరించేవాడు, శ్రీనివాసుడు, సజ్జనులకు గతి; ఎవరూ అడ్డుకోలేనివాడు, దేవతలకు ఆనందం ఇచ్చేవాడు, గోవిందుడు, జ్ఞానులకు పతి.", "hi": "महान धनुर्धर, पृथ्वी के भर्ता, श्रीनिवास, सज्जनों की गति; जिन्हें कोई रोक न सके, देवताओं को आनंद देने वाले, गोविंद, ज्ञानियों के स्वामी।", "names": [["mahēśvāsaḥ", "మహేశ్వాసః", "The great archer", "మహా ధనుర్ధారి", "महान धनुर्धर"], ["mahībhartā", "మహీభర్తా", "Upholder of the earth (as Varāha)", "భూమిని ఉద్ధరించి భరించేవాడు (వరాహుడు)", "पृथ्वी को उठाने और धारण करने वाले (वराह)"], ["śrīnivāsaḥ", "శ్రీనివాసః", "The one on whose chest Śrī dwells", "శ్రీ నివసించే వక్షస్థలం గలవాడు", "जिनके वक्ष पर श्री निवास करती हैं"], ["satāṅgatiḥ", "సతాంగతిః", "The goal of the good", "సజ్జనులకు గమ్యం", "सज्जनों की गति"], ["aniruddhaḥ", "అనిరుద్ధః", "The one no one can obstruct", "ఎవరూ అడ్డుకోలేనివాడు", "जिन्हें कोई रोक न सके"], ["surānandaḥ", "సురానందః", "Giver of joy to the gods", "దేవతలకు ఆనందం ఇచ్చేవాడు", "देवताओं को आनंद देने वाले"], ["gōvindaḥ", "గోవిందః", "The one who found the earth again; known through the Veda; protector of cows", "భూమిని మళ్ళీ పొందినవాడు; వేదవాక్కులతో తెలియబడేవాడు; గోవులను కాపాడేవాడు", "पृथ्वी को फिर पाने वाले; वेद-वाणी से जाने जाने वाले; गौ-रक्षक"], ["gōvidāṃ patiḥ", "గోవిదాం పతిః", "Lord of those who know the Veda", "వేద వేత్తలకు పతి", "वेद जानने वालों के स्वामी"]] },
"vsn_21_21": { "en": "A ray of light, the tamer, the swan, the beautiful-winged, the best of serpents; golden-navelled, of fine tapas, lotus-navelled, lord of creatures.", "te": "కిరణం, దుష్టులను అణచేవాడు, హంస, సుపర్ణుడు (గరుడుడు), సర్పాలలో ఉత్తముడు (ఆదిశేషుడు); బంగారు నాభి గలవాడు, మంచి తపస్సు గలవాడు, పద్మనాభుడు, ప్రజాపతి.", "hi": "किरण, दमन करने वाले, हंस, सुपर्ण (गरुड़), सर्पों में श्रेष्ठ (शेष); स्वर्ण-नाभि वाले, उत्तम तप वाले, पद्मनाभ, प्रजापति।", "names": [["marīchiḥ", "మరీచిః", "Radiance; the light of the radiant", "కాంతి; తేజస్వులకు తేజస్సు", "प्रकाश; तेजस्वियों का तेज"], ["damanaḥ", "దమనః", "The one who tames the wicked", "దుష్టులను అణచేవాడు", "दुष्टों का दमन करने वाले"], ["haṃsaḥ", "హంసః", "The swan; the one who removes the fear of worldly life", "హంస; సంసార భయాన్ని తొలగించేవాడు", "हंस; संसार-भय मिटाने वाले"], ["suparṇaḥ", "సుపర్ణః", "Beautiful-winged (dharma and adharma as wings); Garuḍa", "అందమైన రెక్కలవాడు; గరుడుడు", "सुंदर पंखों वाले; गरुड़"], ["bhujagōttamaḥ", "భుజగోత్తమః", "Best of serpents (Ādiśeṣa)", "సర్పాలలో ఉత్తముడు (ఆదిశేషుడు)", "सर्पों में श्रेष्ठ (शेषनाग)"], ["hiraṇyanābhaḥ", "హిరణ్యనాభః", "With a golden navel", "బంగారు నాభి గలవాడు", "स्वर्ण नाभि वाले"], ["sutapāḥ", "సుతపాః", "Of perfect tapas (as Nara-Nārāyaṇa)", "చక్కని తపస్సు చేసినవాడు (నరనారాయణులు)", "उत्तम तप करने वाले (नर-नारायण)"], ["padmanābhaḥ", "పద్మనాభః", "Lotus-navelled", "పద్మనాభుడు", "पद्मनाभ"], ["prajāpatiḥ", "ప్రజాపతిః", "Father of all creatures", "సర్వ ప్రాణులకు తండ్రి", "सब प्राणियों के पिता"]] },
"vsn_22_22": { "en": "Deathless, all-seeing, the lion; the one who joins beings to the fruits of their acts, steady and unborn; unbearable to foes, the ruler, of well-known Self, slayer of the gods' enemies.", "te": "మరణం లేనివాడు, అన్నిటినీ చూసేవాడు, సింహం; కర్మఫలాలను జతచేసేవాడు, ఆ ఫలాలను అనుభవించేవాడూ తానే, స్థిరుడు, అజుడు; శత్రువులకు సహించరానివాడు, శాసించేవాడు, ప్రసిద్ధ స్వరూపుడు, దేవతల శత్రువులను సంహరించేవాడు.", "hi": "अमर, सर्वदर्शी, सिंह; कर्मों को फल से जोड़ने वाले और फल पाने वाले, स्थिर, अजन्मा; शत्रुओं के लिए असह्य, शासक, प्रसिद्ध आत्मा, देव-शत्रुओं के संहारक।", "names": [["amṛtyuḥ", "అమృత్యుః", "Free from death", "మరణం లేనివాడు", "मृत्यु से रहित"], ["sarvadṛk", "సర్వదృక్", "All-seeing", "అన్నిటినీ చూసేవాడు", "सबको देखने वाले"], ["siṃhaḥ", "సింహః", "The lion; who destroys", "సింహం; సంహరించేవాడు", "सिंह; संहार करने वाले"], ["sandhātā", "సంధాతా", "The one who joins people with the fruits of their acts", "కర్మలను వాటి ఫలాలతో కలిపేవాడు", "कर्मों को उनके फल से जोड़ने वाले"], ["sandhimān", "సంధిమాన్", "The one who also experiences those fruits", "ఆ ఫలాలను అనుభవించేవాడు", "उन फलों के भोक्ता"], ["sthiraḥ", "స్థిరః", "Ever steady", "ఎప్పుడూ స్థిరుడు", "सदा स्थिर"], ["ajaḥ", "అజః", "Unborn; who moves in devotees' hearts", "పుట్టుక లేనివాడు; భక్తుల హృదయాలలో సంచరించేవాడు", "अजन्मा; भक्तों के हृदय में विचरने वाले"], ["durmarṣaṇaḥ", "దుర్మర్షణః", "Whom the demons cannot withstand", "రాక్షసులు తట్టుకోలేనివాడు", "जिन्हें असुर सह नहीं सकते"], ["śāstā", "శాస్తా", "The teacher and ruler, through scripture", "శాస్త్రంతో శాసించి బోధించేవాడు", "शास्त्र द्वारा शिक्षा और शासन करने वाले"], ["viśrutātmā", "విశ్రుతాత్మా", "Whose nature is famous", "ప్రసిద్ధమైన స్వరూపం గలవాడు", "जिनका स्वरूप प्रसिद्ध है"], ["surārihā", "సురారిహా", "Slayer of the gods' enemies", "దేవతల శత్రువులను సంహరించేవాడు", "देव-शत्रुओं के संहारक"]] },
"vsn_23_23": { "en": "The teacher, the greatest teacher, the abode, truth itself, whose valour is true; the one who closes and opens His eyes, wearing a garland, lord of speech, of noble mind.", "te": "గురువు, గురువులలో గురువు, ఆశ్రయం, సత్యం, సత్యమైన పరాక్రమం గలవాడు; కనులు మూసేవాడు, తెరిచి ఉంచేవాడు, మాల ధరించినవాడు, వాక్కుకు పతి, ఉదార బుద్ధి గలవాడు.", "hi": "गुरु, गुरुओं के गुरु, धाम, सत्य, सच्चे पराक्रम वाले; आँखें मूँदने वाले और न मूँदने वाले, माला धारी, वाणी के स्वामी, उदार बुद्धि वाले।", "names": [["guruḥ", "గురుః", "The teacher of all knowledge", "అన్ని విద్యలకూ గురువు", "सब विद्याओं के गुरु"], ["gurutamaḥ", "గురుతమః", "Teacher even of Brahmā — the greatest teacher", "బ్రహ్మకు సైతం గురువు", "ब्रह्मा के भी गुरु"], ["dhāma", "ధామ", "The supreme light and abode", "పరమ జ్యోతి, ఆశ్రయం", "परम ज्योति और धाम"], ["satyaḥ", "సత్యః", "Truth", "సత్యం", "सत्य"], ["satyaparākramaḥ", "సత్యపరాక్రమః", "Whose valour never fails", "ఎన్నడూ విఫలం కాని పరాక్రమం గలవాడు", "जिनका पराक्रम कभी विफल नहीं होता"], ["nimiṣaḥ", "నిమిషః", "With closed eyes (in yoga-sleep)", "యోగనిద్రలో కనులు మూసినవాడు", "योगनिद्रा में आँखें मूँदे"], ["animiṣaḥ", "అనిమిషః", "Unblinking, ever awake (as the fish avatar)", "రెప్ప వేయనివాడు, ఎప్పుడూ మేల్కొని ఉండేవాడు (మత్స్యావతారం)", "बिना पलक झपकाए सदा जाग्रत (मत्स्य)"], ["sragvī", "స్రగ్వీ", "Wearing the Vaijayantī garland", "వైజయంతీ మాల ధరించినవాడు", "वैजयंती माला धारी"], ["vāchaspatirudāradhīḥ", "వాచస్పతిరుదారధీః", "Lord of speech, with a mind that grasps everything", "వాక్పతి, అన్నిటినీ గ్రహించే ఉదార బుద్ధి గలవాడు", "वाणी के स्वामी, सब कुछ समझने वाली उदार बुद्धि वाले"]] },
"vsn_24_24": { "en": "He leads to the highest, leads the hosts, is glorious, is justice, the guide, the moving breath; thousand-headed, the Self of the universe, thousand-eyed and thousand-footed.", "te": "పరమ పదానికి నడిపించేవాడు, సమూహాలకు నాయకుడు, శ్రీమంతుడు, న్యాయం తానే, నేత, ప్రాణవాయువుగా కదిలించేవాడు; వేయి శిరస్సులు, వేయి కన్నులు, వేయి పాదాలు గలవాడు, విశ్వాత్మ.", "hi": "परम पद तक ले जाने वाले, समूहों के नायक, श्रीमान, स्वयं न्याय, नेता, प्राणवायु के रूप में चलाने वाले; हज़ार सिरों, हज़ार आँखों, हज़ार पैरों वाले विश्वात्मा।", "names": [["agraṇīḥ", "అగ్రణీః", "The one who leads seekers to the highest", "సాధకులను పరమ పదానికి నడిపించేవాడు", "साधकों को परम पद तक ले जाने वाले"], ["grāmaṇīḥ", "గ్రామణీః", "Leader of all the hosts", "సమూహాలన్నిటికీ నాయకుడు", "सब समूहों के नायक"], ["śrīmān", "శ్రీమాన్", "Radiant with glory", "శోభతో ప్రకాశించేవాడు", "शोभा से दीप्त"], ["nyāyaḥ", "న్యాయః", "Justice and right reasoning itself", "న్యాయం, సరైన తర్కం తానే", "स्वयं न्याय और सही तर्क"], ["nētā", "నేతా", "The guide who moves the world", "జగత్తును నడిపించేవాడు", "जगत को चलाने वाले"], ["samīraṇaḥ", "సమీరణః", "The one who makes beings move, as breath", "ప్రాణవాయువుగా జీవులను కదిలించేవాడు", "प्राणवायु बनकर प्राणियों को चलाने वाले"], ["sahasramūrdhā", "సహస్రమూర్ధా", "Thousand-headed", "వేయి శిరస్సులవాడు", "हज़ार सिरों वाले"], ["viśvātmā", "విశ్వాత్మా", "The Self of the universe", "విశ్వానికి ఆత్మ", "विश्व की आत्मा"], ["sahasrākṣaḥ", "సహస్రాక్షః", "Thousand-eyed", "వేయి కన్నులవాడు", "हज़ार नेत्रों वाले"], ["sahasrapāt", "సహస్రపాత్", "Thousand-footed", "వేయి పాదాలవాడు", "हज़ार पैरों वाले"]] },
"vsn_25_25": { "en": "He turns the wheel of the world, yet is turned away from it; He is covered by ignorance from those who do not know Him, crushes evil; He is the day, the one who rolls all up at the end, fire, wind and the bearer of the earth.", "te": "సంసార చక్రాన్ని తిప్పేవాడు, అయినా దానికి అతీతుడు; అజ్ఞానులకు కప్పబడి ఉండేవాడు, దుష్టులను అణచివేసేవాడు; పగలు తానే, ప్రళయంలో అన్నిటినీ ముడుచుకునేవాడు, అగ్ని, వాయువు, భూమిని ధరించేవాడు.", "hi": "संसार-चक्र को घुमाने वाले, फिर भी उससे परे; अज्ञानियों से ढके हुए, दुष्टों को कुचलने वाले; स्वयं दिन, प्रलय में सबको समेटने वाले, अग्नि, वायु और पृथ्वी को धारण करने वाले।", "names": [["āvartanaḥ", "ఆవర్తనః", "The one who turns the wheel of saṃsāra", "సంసార చక్రాన్ని తిప్పేవాడు", "संसार-चक्र को घुमाने वाले"], ["nivṛttātmā", "నివృత్తాత్మా", "Whose Self is free from worldly ties", "సంసార బంధాలకు అతీతమైన ఆత్మ గలవాడు", "जिनकी आत्मा संसार के बंधनों से परे है"], ["saṃvṛtaḥ", "సంవృతః", "Hidden by the veil of ignorance", "అజ్ఞానం అనే తెరతో కప్పబడినవాడు", "अज्ञान के आवरण से ढके"], ["sampramardanaḥ", "సంప్రమర్దనః", "The one who crushes the wicked", "దుష్టులను నలిపివేసేవాడు", "दुष्टों को कुचलने वाले"], ["ahaḥ saṃvartakaḥ", "అహః సంవర్తకః", "The sun who makes the days turn", "రోజులను నడిపించే సూర్యుడు", "दिनों को चलाने वाले सूर्य"], ["vahniḥ", "వహ్నిః", "Fire, the carrier of offerings", "హవిస్సును మోసే అగ్ని", "हवि वहन करने वाले अग्नि"], ["anilaḥ", "అనిలః", "Wind; the one without a fixed abode", "వాయువు; స్థిర నివాసం లేనివాడు", "वायु; बिना निश्चित निवास वाले"], ["dharaṇīdharaḥ", "ధరణీధరః", "Bearer of the earth", "భూమిని ధరించేవాడు", "पृथ्वी को धारण करने वाले"]] },
"vsn_26_26": { "en": "Most gracious, of serene mind, holding and sustaining the universe, all-pervading; He honours the good and is honoured, is goodness itself; He drew all into Himself; He is Nārāyaṇa and Nara.", "te": "అపారమైన అనుగ్రహం గలవాడు, ప్రసన్నమైన మనసు గలవాడు, విశ్వాన్ని ధరించి పోషించేవాడు, సర్వవ్యాపి; సజ్జనులను సత్కరించేవాడు, పూజించబడేవాడు, సాధువు; ప్రళయంలో అన్నిటినీ తనలోకి తీసుకునేవాడు; నారాయణుడు, నరుడు.", "hi": "अत्यंत कृपालु, प्रसन्न मन वाले, विश्व को धारण और पोषण करने वाले, सर्वव्यापी; सज्जनों का सत्कार करने वाले और सत्कार पाने वाले, साधु; प्रलय में सबको अपने में लेने वाले; नारायण और नर।", "names": [["suprasādaḥ", "సుప్రసాదః", "Gracious even to those who wrong Him", "అపకారులపైనా అనుగ్రహం చూపేవాడు", "अपराधियों पर भी कृपा करने वाले"], ["prasannātmā", "ప్రసన్నాత్మా", "Ever clear and serene of mind", "ఎప్పుడూ ప్రసన్నమైన మనసు గలవాడు", "सदा प्रसन्न मन वाले"], ["viśvadhṛk", "విశ్వధృక్", "Holder of the universe", "విశ్వాన్ని ధరించేవాడు", "विश्व को धारण करने वाले"], ["viśvabhuk", "విశ్వభుక్", "Sustainer (and enjoyer) of the universe", "విశ్వాన్ని పోషించి అనుభవించేవాడు", "विश्व के पालक और भोक्ता"], ["vibhuḥ", "విభుః", "All-pervading, taking many forms", "అనేక రూపాలతో అంతటా ఉండేవాడు", "अनेक रूपों में सर्वत्र"], ["satkartā", "సత్కర్తా", "The one who honours the good", "సజ్జనులను సత్కరించేవాడు", "सज्जनों का सत्कार करने वाले"], ["satkṛtaḥ", "సత్కృతః", "Worshipped even by the worshipped", "పూజ్యులచేత కూడా పూజించబడేవాడు", "पूज्यों द्वारा भी पूजित"], ["sādhuḥ", "సాధుః", "The righteous one", "ధర్మాత్ముడు", "धर्मात्मा साधु"], ["jahnuḥ", "జహ్నుః", "The one who withdraws all beings at the end", "ప్రళయంలో ప్రాణులను తనలోకి ఉపసంహరించేవాడు", "प्रलय में प्राणियों को अपने में समेटने वाले"], ["nārāyaṇaḥ", "నారాయణః", "The resting place of all beings; who rests on the waters", "సర్వ జీవులకు ఆశ్రయం; జలాలపై శయనించేవాడు", "सब जीवों के आश्रय; जल पर शयन करने वाले"], ["naraḥ", "నరః", "The guide who leads (Nara)", "నడిపించే నరుడు", "मार्ग दिखाने वाले नर"]] },
"vsn_27_27": { "en": "Countless, of immeasurable Self, distinguished, the teacher of the disciplined, pure; His aims are fulfilled and His will is always true; giver of success and the very means of success.", "te": "లెక్కలేనివాడు, కొలవలేని ఆత్మ గలవాడు, విశిష్టుడు, శిష్టులను శాసించేవాడు, పవిత్రుడు; సిద్ధించిన ప్రయోజనం గలవాడు, సత్య సంకల్పుడు; సిద్ధిని ఇచ్చేవాడు, సిద్ధికి సాధనమూ తానే.", "hi": "असंख्य, अपरिमेय आत्मा, विशिष्ट, शिष्टों के शासक, पवित्र; जिनके सब प्रयोजन सिद्ध हैं, सत्य-संकल्प; सिद्धि देने वाले और सिद्धि का साधन भी।", "names": [["asaṅkhyēyaḥ", "అసంఖ్యేయః", "Beyond counting — names and forms without number", "లెక్కలేని నామరూపాలు గలవాడు", "असंख्य नाम-रूपों वाले"], ["apramēyātmā", "అప్రమేయాత్మా", "Of immeasurable nature", "కొలవలేని స్వరూపం గలవాడు", "अपरिमेय स्वरूप वाले"], ["viśiṣṭaḥ", "విశిష్టః", "Distinguished above all", "అందరికంటే విశిష్టుడు", "सबसे विशिष्ट"], ["śiṣṭakṛt", "శిష్టకృత్", "The one who commands and protects the good", "శిష్టులను శాసించి కాపాడేవాడు", "शिष्टों को आदेश देने और रक्षा करने वाले"], ["śuchiḥ", "శుచిః", "Spotless", "నిర్మలుడు", "निर्मल"], ["siddhārthaḥ", "సిద్ధార్థః", "One whose every aim is already fulfilled", "కోరికలన్నీ సిద్ధించినవాడు", "जिनके सब प्रयोजन सिद्ध हैं"], ["siddhasaṅkalpaḥ", "సిద్ధసంకల్పః", "Whose resolve always comes true", "సంకల్పమంతా సత్యమయ్యేవాడు", "जिनका संकल्प सदा सत्य होता है"], ["siddhidaḥ", "సిద్ధిదః", "Giver of success", "సిద్ధిని ఇచ్చేవాడు", "सिद्धि देने वाले"], ["siddhisādhanaḥ", "సిద్ధిసాధనః", "The very means to success", "సిద్ధికి సాధనం", "सिद्धि का साधन"]] },
"vsn_28_28": { "en": "Lord of the yajña day, the bull who showers blessings, Viṣṇu; dharma is His steps and dharma His belly; He makes all grow and grows Himself, yet stays apart — an ocean of scripture.", "te": "యజ్ఞ దినానికి అధిపతి, వరాలను వర్షించే వృషభం, విష్ణువు; ధర్మమే మెట్లుగా, ధర్మమే ఉదరంగా గలవాడు; అందరినీ పెంచేవాడు, తానూ పెరిగేవాడు, అయినా వేరుగా ఉండేవాడు, శ్రుతుల సముద్రం.", "hi": "यज्ञ-दिवस के स्वामी, वर बरसाने वाले वृषभ, विष्णु; धर्म जिनकी सीढ़ी और धर्म जिनका उदर है; सबको बढ़ाने वाले, स्वयं बढ़ने वाले, फिर भी अलग — श्रुतियों के सागर।", "names": [["vṛṣāhī", "వృషాహీ", "The one in whom yajña-days (dharma) shine", "యజ్ఞ దినాలు (ధర్మం) ప్రకాశించేవాడు", "जिनमें यज्ञ-दिवस (धर्म) प्रकाशित हैं"], ["vṛṣabhaḥ", "వృషభః", "The bull who showers all wishes on devotees", "భక్తులపై కోరికలను వర్షించేవాడు", "भक्तों पर कामनाएँ बरसाने वाले"], ["viṣṇuḥ", "విష్ణుః", "The all-pervader", "సర్వవ్యాపి", "सर्वव्यापी"], ["vṛṣaparvā", "వృషపర్వా", "Dharma is the ladder to Him", "ఆయనను చేరే మెట్లు ధర్మమే", "धर्म ही जिन तक पहुँचने की सीढ़ी है"], ["vṛṣōdaraḥ", "వృషోదరః", "In whose belly all beings rest; dharma at His core", "ఉదరంలో ప్రాణులను ధరించినవాడు; ధర్మమే కేంద్రం", "जिनके उदर में सब प्राणी हैं; धर्म जिनका केंद्र है"], ["vardhanaḥ", "వర్ధనః", "The one who makes all grow", "అందరినీ వృద్ధి చేసేవాడు", "सबको बढ़ाने वाले"], ["vardhamānaḥ", "వర్ధమానః", "The one who grows as the world", "ప్రపంచంగా పెరిగేవాడు", "जगत के रूप में बढ़ने वाले"], ["viviktaḥ", "వివిక్తః", "Yet standing apart, untouched", "అయినా అంటకుండా వేరుగా ఉండేవాడు", "फिर भी अलग, अछूते"], ["śrutisāgaraḥ", "శ్రుతిసాగరః", "Ocean of the Vedas", "వేదాల సముద్రం", "वेदों के सागर"]] },
"vsn_29_29": { "en": "Of beautiful arms, hard to hold, eloquent, the great Indra, giver of wealth and wealth itself; of many forms and vast form, present in the rays, the revealer.", "te": "అందమైన భుజాలు గలవాడు, ఎవరూ పట్టలేనివాడు, వాక్చాతుర్యం గలవాడు, మహేంద్రుడు, సంపదను ఇచ్చేవాడు, సంపదే తానైనవాడు; అనేక రూపాలు, విశాల రూపం గలవాడు, కిరణాలలో వ్యాపించినవాడు, ప్రకాశింపజేసేవాడు.", "hi": "सुंदर भुजाओं वाले, जिन्हें कोई धर न सके, वाक्पटु, महेंद्र, धन देने वाले और स्वयं धन; अनेक रूपों वाले, विराट रूप वाले, किरणों में व्याप्त, प्रकाशित करने वाले।", "names": [["subhujaḥ", "సుభుజః", "With beautiful arms that protect the world", "లోకాన్ని కాపాడే అందమైన భుజాలవాడు", "जगत की रक्षा करने वाली सुंदर भुजाओं वाले"], ["durdharaḥ", "దుర్ధరః", "Whom no one can hold or resist", "ఎవరూ పట్టలేనివాడు", "जिन्हें कोई धारण न कर सके"], ["vāgmī", "వాగ్మీ", "From whom the Veda's speech comes", "వేద వాక్కు పుట్టిన వాగ్మి", "जिनसे वेद-वाणी निकली"], ["mahēndraḥ", "మహేంద్రః", "Lord even of Indra", "ఇంద్రునికి సైతం ప్రభువు", "इंद्र के भी स्वामी"], ["vasudaḥ", "వసుదః", "Giver of wealth", "సంపదను ఇచ్చేవాడు", "धन देने वाले"], ["vasuḥ", "వసుః", "Wealth itself", "సంపదే తానైనవాడు", "स्वयं धन"], ["naikarūpaḥ", "నైకరూపః", "Of many forms", "అనేక రూపాలు గలవాడు", "अनेक रूपों वाले"], ["bṛhadrūpaḥ", "బృహద్రూపః", "Of vast form (Varāha, Trivikrama)", "విశాల రూపం గలవాడు (వరాహ, త్రివిక్రముడు)", "विराट रूप वाले (वराह, त्रिविक्रम)"], ["śipiviṣṭaḥ", "శిపివిష్టః", "Present in the rays of light", "కిరణాలలో ప్రవేశించినవాడు", "किरणों में प्रविष्ट"], ["prakāśanaḥ", "ప్రకాశనః", "The one who lights everything up", "అన్నిటినీ ప్రకాశింపజేసేవాడు", "सबको प्रकाशित करने वाले"]] },
"vsn_30_30": { "en": "He holds vigour, brilliance and light; luminous of Self, the scorcher; rich in all, of clear-sounding syllable (Om), the mantra, with the moon's cool rays and the sun's brilliance.", "te": "ఓజస్సు, తేజస్సు, కాంతి గలవాడు; ప్రకాశ స్వరూపుడు, తపింపజేసేవాడు; సమృద్ధుడు, స్పష్టమైన అక్షరం (ఓంకారం) గలవాడు, మంత్రం తానే; చంద్రుని చల్లని కిరణాలు, సూర్యుని తేజస్సు గలవాడు.", "hi": "ओज, तेज और कांति धारण करने वाले; प्रकाश-स्वरूप, तपाने वाले; समृद्ध, स्पष्ट अक्षर (ॐ) वाले, स्वयं मंत्र; चंद्रमा की शीतल किरणों और सूर्य के तेज वाले।", "names": [["ōjastējōdyutidharaḥ", "ఓజస్తేజోద్యుతిధరః", "Holder of vigour, brilliance and radiance", "ఓజస్సు, తేజస్సు, కాంతిని ధరించినవాడు", "ओज, तेज और कांति धारण करने वाले"], ["prakāśātmā", "ప్రకాశాత్మా", "Whose nature is light", "ప్రకాశమే స్వరూపంగా గలవాడు", "प्रकाश-स्वरूप"], ["pratāpanaḥ", "ప్రతాపనః", "The one who scorches (as the sun)", "సూర్యునిగా తపింపజేసేవాడు", "सूर्य के रूप में तपाने वाले"], ["ṛddhaḥ", "ఋద్ధః", "Abundant in dharma, knowledge and detachment", "ధర్మ జ్ఞాన వైరాగ్యాలతో సమృద్ధుడు", "धर्म, ज्ञान, वैराग्य से समृद्ध"], ["spaṣṭākṣaraḥ", "స్పష్టాక్షరః", "Whose syllable Om is clear", "స్పష్టమైన ఓంకారం గలవాడు", "स्पष्ट ॐकार वाले"], ["mantraḥ", "మంత్రః", "The mantra — known through the Vedic mantras", "మంత్రమే తానైనవాడు", "स्वयं मंत्र"], ["chandrāṃśuḥ", "చంద్రాంశుః", "Cool and soothing like moonlight", "వెన్నెల వలె చల్లగా ఉండేవాడు", "चाँदनी जैसे शीतल"], ["bhāskaradyutiḥ", "భాస్కరద్యుతిః", "Bright as the sun", "సూర్యుని వలె ప్రకాశించేవాడు", "सूर्य के समान तेजस्वी"]] },
"vsn_31_31": { "en": "Source of the moon born from the ocean, the sun, the hare-marked moon, lord of the gods; the medicine of the world, the bridge across it, whose dharma and valour are true.", "te": "సముద్ర మథనంలో పుట్టిన చంద్రునికి మూలం, సూర్యుడు, శశాంకుడు (చంద్రుడు), దేవతల ఈశ్వరుడు; లోకానికి ఔషధం, దాటించే వారధి, సత్యమైన ధర్మం, పరాక్రమం గలవాడు.", "hi": "समुद्र-मंथन से निकले चंद्रमा के मूल, सूर्य, शशांक (चंद्र), देवताओं के ईश्वर; संसार की औषधि, पार कराने वाला सेतु, सत्य धर्म और पराक्रम वाले।", "names": [["amṛtāṃśūdbhavaḥ", "అమృతాంశూద్భవః", "The source of the moon (born from the churned ocean)", "చంద్రుని పుట్టుకకు మూలం", "चंद्रमा की उत्पत्ति के मूल"], ["bhānuḥ", "భానుః", "The shining sun", "ప్రకాశించే సూర్యుడు", "प्रकाशमान सूर्य"], ["śaśabinduḥ", "శశబిందుః", "The moon, marked with a hare", "కుందేలు గుర్తు గల చంద్రుడు", "खरगोश-चिह्न वाले चंद्रमा"], ["surēśvaraḥ", "సురేశ్వరః", "Lord of the gods", "దేవతల ఈశ్వరుడు", "देवताओं के ईश्वर"], ["auṣadham", "ఔషధం", "Medicine for the disease of worldly life", "సంసార వ్యాధికి ఔషధం", "संसार-रोग की औषधि"], ["jagataḥ sētuḥ", "జగతః సేతుః", "The bridge to cross the world", "సంసారాన్ని దాటించే వారధి", "संसार पार कराने वाला सेतु"], ["satyadharmaparākramaḥ", "సత్యధర్మపరాక్రమః", "Whose dharma and valour are true", "సత్యమైన ధర్మ పరాక్రమాలు గలవాడు", "सत्य धर्म और पराक्रम वाले"]] },
"vsn_32_32": { "en": "Lord of past, future and present; the wind that purifies, the fire; He destroys desire and fulfils it, is lovely, is love itself, the giver of what is longed for, the master.", "te": "భూత భవిష్యత్ వర్తమానాలకు నాథుడు; పవిత్రం చేసే వాయువు, అగ్ని; కోరికలను నశింపజేసేవాడు, తీర్చేవాడు, మనోహరుడు, కామ్యుడు, కోరినవి ఇచ్చేవాడు, ప్రభువు.", "hi": "भूत, भविष्य, वर्तमान के नाथ; पवित्र करने वाले वायु, अग्नि; कामनाओं का नाश करने वाले और पूरी करने वाले, मनोहर, स्वयं काम्य, इच्छित देने वाले, प्रभु।", "names": [["bhūtabhavyabhavannāthaḥ", "భూతభవ్యభవన్నాథః", "Lord of all that was, will be and is", "జరిగినది, జరగబోయేది, జరుగుతున్నదానికి నాథుడు", "जो था, होगा और है — उसके नाथ"], ["pavanaḥ", "పవనః", "The purifying wind", "పవిత్రం చేసే వాయువు", "पवित्र करने वाले वायु"], ["pāvanaḥ", "పావనః", "The one who makes things move and purifies", "కదిలించి పవిత్రం చేసేవాడు", "गति देने और पवित्र करने वाले"], ["analaḥ", "అనలః", "Fire; never satisfied in giving", "అగ్ని; ఇచ్చి తృప్తి చెందనివాడు", "अग्नि; देकर भी कभी न अघाने वाले"], ["kāmahā", "కామహా", "Destroyer of the desires of seekers", "సాధకుల కోరికలను నశింపజేసేవాడు", "मुमुक्षुओं की कामनाओं का नाश करने वाले"], ["kāmakṛt", "కామకృత్", "Fulfiller of devotees' wishes", "భక్తుల కోరికలు తీర్చేవాడు", "भक्तों की कामनाएँ पूरी करने वाले"], ["kāntaḥ", "కాంతః", "Beautiful, lovely", "మనోహరుడు", "मनोहर"], ["kāmaḥ", "కామః", "The one all long for", "అందరూ కోరుకునేవాడు", "जिनकी सब कामना करते हैं"], ["kāmapradaḥ", "కామప్రదః", "Giver of what is desired", "కోరినవి ఇచ్చేవాడు", "मनचाहा देने वाले"], ["prabhuḥ", "ప్రభుః", "The master", "ప్రభువు", "प्रभु"]] },
"vsn_33_33": { "en": "Maker of the ages and turner of the ages, of countless māyās, the great devourer at the end; invisible yet manifest, conqueror of thousands and of the endless.", "te": "యుగాలను సృష్టించేవాడు, యుగాలను తిప్పేవాడు, అనేక మాయలు గలవాడు, ప్రళయంలో అన్నిటినీ మింగేవాడు; కనిపించనివాడు, వ్యక్త రూపుడు కూడా, వేలమందిని, అనంతులను జయించేవాడు.", "hi": "युगों के रचयिता और युगों को घुमाने वाले, अनेक मायाओं वाले, प्रलय में सबको निगलने वाले; अदृश्य होकर भी व्यक्त रूप वाले, हज़ारों और अनंत को जीतने वाले।", "names": [["yugādikṛt", "యుగాదికృత్", "Maker of the beginning of the ages", "యుగారంభాన్ని సృష్టించేవాడు", "युगों के आरंभकर्ता"], ["yugāvartaḥ", "యుగావర్తః", "The one who makes the ages turn", "యుగాలను తిప్పేవాడు", "युगों को घुमाने वाले"], ["naikamāyaḥ", "నైకమాయః", "Of many wondrous powers (māyās)", "అనేక మాయలు గలవాడు", "अनेक मायाओं वाले"], ["mahāśanaḥ", "మహాశనః", "The great eater who consumes all at the end", "ప్రళయంలో అన్నిటినీ భక్షించేవాడు", "प्रलय में सबको खा जाने वाले"], ["adṛśyaḥ", "అదృశ్యః", "Invisible to the senses", "ఇంద్రియాలకు కనిపించనివాడు", "इंद्रियों से अदृश्य"], ["vyaktarūpaḥ", "వ్యక్తరూపః", "Yet manifest in gross form", "స్థూల రూపంలో వ్యక్తమైనవాడు", "स्थूल रूप में व्यक्त"], ["sahasrajit", "సహస్రజిత్", "Conqueror of thousands of foes", "వేల శత్రువులను జయించేవాడు", "हज़ारों शत्रुओं को जीतने वाले"], ["anantajit", "అనంతజిత్", "Conqueror of all, without limit", "అపరిమితంగా అందరినీ జయించేవాడు", "असीम विजय वाले"]] },
"vsn_34_34": { "en": "Dear to all and distinguished by none, beloved of the wise, wearing the peacock feather, the binder by māyā, dharma itself; destroyer of anger and causing anger in the wicked, the doer, with the universe as His arms, the bearer of the earth.", "te": "అందరికీ ప్రియుడు, ఎవరిచేతా వేరుపరచబడనివాడు, శిష్టులకు ఇష్టుడు, నెమలి పింఛం ధరించినవాడు, మాయతో బంధించేవాడు, ధర్మ స్వరూపుడు; కోపాన్ని పోగొట్టేవాడు, దుష్టులపై కోపం చూపేవాడు, కర్త, విశ్వమే భుజాలుగా గలవాడు, భూమిని ధరించేవాడు.", "hi": "सबके प्रिय, किसी से भिन्न न किए जा सकने वाले, शिष्टों के प्रिय, मोरपंख धारी, माया से बाँधने वाले, स्वयं धर्म; क्रोध मिटाने वाले, दुष्टों पर क्रोध करने वाले, कर्ता, विश्व जिनकी भुजाएँ हैं, पृथ्वी के धारक।", "names": [["iṣṭaḥ", "ఇష్టః", "Dear to all; worshipped in yajña", "అందరికీ ఇష్టుడు; యజ్ఞంలో పూజించబడేవాడు", "सबके प्रिय; यज्ञ में पूजित"], ["aviśiṣṭaḥ", "అవిశిష్టః", "The same within all, without distinction", "అందరిలో భేదం లేకుండా ఉన్నవాడు", "सबमें बिना भेद के विद्यमान"], ["śiṣṭēṣṭaḥ", "శిష్టేష్టః", "Beloved of the wise", "జ్ఞానులకు ప్రియుడు", "ज्ञानियों के प्रिय"], ["śikhaṇḍī", "శిఖండీ", "Wearing a peacock feather (as Kṛṣṇa)", "నెమలి పింఛం ధరించినవాడు (శ్రీకృష్ణుడు)", "मोरपंख धारी (श्रीकृष्ण)"], ["nahuṣaḥ", "నహుషః", "The one who binds beings by māyā", "మాయతో జీవులను బంధించేవాడు", "माया से जीवों को बाँधने वाले"], ["vṛṣaḥ", "వృషః", "Dharma itself", "ధర్మ స్వరూపుడు", "स्वयं धर्म"], ["krōdhahā", "క్రోధహా", "Destroyer of anger (in devotees)", "భక్తులలో కోపాన్ని నశింపజేసేవాడు", "भक्तों के क्रोध का नाश करने वाले"], ["krōdhakṛt", "క్రోధకృత్", "The one who shows anger to the wicked", "దుష్టులపై కోపం చూపేవాడు", "दुष्टों पर क्रोध करने वाले"], ["kartā", "కర్తా", "The doer of all", "అన్నిటికీ కర్త", "सबके कर्ता"], ["viśvabāhuḥ", "విశ్వబాహుః", "Whose arms are everywhere", "అంతటా భుజాలు గలవాడు", "जिनकी भुजाएँ सर्वत्र हैं"], ["mahīdharaḥ", "మహీధరః", "Bearer of the earth", "భూమిని ధరించేవాడు", "पृथ्वी को धारण करने वाले"]] },
"vsn_35_35": { "en": "Unfailing, renowned, the life-breath and its giver, Indra's younger brother; the treasure of the waters, the foundation, ever watchful, firmly established.", "te": "అచ్యుతుడు, ప్రఖ్యాతుడు, ప్రాణం, ప్రాణదాత, ఇంద్రుని తమ్ముడు; సముద్రం, అన్నిటికీ అధిష్ఠానం, ఎప్పుడూ జాగ్రత్తగా ఉండేవాడు, తనలో తాను స్థిరుడు.", "hi": "अच्युत, प्रसिद्ध, प्राण और प्राणदाता, इंद्र के अनुज; जल-निधि (समुद्र), सबके आधार, सदा सावधान, अपनी महिमा में प्रतिष्ठित।", "names": [["achyutaḥ", "అచ్యుతః", "Never slipping from His nature", "తన స్వభావం నుండి జారనివాడు", "अपने स्वभाव से कभी न गिरने वाले"], ["prathitaḥ", "ప్రథితః", "Famous for creating the world", "జగత్సృష్టితో ప్రఖ్యాతుడు", "जगत-सृष्टि से प्रसिद्ध"], ["prāṇaḥ", "ప్రాణః", "The breath of life", "ప్రాణం", "प्राण"], ["prāṇadaḥ", "ప్రాణదః", "Giver of strength and life", "బలాన్నీ ప్రాణాన్నీ ఇచ్చేవాడు", "बल और प्राण देने वाले"], ["vāsavānujaḥ", "వాసవానుజః", "Younger brother of Indra (Vāmana)", "ఇంద్రుని తమ్ముడు (వామనుడు)", "इंद्र के छोटे भाई (वामन)"], ["apāṃ nidhiḥ", "అపాం నిధిః", "Treasure of the waters — the ocean", "జలాల నిధి — సముద్రం", "जल का भंडार — समुद्र"], ["adhiṣṭhānam", "అధిష్ఠానం", "The foundation of all", "అన్నిటికీ ఆధారం", "सबका आधार"], ["apramattaḥ", "అప్రమత్తః", "Never careless in giving each their due", "ఫలమివ్వడంలో ఏమరుపాటు లేనివాడు", "फल देने में कभी असावधान न होने वाले"], ["pratiṣṭhitaḥ", "ప్రతిష్ఠితః", "Established in His own greatness", "తన మహిమలోనే నిలిచినవాడు", "अपनी महिमा में प्रतिष्ठित"]] },
"vsn_36_36": { "en": "Skanda, the upholder of Skanda; bearer of the burden of the world, giver of boons, master of the winds; Vāsudeva, of great radiance, the first god, the destroyer of cities.", "te": "స్కందుడు, స్కందుని ధరించేవాడు; లోక భారాన్ని మోసేవాడు, వరాలు ఇచ్చేవాడు, వాయువులను నడిపించేవాడు; వాసుదేవుడు, గొప్ప కాంతి గలవాడు, ఆదిదేవుడు, అసుర పురాలను భేదించినవాడు.", "hi": "स्कंद, स्कंद को धारण करने वाले; जगत का भार उठाने वाले, वर देने वाले, वायु को चलाने वाले; वासुदेव, महान तेज वाले, आदिदेव, असुर-पुरों को तोड़ने वाले।", "names": [["skandaḥ", "స్కందః", "The one who flows as nectar; Skanda", "అమృతంగా ప్రవహించేవాడు; స్కందుడు", "अमृत रूप में बहने वाले; स्कंद"], ["skandadharaḥ", "స్కందధరః", "Upholder of the path of dharma", "ధర్మ మార్గాన్ని నిలిపేవాడు", "धर्म-मार्ग को धारण करने वाले"], ["dhuryaḥ", "ధుర్యః", "Bearer of the burden of all beings", "సర్వ ప్రాణుల భారాన్ని మోసేవాడు", "सब प्राणियों का भार उठाने वाले"], ["varadaḥ", "వరదః", "Giver of boons", "వరాలు ఇచ్చేవాడు", "वर देने वाले"], ["vāyuvāhanaḥ", "వాయువాహనః", "The one who drives the winds", "వాయువులను నడిపించేవాడు", "वायु को चलाने वाले"], ["vāsudēvaḥ", "వాసుదేవః", "The one who dwells in all and in whom all dwell; Vasudeva's son", "అన్నిటిలో వసించే దేవుడు; వసుదేవుని కుమారుడు", "सबमें बसने वाले देव; वसुदेव-पुत्र"], ["bṛhadbhānuḥ", "బృహద్భానుః", "Of vast radiance", "విశాలమైన కాంతి గలవాడు", "विशाल तेज वाले"], ["ādidēvaḥ", "ఆదిదేవః", "The first god", "ఆదిదేవుడు", "आदिदेव"], ["purandaraḥ", "పురందరః", "Destroyer of the cities of the gods' enemies", "దేవశత్రువుల పురాలను భేదించినవాడు", "देव-शत्रुओं के पुरों को तोड़ने वाले"]] },
"vsn_37_37": { "en": "Free from sorrow, the one who takes us across, the deliverer, the hero, Śauri, lord of people; ever kind, of a hundred forms, holding the lotus, with lotus-like eyes.", "te": "శోకం లేనివాడు, సంసారాన్ని దాటించేవాడు, తారకుడు, శూరుడు, శౌరి (శూరుని వంశీయుడు), జనులకు ఈశ్వరుడు; అనుకూలుడు, వందల అవతారాలు గలవాడు, పద్మం ధరించినవాడు, పద్మాల వంటి కన్నులవాడు.", "hi": "शोक-रहित, पार उतारने वाले, तारक, शूर, शौरि (शूर-वंशी), जनों के ईश्वर; सबके अनुकूल, सैकड़ों अवतारों वाले, कमल धारी, कमल जैसे नेत्रों वाले।", "names": [["aśōkaḥ", "అశోకః", "Free from sorrow", "శోకం లేనివాడు", "शोक से रहित"], ["tāraṇaḥ", "తారణః", "The one who takes us across the ocean of saṃsāra", "సంసార సముద్రాన్ని దాటించేవాడు", "संसार-सागर से पार कराने वाले"], ["tāraḥ", "తారః", "The deliverer from fear", "భయం నుండి రక్షించేవాడు", "भय से तारने वाले"], ["śūraḥ", "శూరః", "The valiant", "శూరుడు", "शूरवीर"], ["śauriḥ", "శౌరిః", "Descendant of Śūra (Kṛṣṇa)", "శూరుని వంశంలో పుట్టినవాడు (శ్రీకృష్ణుడు)", "शूर के वंशज (श्रीकृष्ण)"], ["janēśvaraḥ", "జనేశ్వరః", "Lord of all people", "జనులందరికీ ఈశ్వరుడు", "सब लोगों के ईश्वर"], ["anukūlaḥ", "అనుకూలః", "Favourable to all, as their own Self", "ఆత్మగా అందరికీ అనుకూలుడు", "आत्मा के रूप में सबके अनुकूल"], ["śatāvartaḥ", "శతావర్తః", "Who returns in hundreds of avatāras", "వందల అవతారాలు ఎత్తేవాడు", "सैकड़ों अवतार लेने वाले"], ["padmī", "పద్మీ", "Holding a lotus", "చేతిలో పద్మం ధరించినవాడు", "हाथ में कमल धारण करने वाले"], ["padmanibhēkṣaṇaḥ", "పద్మనిభేక్షణః", "With eyes like lotuses", "పద్మాల వంటి కన్నులు గలవాడు", "कमल जैसे नेत्रों वाले"]] },
"vsn_38_38": { "en": "Lotus-navelled and lotus-eyed, seated in the heart's lotus, taking on bodies; of great prosperity, flourishing, ancient of Self, large-eyed, with Garuḍa on His banner.", "te": "పద్మనాభుడు, అరవిందాక్షుడు, హృదయ పద్మంలో ఉండేవాడు, శరీరాలు ధరించేవాడు; గొప్ప ఐశ్వర్యం గలవాడు, సమృద్ధుడు, పురాతన ఆత్మ, విశాల నేత్రుడు, గరుడ ధ్వజుడు.", "hi": "पद्मनाभ, अरविंदाक्ष, हृदय-कमल में विराजमान, शरीर धारण करने वाले; महान ऐश्वर्य वाले, समृद्ध, पुरातन आत्मा, विशाल नेत्रों वाले, गरुड़ध्वज।", "names": [["padmanābhaḥ", "పద్మనాభః", "With a lotus at the navel", "నాభిలో పద్మం గలవాడు", "नाभि में कमल वाले"], ["aravindākṣaḥ", "అరవిందాక్షః", "Lotus-eyed", "అరవిందాల వంటి కన్నులవాడు", "कमल-नयन"], ["padmagarbhaḥ", "పద్మగర్భః", "Worshipped in the lotus of the heart", "హృదయ పద్మంలో ఉపాసించబడేవాడు", "हृदय-कमल में उपासित"], ["śarīrabhṛt", "శరీరభృత్", "Sustainer of all bodies", "శరీరాలన్నిటినీ పోషించేవాడు", "सब शरीरों का पोषण करने वाले"], ["maharddhiḥ", "మహర్ద్ధిః", "Of great splendour and wealth", "గొప్ప ఐశ్వర్యం గలవాడు", "महान ऐश्वर्य वाले"], ["ṛddhaḥ", "ఋద్ధః", "Flourishing as the universe", "ప్రపంచంగా విస్తరించినవాడు", "जगत के रूप में विस्तृत"], ["vṛddhātmā", "వృద్ధాత్మా", "The ancient Self", "పురాతన ఆత్మ", "पुरातन आत्मा"], ["mahākṣaḥ", "మహాక్షః", "Large-eyed", "విశాల నేత్రుడు", "विशाल नेत्रों वाले"], ["garuḍadhvajaḥ", "గరుడధ్వజః", "With Garuḍa on His flag", "గరుడ పతాకం గలవాడు", "गरुड़-ध्वज वाले"]] },
"vsn_39_39": { "en": "Matchless, the śarabha, the awe-inspiring, the knower of right time; He is the offering and Hari; bearing every auspicious mark, Lakṣmī's lord, victorious in battle.", "te": "సాటిలేనివాడు, శరభుడు, భయంకరుడు, సమయం తెలిసినవాడు; హవిస్సు తానే, హరి; సర్వ శుభ లక్షణాలతో కూడినవాడు, లక్ష్మీపతి, యుద్ధంలో జయించేవాడు.", "hi": "अतुलनीय, शरभ, भयंकर, समय के ज्ञाता; स्वयं हवि, हरि; सब शुभ लक्षणों से युक्त, लक्ष्मीपति, युद्ध में विजयी।", "names": [["atulaḥ", "అతులః", "Beyond comparison", "సాటిలేనివాడు", "अतुलनीय"], ["śarabhaḥ", "శరభః", "Shining within the body as the Self", "శరీరంలో ఆత్మగా ప్రకాశించేవాడు", "शरीर में आत्मा रूप से प्रकाशित"], ["bhīmaḥ", "భీమః", "Awe-inspiring", "భయం కలిగించేవాడు", "भय उत्पन्न करने वाले"], ["samayajñaḥ", "సమయజ్ఞః", "Knower of the right time; even-minded", "సమయం తెలిసినవాడు; సమదృష్టి గలవాడు", "उचित समय के ज्ञाता; समदर्शी"], ["haviḥ", "హవిః", "The offering in yajña", "యజ్ఞంలో హవిస్సు", "यज्ञ की हवि"], ["hariḥ", "హరిః", "The one who takes away sin and sorrow", "పాపాన్నీ దుఃఖాన్నీ హరించేవాడు", "पाप और दुःख हरने वाले"], ["sarvalakṣaṇalakṣaṇyaḥ", "సర్వలక్షణలక్షణ్యః", "Known by every true sign", "అన్ని శుభ లక్షణాలతో తెలియబడేవాడు", "सब लक्षणों से जाने जाने वाले"], ["lakṣmīvān", "లక్ష్మీవాన్", "With Lakṣmī ever at His side", "లక్ష్మి ఎప్పుడూ తోడుగా ఉన్నవాడు", "लक्ष्मी सदा जिनके साथ हैं"], ["samitiñjayaḥ", "సమితింజయః", "Victorious in battle", "యుద్ధంలో జయించేవాడు", "युद्ध में विजयी"]] },
"vsn_40_40": { "en": "Undecaying, the red-hued (fish form), the path, the cause, Dāmodara, the forbearing; bearer of mountains, of great fortune, swift, who consumes without limit.", "te": "క్షయం లేనివాడు, ఎర్రని (మత్స్య) రూపం గలవాడు, మార్గం, కారణం, దామోదరుడు, సహనశీలుడు; పర్వతాలను ధరించేవాడు, మహా భాగ్యవంతుడు, వేగవంతుడు, అపరిమితంగా భుజించేవాడు.", "hi": "अक्षर, लाल (मत्स्य) रूप वाले, मार्ग, कारण, दामोदर, सहनशील; पर्वतों के धारक, महान भाग्य वाले, वेगवान, असीम भोजन करने वाले।", "names": [["vikṣaraḥ", "విక్షరః", "The undecaying", "క్షయం లేనివాడు", "क्षय-रहित"], ["rōhitaḥ", "రోహితః", "Red-hued (as the fish avatāra)", "ఎర్రని రంగుగల మత్స్య రూపుడు", "लाल रंग के मत्स्य रूप"], ["mārgaḥ", "మార్గః", "The path to liberation", "మోక్ష మార్గం", "मोक्ष का मार्ग"], ["hētuḥ", "హేతుః", "The cause of all", "అన్నిటికీ కారణం", "सबका कारण"], ["dāmōdaraḥ", "దామోదరః", "Tied at the waist by Yaśodā's rope; known through self-control", "యశోద తాడుతో నడుము కట్టబడినవాడు; ఇంద్రియ నిగ్రహంతో తెలియబడేవాడు", "यशोदा की रस्सी से कमर में बँधे; इंद्रिय-संयम से जाने जाने वाले"], ["sahaḥ", "సహః", "All-enduring", "అన్నిటినీ సహించేవాడు", "सब कुछ सहने वाले"], ["mahīdharaḥ", "మహీధరః", "Bearer of the mountains", "పర్వతాలను ధరించేవాడు", "पर्वतों को धारण करने वाले"], ["mahābhāgaḥ", "మహాభాగః", "Of great fortune", "మహా భాగ్యశాలి", "महाभाग्यशाली"], ["vēgavān", "వేగవాన్", "Swift", "వేగవంతుడు", "वेगवान"], ["amitāśanaḥ", "అమితాశనః", "Who consumes everything at the end", "ప్రళయంలో అన్నిటినీ భుజించేవాడు", "प्रलय में सबको खाने वाले"]] },
"vsn_41_41": { "en": "The source, the one who stirs creation into motion, the shining one, holding Śrī within, the Supreme Lord; the instrument, the cause, the doer and the transformer, deep and hidden.", "te": "మూలం, సృష్టిని కదిలించేవాడు, ప్రకాశించే దేవుడు, శ్రీని గర్భంలో ధరించినవాడు, పరమేశ్వరుడు; సాధనం, కారణం, కర్త, వికర్త, అగాధుడు, గుహలో దాగినవాడు.", "hi": "उद्गम, सृष्टि को गति देने वाले, प्रकाशमान देव, श्री को गर्भ में धारण करने वाले, परमेश्वर; साधन, कारण, कर्ता, विकर्ता, गहन और गुहा में छिपे।", "names": [["udbhavaḥ", "ఉద్భవః", "The source of all creation; beyond birth", "సృష్టికి మూలం; జన్మకు అతీతుడు", "सृष्टि के मूल; जन्म से परे"], ["kṣōbhaṇaḥ", "క్షోభణః", "The one who stirs nature into creating", "ప్రకృతిని సృష్టికి కదిలించేవాడు", "प्रकृति को सृष्टि के लिए क्षुब्ध करने वाले"], ["dēvaḥ", "దేవః", "The shining, playful one", "ప్రకాశించేవాడు, లీలామయుడు", "प्रकाशमान, लीलामय"], ["śrīgarbhaḥ", "శ్రీగర్భః", "Holding all glory within", "సమస్త శ్రీని తనలో ధరించినవాడు", "सब ऐश्वर्य अपने भीतर धारण करने वाले"], ["paramēśvaraḥ", "పరమేశ్వరః", "The Supreme Lord", "పరమేశ్వరుడు", "परमेश्वर"], ["karaṇam", "కరణం", "The instrument of creation", "సృష్టికి సాధనం", "सृष्टि का साधन"], ["kāraṇam", "కారణం", "The cause", "కారణం", "कारण"], ["kartā", "కర్తా", "The doer", "కర్త", "कर्ता"], ["vikartā", "వికర్తా", "The maker of endless variety", "అనంత వైవిధ్యాన్ని సృష్టించేవాడు", "अनंत विविधता रचने वाले"], ["gahanaḥ", "గహనః", "Deep, hard to fathom", "అగాధుడు, అర్థం కానివాడు", "गहन, दुर्बोध"], ["guhaḥ", "గుహః", "Hidden by His māyā", "మాయతో దాగినవాడు", "माया से छिपे"]] },
"vsn_42_42": { "en": "He is certainty, the ground of order, the final resting place, the giver of positions, the unmoving; of supreme richness, utterly clear, content, full, with an auspicious gaze.", "te": "నిశ్చయ స్వరూపుడు, వ్యవస్థకు ఆధారం, అంతిమ నివాసం, స్థానాలను ఇచ్చేవాడు, ధ్రువుడు; పరమ ఐశ్వర్యం గలవాడు, అత్యంత స్పష్టుడు, తృప్తుడు, పరిపూర్ణుడు, శుభ దృష్టి గలవాడు.", "hi": "निश्चय-स्वरूप, व्यवस्था के आधार, अंतिम विश्राम-स्थान, पद देने वाले, ध्रुव; परम ऐश्वर्य वाले, अत्यंत स्पष्ट, तुष्ट, पुष्ट, शुभ दृष्टि वाले।", "names": [["vyavasāyaḥ", "వ్యవసాయః", "Pure knowledge, firm resolve", "నిశ్చయ జ్ఞానం", "निश्चयात्मक ज्ञान"], ["vyavasthānaḥ", "వ్యవస్థానః", "The ground on which the world's order rests", "లోక వ్యవస్థకు ఆధారం", "जगत-व्यवस्था के आधार"], ["saṃsthānaḥ", "సంస్థానః", "The final abode of all at dissolution", "ప్రళయంలో అందరికీ అంతిమ స్థానం", "प्रलय में सबका अंतिम स्थान"], ["sthānadaḥ", "స్థానదః", "Giver of rightful places (as to Dhruva)", "తగిన స్థానాలు ఇచ్చేవాడు (ధ్రువునికి వలె)", "उचित पद देने वाले (जैसे ध्रुव को)"], ["dhruvaḥ", "ధ్రువః", "Fixed, imperishable", "ధ్రువుడు, నశించనివాడు", "ध्रुव, अविनाशी"], ["parardhiḥ", "పరర్ధిః", "Of supreme glory", "పరమ ఐశ్వర్యం గలవాడు", "परम ऐश्वर्य वाले"], ["paramaspaṣṭaḥ", "పరమస్పష్టః", "Utterly self-evident", "స్వయంగా అత్యంత స్పష్టుడు", "स्वयं अत्यंत स्पष्ट"], ["tuṣṭaḥ", "తుష్టః", "Ever content", "ఎప్పుడూ తృప్తుడు", "सदा संतुष्ट"], ["puṣṭaḥ", "పుష్టః", "Complete, full", "పరిపూర్ణుడు", "परिपूर्ण"], ["śubhēkṣaṇaḥ", "శుభేక్షణః", "Whose glance brings blessing", "చూపే శుభాన్ని ఇచ్చేవాడు", "जिनकी दृष्टि मंगल देती है"]] },
"vsn_43_43": { "en": "Rāma who delights, the end of all, stainless, the path, the guide and the leading; free from any leader; the hero, best of the mighty, dharma itself, the best knower of dharma.", "te": "ఆనందింపజేసే రాముడు, అన్నిటికీ విరామం, రజోగుణం లేనివాడు, మార్గం, నడిపించేవాడు, నయం; తనను నడిపించేవారు లేనివాడు; వీరుడు, శక్తిమంతులలో శ్రేష్ఠుడు, ధర్మం, ధర్మవేత్తలలో ఉత్తముడు.", "hi": "आनंद देने वाले राम, सबका विराम, रज-रहित, मार्ग, ले जाने वाले, नीति; जिनका कोई नायक नहीं; वीर, शक्तिमानों में श्रेष्ठ, धर्म, धर्म-ज्ञाताओं में उत्तम।", "names": [["rāmaḥ", "రామః", "In whom the yogīs delight", "యోగులు రమించే రాముడు", "जिनमें योगी रमण करते हैं"], ["virāmaḥ", "విరామః", "The rest and end of all", "అన్నిటికీ విరామం", "सबका विराम"], ["virajaḥ", "విరజః", "Free from passion and stain", "రజోగుణం లేనివాడు", "रजोगुण से रहित"], ["mārgaḥ", "మార్గః", "The path to Him", "ఆయనను చేరే మార్గం", "उन तक पहुँचने का मार्ग"], ["nēyaḥ", "నేయః", "The one who is led (by knowledge to the Self)", "జ్ఞానంతో పొందదగినవాడు", "ज्ञान से प्राप्त होने वाले"], ["nayaḥ", "నయః", "The guide", "నడిపించేవాడు", "मार्गदर्शक"], ["anayaḥ", "అనయః", "The one with no one to lead Him", "తనను నడిపించేవారు లేనివాడు", "जिनका कोई नायक नहीं"], ["vīraḥ", "వీరః", "The hero", "వీరుడు", "वीर"], ["śaktimatāṃ śrēṣṭhaḥ", "శక్తిమతాం శ్రేష్ఠః", "Best of the powerful", "శక్తిమంతులలో శ్రేష్ఠుడు", "शक्तिमानों में श्रेष्ठ"], ["dharmaḥ", "ధర్మః", "Dharma itself", "ధర్మం", "धर्म"], ["dharmaviduttamaḥ", "ధర్మవిదుత్తమః", "The best of those who know dharma", "ధర్మవేత్తలలో ఉత్తముడు", "धर्म-ज्ञाताओं में उत्तम"]] },
"vsn_44_44": { "en": "Lord of Vaikuṇṭha, the Person, life and its giver, the sacred Om, the vast; the golden womb, slayer of foes, all-pervading, the wind, and the one beyond the senses.", "te": "వైకుంఠుడు, పురుషుడు, ప్రాణం, ప్రాణదాత, ప్రణవం (ఓంకారం), విస్తృతుడు; హిరణ్యగర్భుడు, శత్రువులను సంహరించేవాడు, వ్యాపకుడు, వాయువు, ఇంద్రియాలకు అతీతుడైన అధోక్షజుడు.", "hi": "वैकुंठ, पुरुष, प्राण, प्राणदाता, प्रणव (ॐ), विस्तृत; हिरण्यगर्भ, शत्रुघ्न, व्यापक, वायु, इंद्रियों से परे अधोक्षज।", "names": [["vaikuṇṭhaḥ", "వైకుంఠః", "The one who brings scattered things together; Lord of Vaikuṇṭha", "చెదిరినవాటిని కలిపేవాడు; వైకుంఠ నాథుడు", "बिखरे को जोड़ने वाले; वैकुंठनाथ"], ["puruṣaḥ", "పురుషః", "The one who existed before all", "అన్నిటికంటే ముందున్నవాడు", "सबसे पहले विद्यमान"], ["prāṇaḥ", "ప్రాణః", "The life-breath", "ప్రాణం", "प्राण"], ["prāṇadaḥ", "ప్రాణదః", "Giver (and taker) of life", "ప్రాణం ఇచ్చేవాడు, తీసుకునేవాడు", "प्राण देने और लेने वाले"], ["praṇavaḥ", "ప్రణవః", "Om itself", "ఓంకారం", "ॐकार"], ["pṛthuḥ", "పృథుః", "The vast, spread as the world", "ప్రపంచంగా విస్తరించినవాడు", "जगत के रूप में विस्तृत"], ["hiraṇyagarbhaḥ", "హిరణ్యగర్భః", "Source of Brahmā, the golden womb", "బ్రహ్మకు మూలమైన హిరణ్యగర్భం", "ब्रह्मा के मूल हिरण्यगर्भ"], ["śatrughnaḥ", "శత్రుఘ్నః", "Slayer of the enemies of the gods", "దేవశత్రువులను సంహరించేవాడు", "देव-शत्रुओं का संहार करने वाले"], ["vyāptaḥ", "వ్యాప్తః", "Pervading all as their cause", "కారణంగా అన్నిటిలో వ్యాపించినవాడు", "कारण रूप से सबमें व्याप्त"], ["vāyuḥ", "వాయుః", "The wind that carries scents", "గంధాన్ని మోసే వాయువు", "गंध वहन करने वाले वायु"], ["adhōkṣajaḥ", "అధోక్షజః", "Beyond the reach of the senses", "ఇంద్రియాల జ్ఞానానికి అతీతుడు", "इंद्रियों के ज्ञान से परे"]] },
"vsn_45_45": { "en": "The season, the one of beautiful vision, time, the one in the highest abode, the one who receives all; the fierce, the year, the able, the resting place, the most generous.", "te": "ఋతువు, సుదర్శనుడు (మంచి దర్శనం ఇచ్చేవాడు), కాలం, పరమ పదంలో ఉండేవాడు, అన్నిటినీ స్వీకరించేవాడు; ఉగ్రుడు, సంవత్సరం, దక్షుడు, విశ్రాంతి స్థానం, అత్యంత ఉదారుడు.", "hi": "ऋतु, सुदर्शन, काल, परमेष्ठी, सबको ग्रहण करने वाले; उग्र, संवत्सर, दक्ष, विश्राम-स्थान, सबसे उदार।", "names": [["ṛtuḥ", "ఋతుః", "The seasons — time", "ఋతువులు — కాలం", "ऋतुएँ — काल"], ["sudarśanaḥ", "సుదర్శనః", "Of auspicious vision; the discus", "శుభ దర్శనం ఇచ్చేవాడు; సుదర్శన చక్రం", "शुभ दर्शन देने वाले; सुदर्शन चक्र"], ["kālaḥ", "కాలః", "Time, which reckons all", "అన్నిటినీ లెక్కించే కాలం", "सबकी गणना करने वाला काल"], ["paramēṣṭhī", "పరమేష్ఠీ", "Dwelling in the highest abode", "పరమ స్థానంలో ఉండేవాడు", "परम धाम में स्थित"], ["parigrahaḥ", "పరిగ్రహః", "The one who accepts offerings from all sides", "అన్ని వైపుల నుండి అర్పణలను స్వీకరించేవాడు", "सब ओर से भेंट ग्रहण करने वाले"], ["ugraḥ", "ఉగ్రః", "Fierce, awe-inspiring", "ఉగ్రుడు", "उग्र"], ["saṃvatsaraḥ", "సంవత్సరః", "In whom all beings live — the year", "అన్ని ప్రాణులూ నివసించే సంవత్సరం", "जिनमें सब बसते हैं — संवत्सर"], ["dakṣaḥ", "దక్షః", "Swift and skilful in action", "చురుకైన, సమర్థుడు", "कुशल और शीघ्रकारी"], ["viśrāmaḥ", "విశ్రామః", "The rest of the weary", "అలసినవారికి విశ్రాంతి", "थके हुओं का विश्राम"], ["viśvadakṣiṇaḥ", "విశ్వదక్షిణః", "The most generous, skilled in all", "అత్యంత ఉదారుడు, అన్నిటిలో నేర్పరి", "सबसे उदार, सबमें निपुण"]] },
"vsn_46_46": { "en": "He expands as the world, is firm and unmoving, the proof of all, the undying seed; He is the goal and needs nothing; the great treasury, of great enjoyment and great wealth.", "te": "ప్రపంచంగా విస్తరించేవాడు, స్థిరుడు, స్థాణువు, ప్రమాణం, నాశనం లేని బీజం; అందరూ కోరే అర్థం, తనకు ఏ కోరికా లేనివాడు; మహా కోశం, మహా భోగం, మహా ధనం గలవాడు.", "hi": "जगत रूप में विस्तार पाने वाले, स्थिर, अचल, प्रमाण, अविनाशी बीज; सबके लक्ष्य, स्वयं निष्काम; महाकोश, महाभोग और महाधन वाले।", "names": [["vistāraḥ", "విస్తారః", "The one in whom the worlds spread out", "లోకాలు విస్తరించే ఆధారం", "जिनमें लोकों का विस्तार है"], ["sthāvaraḥ sthāṇuḥ", "స్థావరః స్థాణుః", "Firm and immovable", "స్థిరుడు, కదలనివాడు", "स्थिर और अचल"], ["pramāṇam", "ప్రమాణం", "The proof — consciousness itself", "ప్రమాణం — చైతన్యమే", "प्रमाण — स्वयं चेतना"], ["bījamavyayam", "బీజమవ్యయం", "The imperishable seed", "నాశనం లేని బీజం", "अविनाशी बीज"], ["arthaḥ", "అర్థః", "The goal all seek", "అందరూ కోరే లక్ష్యం", "सबका लक्ष्य"], ["anarthaḥ", "అనర్థః", "The one with nothing left to seek", "తనకు కోరవలసినదేదీ లేనివాడు", "जिन्हें कुछ पाना शेष नहीं"], ["mahākōśaḥ", "మహాకోశః", "Covered by the great sheaths", "మహా కోశాలతో కప్పబడినవాడు", "महाकोशों से आवृत"], ["mahābhōgaḥ", "మహాభోగః", "Of great bliss", "మహా భోగం (ఆనందం) గలవాడు", "महान आनंद वाले"], ["mahādhanaḥ", "మహాధనః", "Of great wealth", "మహా ధనవంతుడు", "महाधनी"]] },
"vsn_47_47": { "en": "Never weary, the vast, the being, the pillar of dharma, the great sacrifice; the hub of the stars and the lord of the stars, the able, the one who remains when all wanes, the one who strives for all.", "te": "ఎప్పుడూ అలసట లేనివాడు, అతి స్థూలుడు, భూః (సత్తా), ధర్మ యూపం, మహా యజ్ఞం; నక్షత్ర చక్రానికి కేంద్రం, నక్షత్రాల అధిపతి (చంద్రుడు), సమర్థుడు, అన్నీ క్షీణించినా మిగిలేవాడు, లోక హితం కోసం ప్రయత్నించేవాడు.", "hi": "कभी न थकने वाले, अति विशाल, सत्ता, धर्म के यूप, महायज्ञ; नक्षत्र-चक्र के केंद्र, नक्षत्रों के स्वामी, समर्थ, सबके क्षीण होने पर भी शेष, जगत-हित के लिए प्रयत्नशील।", "names": [["anirviṇṇaḥ", "అనిర్విణ్ణః", "Never weary or dejected", "ఎన్నడూ అలసట, నిరాశ లేనివాడు", "कभी न थकने वाले, न निराश होने वाले"], ["sthaviṣṭhaḥ", "స్థవిష్ఠః", "The immense (cosmic form)", "విరాట్ రూపుడు", "विराट रूप"], ["bhūḥ", "భూః", "Existence itself", "సత్తా", "स्वयं सत्ता"], ["dharmayūpaḥ", "ధర్మయూపః", "The post to which all dharma is tied", "ధర్మాలన్నిటినీ కట్టిన యూప స్తంభం", "जिससे सब धर्म बँधे हैं, वह यूप"], ["mahāmakhaḥ", "మహామఖః", "The great sacrifice", "మహా యజ్ఞం", "महायज्ञ"], ["nakṣatranēmiḥ", "నక్షత్రనేమిః", "The hub around which the stars turn", "నక్షత్రాలు తిరిగే కేంద్రం", "जिसके चारों ओर नक्षत्र घूमते हैं"], ["nakṣatrī", "నక్షత్రీ", "The moon, lord of the stars", "నక్షత్రాలకు అధిపతి చంద్రుడు", "नक्षत्रों के स्वामी चंद्र"], ["kṣamaḥ", "క్షమః", "Capable in all things", "అన్నిటిలో సమర్థుడు", "सबमें समर्थ"], ["kṣāmaḥ", "క్షామః", "The one who remains when all has dwindled", "అన్నీ క్షీణించినా మిగిలేవాడు", "सब क्षीण होने पर भी शेष रहने वाले"], ["samīhanaḥ", "సమీహనః", "The one who works for the good of all", "లోక హితం కోసం ప్రయత్నించేవాడు", "सबके हित के लिए प्रयत्नशील"]] },
"vsn_48_48": { "en": "He is yajña, the one worshipped in it, the great object of worship, the rite and the long session; the goal of the good, the all-seeing, the free Self, the all-knowing, the highest knowledge.", "te": "యజ్ఞం తానే, యజ్ఞంలో పూజించబడేవాడు, మహా పూజ్యుడు, క్రతువు, సత్రయాగం, సజ్జనుల గతి; అన్నిటినీ చూసేవాడు, ముక్తాత్మ, సర్వజ్ఞుడు, ఉత్తమ జ్ఞానం.", "hi": "स्वयं यज्ञ, यज्ञ में पूज्य, महान पूज्य, क्रतु, सत्र, सज्जनों की गति; सर्वदर्शी, मुक्तात्मा, सर्वज्ञ, उत्तम ज्ञान।", "names": [["yajñaḥ", "యజ్ఞః", "Yajña itself", "యజ్ఞ స్వరూపుడు", "स्वयं यज्ञ"], ["ijyaḥ", "ఇజ్యః", "The one worshipped in yajña", "యజ్ఞంలో పూజించబడేవాడు", "यज्ञ में पूजित"], ["mahējyaḥ", "మహేజ్యః", "The greatest to be worshipped", "అత్యంత పూజ్యుడు", "सबसे बड़े पूज्य"], ["kratuḥ", "క్రతుః", "The rite with a sacrificial post", "క్రతువు", "क्रतु (यज्ञ-विधि)"], ["satram", "సత్రం", "The long sacrificial session; protector of the good", "సత్రయాగం; సజ్జనులను కాపాడేవాడు", "सत्र-यज्ञ; सज्जनों के रक्षक"], ["satāṅgatiḥ", "సతాంగతిః", "Refuge of the good", "సజ్జనులకు ఆశ్రయం", "सज्जनों का आश्रय"], ["sarvadarśī", "సర్వదర్శీ", "Seeing all", "అన్నిటినీ చూసేవాడు", "सब देखने वाले"], ["vimuktātmā", "విముక్తాత్మా", "Ever free", "నిత్య ముక్తుడు", "नित्य मुक्त"], ["sarvajñaḥ", "సర్వజ్ఞః", "All-knowing", "సర్వజ్ఞుడు", "सर्वज्ञ"], ["jñānamuttamam", "జ్ఞానముత్తమం", "The highest knowledge", "ఉత్తమ జ్ఞానం", "उत्तम ज्ञान"]] },
"vsn_49_49": { "en": "Of firm vows, pleasant-faced, subtle, of beautiful voice, giver of happiness, the friend of all; charming, who has conquered anger, of heroic arms, who tears apart the wicked.", "te": "దృఢ వ్రతుడు, ప్రసన్న ముఖుడు, సూక్ష్ముడు, మధుర స్వరం గలవాడు, సుఖాన్ని ఇచ్చేవాడు, అందరికీ మిత్రుడు; మనోహరుడు, కోపాన్ని జయించినవాడు, వీర భుజాలవాడు, దుష్టులను చీల్చేవాడు.", "hi": "उत्तम व्रत वाले, सुंदर मुख वाले, सूक्ष्म, मधुर स्वर वाले, सुख देने वाले, सबके मित्र; मनोहर, क्रोध को जीतने वाले, वीर भुजाओं वाले, दुष्टों को चीरने वाले।", "names": [["suvrataḥ", "సువ్రతః", "Of firm vows (to protect those who surrender)", "శరణాగతులను కాపాడే దృఢ వ్రతం గలవాడు", "शरणागत-रक्षा के दृढ़ व्रत वाले"], ["sumukhaḥ", "సుముఖః", "Of pleasant face", "ప్రసన్న ముఖం గలవాడు", "प्रसन्न मुख वाले"], ["sūkṣmaḥ", "సూక్ష్మః", "Subtle", "సూక్ష్ముడు", "सूक्ष्म"], ["sughōṣaḥ", "సుఘోషః", "Of beautiful voice — the Veda", "మధుర నాదం (వేదం) గలవాడు", "सुंदर नाद (वेद) वाले"], ["sukhadaḥ", "సుఖదః", "Giver of happiness", "సుఖాన్ని ఇచ్చేవాడు", "सुख देने वाले"], ["suhṛt", "సుహృత్", "The friend who helps without expecting anything", "ప్రతిఫలం ఆశించని మిత్రుడు", "बिना अपेक्षा के सहायक मित्र"], ["manōharaḥ", "మనోహరః", "Stealer of hearts", "మనసులను దోచేవాడు", "मन हरने वाले"], ["jitakrōdhaḥ", "జితక్రోధః", "Conqueror of anger", "కోపాన్ని జయించినవాడు", "क्रोध को जीतने वाले"], ["vīrabāhuḥ", "వీరబాహుః", "Of mighty arms", "వీర భుజాలవాడు", "वीर भुजाओं वाले"], ["vidāraṇaḥ", "విదారణః", "The one who tears apart the unrighteous", "అధర్మాత్ములను చీల్చేవాడు", "अधर्मियों को चीरने वाले"]] },
"vsn_50_50": { "en": "He puts beings to sleep in māyā, is His own master, all-pervading, of many selves and many deeds; the dwelling of all, loving, the protector of the young, holding gems within, lord of wealth.", "te": "మాయతో జీవులను నిద్రపుచ్చేవాడు, స్వతంత్రుడు, వ్యాపకుడు, అనేక రూపాలు, అనేక కర్మలు గలవాడు; అందరికీ నివాసం, వాత్సల్యం గలవాడు, బిడ్డలను కాపాడేవాడు, రత్నాలను గర్భంలో ధరించినవాడు, ధనేశ్వరుడు.", "hi": "माया से जीवों को सुलाने वाले, स्वतंत्र, व्यापक, अनेक रूपों और अनेक कर्मों वाले; सबके निवास, वत्सल, बच्चों के रक्षक, रत्न-गर्भ, धनेश्वर।", "names": [["svāpanaḥ", "స్వాపనః", "The one who lulls beings to sleep with māyā", "మాయతో జీవులను నిద్రపుచ్చేవాడు", "माया से जीवों को सुलाने वाले"], ["svavaśaḥ", "స్వవశః", "Under no one's control but His own", "తనకు తానే అధీనుడు", "केवल अपने वश में"], ["vyāpī", "వ్యాపీ", "All-pervading like space", "ఆకాశం వలె అంతటా ఉండేవాడు", "आकाश की तरह सर्वव्यापी"], ["naikātmā", "నైకాత్మా", "Of many forms", "అనేక స్వరూపాలు గలవాడు", "अनेक स्वरूपों वाले"], ["naikakarmakṛt", "నైకకర్మకృత్", "Doer of many deeds", "అనేక కర్మలు చేసేవాడు", "अनेक कर्म करने वाले"], ["vatsaraḥ", "వత్సరః", "The dwelling place of all", "అందరికీ నివాసం", "सबका निवास"], ["vatsalaḥ", "వత్సలః", "Full of loving affection for devotees", "భక్తులపై వాత్సల్యం గలవాడు", "भक्त-वत्सल"], ["vatsī", "వత్సీ", "Protector of His children (all beings)", "తన బిడ్డలైన ప్రాణులను కాపాడేవాడు", "अपने बच्चों (प्राणियों) के रक्षक"], ["ratnagarbhaḥ", "రత్నగర్భః", "Holding jewels within (as the ocean)", "సముద్రం వలె రత్నాలను గర్భంలో ధరించినవాడు", "समुद्र की तरह रत्नों को गर्भ में धारण करने वाले"], ["dhanēśvaraḥ", "ధనేశ్వరః", "Lord of wealth", "ధనానికి ఈశ్వరుడు", "धन के ईश्वर"]] },
"vsn_51_51": { "en": "Protector, doer and holder of dharma; He is the real and the unreal, the perishable and the imperishable; not a knower in the limited sense, thousand-rayed, the ordainer, with marks well known.", "te": "ధర్మాన్ని కాపాడేవాడు, ఆచరించేవాడు, ధరించేవాడు; సత్తు, అసత్తు, క్షరం, అక్షరం అన్నీ తానే; పరిమిత జ్ఞాత కానివాడు, వేయి కిరణాలవాడు, విధాత, ప్రసిద్ధ లక్షణాలు గలవాడు.", "hi": "धर्म के रक्षक, कर्ता और धारक; सत् और असत्, क्षर और अक्षर सब वही; सीमित ज्ञाता नहीं, हज़ार किरणों वाले, विधाता, प्रसिद्ध लक्षणों वाले।", "names": [["dharmagup", "ధర్మగుప్", "Protector of dharma", "ధర్మాన్ని కాపాడేవాడు", "धर्म के रक्षक"], ["dharmakṛt", "ధర్మకృత్", "The one who practises dharma as an example", "ఆదర్శంగా ధర్మాన్ని ఆచరించేవాడు", "आदर्श रूप में धर्म का आचरण करने वाले"], ["dharmī", "ధర్మీ", "Upholder of dharma", "ధర్మాన్ని ధరించేవాడు", "धर्म को धारण करने वाले"], ["sat", "సత్", "The real", "సత్తు (సత్యమైనది)", "सत् (सत्य)"], ["asat", "అసత్", "The unreal (the world of change)", "అసత్తు (మారే ప్రపంచం)", "असत् (परिवर्तनशील जगत)"], ["kṣaram", "క్షరం", "The perishable", "నశించేది", "नश्वर"], ["akṣaram", "అక్షరం", "The imperishable", "నశించనిది", "अविनाशी"], ["avijñātā", "అవిజ్ఞాతా", "Not a knower in the limited sense of a jīva", "జీవుని వలె పరిమిత జ్ఞాత కానివాడు", "जीव की तरह सीमित ज्ञाता नहीं"], ["sahasrāṃśuḥ", "సహస్రాంశుః", "Thousand-rayed (the sun)", "వేయి కిరణాలవాడు (సూర్యుడు)", "सहस्र किरणों वाले (सूर्य)"], ["vidhātā", "విధాతా", "Upholder of all upholders", "ఆధారాలన్నిటికీ ఆధారం", "सब आधारों के आधार"], ["kṛtalakṣaṇaḥ", "కృతలక్షణః", "Of well-known marks; author of the scriptures", "ప్రసిద్ధ లక్షణాలు గలవాడు; శాస్త్రాలను ఇచ్చినవాడు", "प्रसिद्ध लक्षणों वाले; शास्त्रों के दाता"]] },
"vsn_52_52": { "en": "The hub of the wheel of rays, abiding in sattva, the lion, the great lord of beings; the first god, the great god, lord of the gods, supporter of the gods, the teacher.", "te": "కిరణ చక్రానికి కేంద్రం, సత్త్వంలో ఉండేవాడు, సింహం, భూతాలకు మహేశ్వరుడు; ఆదిదేవుడు, మహాదేవుడు, దేవేశుడు, దేవతలను పోషించేవాడు, గురువు.", "hi": "किरण-चक्र के केंद्र, सत्त्व में स्थित, सिंह, भूतों के महेश्वर; आदिदेव, महादेव, देवेश, देवताओं के पालक, गुरु।", "names": [["gabhastinēmiḥ", "గభస్తినేమిః", "The centre of the wheel of light-rays", "కిరణ చక్రానికి మధ్యలో ఉన్నవాడు", "किरण-चक्र के मध्य में स्थित"], ["sattvasthaḥ", "సత్త్వస్థః", "Abiding in sattva", "సత్త్వ గుణంలో ఉండేవాడు", "सत्त्व में स्थित"], ["siṃhaḥ", "సింహః", "The lion — mighty", "సింహం వంటి పరాక్రమి", "सिंह जैसे पराक्रमी"], ["bhūtamahēśvaraḥ", "భూతమహేశ్వరః", "The great lord of all beings", "సర్వ భూతాలకు మహేశ్వరుడు", "सब प्राणियों के महेश्वर"], ["ādidēvaḥ", "ఆదిదేవః", "The first god", "ఆదిదేవుడు", "आदिदेव"], ["mahādēvaḥ", "మహాదేవః", "The great god, glorious in knowledge and yoga", "జ్ఞాన యోగాలతో మహిమాన్వితుడైన మహాదేవుడు", "ज्ञान और योग से महिमामय महादेव"], ["dēvēśaḥ", "దేవేశః", "Lord of the gods", "దేవతల ఈశుడు", "देवताओं के ईश"], ["dēvabhṛdguruḥ", "దేవభృద్గురుః", "Teacher of Indra, sustainer of the gods", "దేవతలను పోషించే గురువు", "देवताओं का पालन करने वाले गुरु"]] },
"vsn_53_53": { "en": "The one who lifts us out, lord of cows and of the earth, the protector, reached through knowledge, the ancient; sustainer of the elements of the body, the enjoyer, lord of the monkeys, giver of rich gifts.", "te": "సంసారం నుండి ఉద్ధరించేవాడు, గోవులకు (భూమికి) పతి, రక్షకుడు, జ్ఞానంతో చేరదగినవాడు, పురాతనుడు; శరీర భూతాలను పోషించేవాడు, భోక్త, వానరులకు అధిపతి, గొప్ప దక్షిణలు ఇచ్చేవాడు.", "hi": "संसार से उबारने वाले, गौ (पृथ्वी) के पति, रक्षक, ज्ञान से प्राप्य, पुरातन; शरीर के भूतों का पोषण करने वाले, भोक्ता, वानरों के राजा, प्रचुर दक्षिणा देने वाले।", "names": [["uttaraḥ", "ఉత్తరః", "The one who lifts beings out of saṃsāra", "సంసారం నుండి ఉద్ధరించేవాడు", "संसार से उबारने वाले"], ["gōpatiḥ", "గోపతిః", "Lord of cows; lord of the earth", "గోవులకు పతి; భూమికి పతి", "गौओं के स्वामी; पृथ्वी के स्वामी"], ["gōptā", "గోప్తా", "The protector of all", "అందరినీ రక్షించేవాడు", "सबके रक्षक"], ["jñānagamyaḥ", "జ్ఞానగమ్యః", "Reached through knowledge", "జ్ఞానంతో చేరదగినవాడు", "ज्ञान से प्राप्य"], ["purātanaḥ", "పురాతనః", "Most ancient", "అతి పురాతనుడు", "अति प्राचीन"], ["śarīrabhūtabhṛt", "శరీరభూతభృత్", "Sustainer of the elements that make up the body", "శరీరంలోని భూతాలను పోషించేవాడు", "शरीर के तत्वों का पोषण करने वाले"], ["bhōktā", "భోక్తా", "The enjoyer", "భోక్త", "भोक्ता"], ["kapīndraḥ", "కపీంద్రః", "Lord of the monkeys (Rāma)", "వానర నాయకుడు (శ్రీరాముడు)", "वानरों के स्वामी (श्रीराम)"], ["bhūridakṣiṇaḥ", "భూరిదక్షిణః", "Who gives abundant gifts in yajña", "యజ్ఞాలలో విస్తారమైన దక్షిణలు ఇచ్చేవాడు", "यज्ञों में प्रचुर दक्षिणा देने वाले"]] },
"vsn_54_54": { "en": "Drinker of soma and of nectar, the moon itself; conqueror of many, best of many; the disciplinarian, victory, true to His word, of the Daśārha line, lord of the Sātvatas.", "te": "సోమాన్ని, అమృతాన్ని పానం చేసేవాడు, సోముడు (చంద్రుడు); అనేకులను జయించినవాడు, అనేకులలో ఉత్తముడు; శిక్షించేవాడు, జయం, సత్యసంధుడు, దాశార్హుడు, సాత్వతుల పతి.", "hi": "सोम और अमृत पीने वाले, स्वयं सोम; अनेकों को जीतने वाले, अनेकों में श्रेष्ठ; दंड देने वाले, विजय, सत्यप्रतिज्ञ, दाशार्ह, सात्वतों के स्वामी।", "names": [["sōmapaḥ", "సోమపః", "The one who drinks the soma in yajña", "యజ్ఞంలో సోమపానం చేసేవాడు", "यज्ञ में सोम पीने वाले"], ["amṛtapaḥ", "అమృతపః", "The one who drinks the nectar of His own bliss", "తన ఆనందామృతాన్ని పానం చేసేవాడు", "अपने आनंद-अमृत का पान करने वाले"], ["sōmaḥ", "సోమః", "The moon that nourishes plants", "ఓషధులను పోషించే చంద్రుడు", "औषधियों को पोषित करने वाले चंद्र"], ["purujit", "పురుజిత్", "Conqueror of many", "అనేకులను జయించినవాడు", "अनेकों को जीतने वाले"], ["purusattamaḥ", "పురుసత్తమః", "The best among the great", "గొప్పవారిలో ఉత్తముడు", "महानों में श्रेष्ठ"], ["vinayaḥ", "వినయః", "The one who disciplines the wicked", "దుష్టులను శిక్షించేవాడు", "दुष्टों को दंड देने वाले"], ["jayaḥ", "జయః", "Victory", "జయం", "विजय"], ["satyasandhaḥ", "సత్యసంధః", "True to His promises", "మాట నిలబెట్టేవాడు", "वचन के पक्के"], ["dāśārhaḥ", "దాశార్హః", "Born in the Daśārha clan; worthy of gifts", "దాశార్హ వంశంలో పుట్టినవాడు", "दाशार्ह कुल में जन्मे"], ["sātvatāṃ patiḥ", "సాత్వతాం పతిః", "Lord of the Sātvatas (the devotees)", "సాత్వతులకు (భక్తులకు) పతి", "सात्वतों (भक्तों) के स्वामी"]] },
"vsn_55_55": { "en": "The living being, the one who leads and disciplines, the witness, giver of liberation, of boundless valour; the ocean, the endless Self, the one who sleeps on the great ocean, the ender.", "te": "జీవుడు, నడిపించి శిక్షణ ఇచ్చేవాడు, సాక్షి, ముక్తినిచ్చే ముకుందుడు, అపరిమిత పరాక్రమం గలవాడు; సముద్రం, అనంతాత్మ, మహా సముద్రంలో శయనించేవాడు, అంతం చేసేవాడు.", "hi": "जीव, अनुशासन देने वाले, साक्षी, मुक्ति देने वाले मुकुंद, अपार पराक्रम वाले; समुद्र, अनंतात्मा, महासागर में शयन करने वाले, अंतक।", "names": [["jīvaḥ", "జీవః", "Who sustains life in all as the jīva", "జీవునిగా ప్రాణాలను నిలిపేవాడు", "जीव के रूप में प्राण धारण करने वाले"], ["vinayitā", "వినయితా", "Who guides and trains His people", "తన ప్రజలకు శిక్షణ ఇచ్చి నడిపించేవాడు", "अपनी प्रजा को शिक्षा और दिशा देने वाले"], ["sākṣī", "సాక్షీ", "The witness", "సాక్షి", "साक्षी"], ["mukundaḥ", "ముకుందః", "Giver of liberation", "ముక్తిని ఇచ్చేవాడు", "मुक्ति देने वाले"], ["amitavikramaḥ", "అమితవిక్రమః", "Of boundless stride and valour", "అపరిమిత పరాక్రమం గలవాడు", "असीम पराक्रम वाले"], ["ambhōnidhiḥ", "అంభోనిధిః", "The ocean, home of the waters", "జలాలకు నిలయమైన సముద్రం", "जल का निवास समुद्र"], ["anantātmā", "అనంతాత్మా", "The endless Self", "అనంతమైన ఆత్మ", "अनंत आत्मा"], ["mahōdadhiśayaḥ", "మహోదధిశయః", "Resting on the great ocean", "మహా సముద్రంలో శయనించేవాడు", "महासागर में शयन करने वाले"], ["antakaḥ", "అంతకః", "The one who brings all to an end", "అన్నిటినీ అంతం చేసేవాడు", "सबका अंत करने वाले"]] },
"vsn_56_56": { "en": "Unborn, most worthy of worship, ever true to His own nature, conqueror of enemies, giver of delight; bliss itself, delighting, rejoicing; true in dharma, the one of three strides.", "te": "పుట్టుక లేనివాడు, అత్యంత పూజ్యుడు, స్వభావ సిద్ధుడు, శత్రువులను జయించినవాడు, ఆనందం కలిగించేవాడు; ఆనంద స్వరూపుడు, ఆనందింపజేసేవాడు, సంతోషంగా ఉండేవాడు; సత్య ధర్ముడు, త్రివిక్రముడు.", "hi": "अजन्मा, परम पूज्य, स्वभाव से सिद्ध, शत्रुओं को जीतने वाले, आनंद देने वाले; स्वयं आनंद, आनंदित करने वाले, प्रसन्न; सत्य-धर्मा, त्रिविक्रम।", "names": [["ajaḥ", "అజః", "Unborn", "పుట్టుక లేనివాడు", "अजन्मा"], ["mahārhaḥ", "మహార్హః", "Most worthy of worship", "అత్యంత పూజ్యుడు", "परम पूज्य"], ["svābhāvyaḥ", "స్వాభావ్యః", "Always established in His own nature", "ఎల్లప్పుడూ తన స్వభావంలో నిలిచినవాడు", "सदा अपने स्वभाव में स्थित"], ["jitāmitraḥ", "జితామిత్రః", "Conqueror of inner and outer foes", "లోపలి బయటి శత్రువులను జయించినవాడు", "भीतर-बाहर के शत्रुओं को जीतने वाले"], ["pramōdanaḥ", "ప్రమోదనః", "Ever joyful, giving joy", "ఎప్పుడూ సంతోషంగా ఉండి ఆనందం పంచేవాడు", "सदा प्रसन्न और आनंद देने वाले"], ["ānandaḥ", "ఆనందః", "Bliss itself", "ఆనంద స్వరూపుడు", "स्वयं आनंद"], ["nandanaḥ", "నందనః", "The one who gladdens", "ఆనందింపజేసేవాడు", "आनंदित करने वाले"], ["nandaḥ", "నందః", "Full of all joys", "అన్ని ఆనందాలతో నిండినవాడు", "सब सुखों से पूर्ण"], ["satyadharmā", "సత్యధర్మా", "Whose dharma is true", "సత్యమైన ధర్మం గలవాడు", "सत्य धर्म वाले"], ["trivikramaḥ", "త్రివిక్రమః", "The one who covered the three worlds in three strides", "మూడు అడుగులతో మూడు లోకాలను కొలిచినవాడు", "तीन पगों में तीन लोक नापने वाले"]] },
"vsn_57_57": { "en": "The great sage Kapila, the teacher; grateful, lord of the earth; of three steps, overseer of the gods, the great-horned (fish), destroyer of death.", "te": "మహర్షి కపిలాచార్యుడు; కృతజ్ఞుడు, భూపతి; మూడు పదాలు గలవాడు, దేవతలకు అధ్యక్షుడు, గొప్ప కొమ్ము గల (మత్స్య) రూపుడు, మృత్యువును అంతం చేసేవాడు.", "hi": "महर्षि कपिलाचार्य; कृतज्ञ, पृथ्वीपति; तीन पदों वाले, देवताओं के अध्यक्ष, महान सींग वाले (मत्स्य), मृत्यु का अंत करने वाले।", "names": [["maharṣiḥ kapilāchāryaḥ", "మహర్షిః కపిలాచార్యః", "The great sage Kapila, teacher of Sāṅkhya", "సాంఖ్యాన్ని బోధించిన మహర్షి కపిలుడు", "सांख्य के आचार्य महर्षि कपिल"], ["kṛtajñaḥ", "కృతజ్ఞః", "Knower of the world and the Self", "జగత్తునూ ఆత్మనూ తెలిసినవాడు", "जगत और आत्मा के ज्ञाता"], ["mēdinīpatiḥ", "మేదినీపతిః", "Lord of the earth", "భూమికి పతి", "पृथ्वी के स्वामी"], ["tripadaḥ", "త్రిపదః", "The one of three steps", "మూడు అడుగులవాడు", "तीन पगों वाले"], ["tridaśādhyakṣaḥ", "త్రిదశాధ్యక్షః", "Overseer of the gods; witness of the three states", "దేవతలకు అధ్యక్షుడు; మూడు అవస్థలకు సాక్షి", "देवताओं के अध्यक्ष; तीन अवस्थाओं के साक्षी"], ["mahāśṛṅgaḥ", "మహాశృంగః", "The great-horned fish who towed the boat", "నావను లాగిన గొప్ప కొమ్ము గల మత్స్యం", "नाव खींचने वाले बड़े सींग वाले मत्स्य"], ["kṛtāntakṛt", "కృతాంతకృత్", "Destroyer of death", "మృత్యువును నాశనం చేసేవాడు", "मृत्यु का नाश करने वाले"]] },
"vsn_58_58": { "en": "The great boar, Govinda, with a fine army, wearing golden armlets; secret, profound, unfathomable, hidden, bearer of discus and mace.", "te": "మహావరాహుడు, గోవిందుడు, మంచి సేన గలవాడు, బంగారు భుజకీర్తులు ధరించినవాడు; రహస్యుడు, గంభీరుడు, అగాధుడు, దాగినవాడు, చక్రం గద ధరించినవాడు.", "hi": "महावराह, गोविंद, उत्तम सेना वाले, स्वर्ण बाजूबंद धारी; गुह्य, गंभीर, गहन, गुप्त, चक्र-गदाधारी।", "names": [["mahāvarāhaḥ", "మహావరాహః", "The great boar who lifted the earth", "భూమిని ఉద్ధరించిన మహావరాహుడు", "पृथ्वी को उठाने वाले महावराह"], ["gōvindaḥ", "గోవిందః", "The one who regained the earth", "భూమిని తిరిగి పొందినవాడు", "पृथ्वी को पुनः पाने वाले"], ["suṣēṇaḥ", "సుషేణః", "With a splendid army (His attendants)", "చక్కని సేన గలవాడు", "उत्तम सेना वाले"], ["kanakāṅgadī", "కనకాంగదీ", "Wearing golden armlets", "బంగారు కేయూరాలు ధరించినవాడు", "स्वर्ण बाजूबंद धारी"], ["guhyaḥ", "గుహ్యః", "Known only through the secret of the Upaniṣads", "ఉపనిషత్తుల రహస్యంతో తెలియబడేవాడు", "उपनिषदों के रहस्य से जाने जाने वाले"], ["gabhīraḥ", "గభీరః", "Deep and profound", "గంభీరుడు", "गंभीर"], ["gahanaḥ", "గహనః", "Hard to enter or fathom", "ప్రవేశించలేనంత అగాధుడు", "जिसकी थाह पाना कठिन"], ["guptaḥ", "గుప్తః", "Hidden from mind and speech", "మనసుకూ మాటకూ అందనివాడు", "मन और वाणी से छिपे"], ["chakragadādharaḥ", "చక్రగదాధరః", "Bearer of discus and mace", "చక్రం, గద ధరించినవాడు", "चक्र और गदा धारी"]] },
"vsn_59_59": { "en": "The creator, the self-sufficient, the unconquered, Kṛṣṇa, the firm, Saṅkarṣaṇa, the unfailing; Varuṇa and his son, the tree, lotus-eyed, great-minded.", "te": "సృష్టికర్త, తనకు తానే సాధనం, అజితుడు, కృష్ణుడు, దృఢుడు, సంకర్షణుడు, అచ్యుతుడు; వరుణుడు, వరుణుని కుమారుడు, వృక్షం, పుష్కరాక్షుడు, మహా మనస్కుడు.", "hi": "विधाता, स्वयं साधन, अजित, कृष्ण, दृढ़, संकर्षण, अच्युत; वरुण, वरुण-पुत्र, वृक्ष, पुष्कराक्ष, महामना।", "names": [["vēdhāḥ", "వేధాః", "The creator", "సృష్టికర్త", "सृष्टिकर्ता"], ["svāṅgaḥ", "స్వాంగః", "Himself the means of His own work", "తన పనికి తానే సాధనం", "अपने कार्य के स्वयं साधन"], ["ajitaḥ", "అజితః", "Never conquered", "ఎన్నడూ ఓడనివాడు", "कभी न जीते गए"], ["kṛṣṇaḥ", "కృష్ణః", "Kṛṣṇa, the dark one", "శ్రీకృష్ణుడు", "श्रीकृष्ण"], ["dṛḍhaḥ", "దృఢః", "Firm, unshakable", "దృఢుడు", "दृढ़"], ["saṅkarṣaṇō'chyutaḥ", "సంకర్షణోఽచ్యుతః", "The one who draws all in at dissolution, yet never falls", "ప్రళయంలో అన్నిటినీ ఆకర్షించేవాడు, అచ్యుతుడు", "प्रलय में सबको खींचने वाले, अच्युत"], ["varuṇaḥ", "వరుణః", "Varuṇa — the sun at evening drawing in its rays", "వరుణుడు — కిరణాలను ముడుచుకునే సాయంకాల సూర్యుడు", "वरुण — किरणें समेटने वाले संध्या-सूर्य"], ["vāruṇaḥ", "వారుణః", "Son of Varuṇa (Vasiṣṭha, Agastya)", "వరుణుని కుమారుడు (వసిష్ఠుడు, అగస్త్యుడు)", "वरुण-पुत्र (वसिष्ठ, अगस्त्य)"], ["vṛkṣaḥ", "వృక్షః", "Like a tree, firmly rooted", "వృక్షం వలె స్థిరంగా నిలిచినవాడు", "वृक्ष की तरह स्थिर"], ["puṣkarākṣaḥ", "పుష్కరాక్షః", "Lotus-eyed", "పుష్కరాల వంటి కన్నులవాడు", "कमल-नयन"], ["mahāmanāḥ", "మహామనాః", "Great-minded — creating, sustaining, ending by thought alone", "సంకల్పమాత్రంతో సృష్టి స్థితి లయాలు చేసే మహా మనస్కుడు", "संकल्प मात्र से सृष्टि-स्थिति-लय करने वाले महामना"]] },
"vsn_60_60": { "en": "The Blessed Lord, who takes away (at the end) all fortune, the joyful, wearing the forest garland, armed with the plough; Āditya, the light among suns, the patient, the best goal.", "te": "భగవంతుడు, ప్రళయంలో ఐశ్వర్యాన్ని హరించేవాడు, ఆనందమయుడు, వనమాల ధరించినవాడు, హలాయుధుడు (బలరాముడు); ఆదిత్యుడు, జ్యోతిర్మయ ఆదిత్యుడు, సహనశీలుడు, ఉత్తమ గతి.", "hi": "भगवान, प्रलय में ऐश्वर्य हरने वाले, आनंदमय, वनमाला धारी, हलायुध (बलराम); आदित्य, ज्योतिर्मय आदित्य, सहनशील, सर्वोत्तम गति।", "names": [["bhagavān", "భగవాన్", "Possessor of the six divine excellences", "షడ్గుణ ఐశ్వర్యాలు గల భగవంతుడు", "छह दिव्य ऐश्वर्यों वाले भगवान"], ["bhagahā", "భగహా", "The one who withdraws all glory at dissolution", "ప్రళయంలో ఐశ్వర్యాన్ని ఉపసంహరించేవాడు", "प्रलय में ऐश्वर्य को समेटने वाले"], ["ānandī", "ఆనందీ", "Full of bliss", "ఆనందమయుడు", "आनंदमय"], ["vanamālī", "వనమాలీ", "Wearing the Vaijayantī forest garland", "వైజయంతీ వనమాల ధరించినవాడు", "वैजयंती वनमाला धारी"], ["halāyudhaḥ", "హలాయుధః", "Armed with the plough (Balarāma)", "నాగలిని ఆయుధంగా గలవాడు (బలరాముడు)", "हल को अस्त्र बनाने वाले (बलराम)"], ["ādityaḥ", "ఆదిత్యః", "Son of Aditi (Vāmana)", "అదితి కుమారుడు (వామనుడు)", "अदिति-पुत्र (वामन)"], ["jyōtirādityaḥ", "జ్యోతిరాదిత్యః", "The light within the sun", "సూర్యమండలంలోని జ్యోతి", "सूर्यमंडल की ज्योति"], ["sahiṣṇuḥ", "సహిష్ణుః", "Bearing all pairs of opposites with patience", "ద్వంద్వాలను ఓర్పుతో సహించేవాడు", "द्वंद्वों को धैर्य से सहने वाले"], ["gatisattamaḥ", "గతిసత్తమః", "The best of all refuges", "ఆశ్రయాలన్నిటిలో ఉత్తమం", "सब आश्रयों में श्रेष्ठ"]] },
"vsn_61_61": { "en": "Wielder of a fine bow, of the axe that breaks foes, fierce to the wicked, giver of wealth; touching the heavens, all-seeing, Vyāsa, lord of speech, born of no womb.", "te": "చక్కని ధనుస్సు గలవాడు, శత్రువులను ఖండించే గొడ్డలి గలవాడు (పరశురాముడు), దుష్టులకు భయంకరుడు, ధనం ఇచ్చేవాడు; స్వర్గాన్ని తాకేవాడు, సర్వదర్శి, వ్యాసుడు, వాచస్పతి, గర్భంలో పుట్టనివాడు.", "hi": "उत्तम धनुष वाले, शत्रुओं को खंडित करने वाले परशु धारी (परशुराम), दुष्टों के लिए भयंकर, धन देने वाले; स्वर्ग को छूने वाले, सर्वदर्शी, व्यास, वाचस्पति, गर्भ से न जन्मे।", "names": [["sudhanvā", "సుధన్వా", "With the fine bow Śārṅga", "శార్ఙ్గమనే చక్కని ధనుస్సు గలవాడు", "शार्ङ्ग नामक उत्तम धनुष वाले"], ["khaṇḍaparaśuḥ", "ఖండపరశుః", "Whose axe cuts down foes (Paraśurāma)", "శత్రువులను ఖండించే పరశువు గలవాడు (పరశురాముడు)", "शत्रुओं को काटने वाले परशु वाले (परशुराम)"], ["dāruṇaḥ", "దారుణః", "Terrible to the unrighteous", "అధర్మాత్ములకు భయంకరుడు", "अधर्मियों के लिए भयंकर"], ["draviṇapradaḥ", "ద్రవిణప్రదః", "Giver of the wealth devotees long for", "భక్తులు కోరిన ధనాన్ని ఇచ్చేవాడు", "भक्तों को इच्छित धन देने वाले"], ["divaḥspṛk", "దివఃస్పృక్", "Touching the sky", "ఆకాశాన్ని తాకేవాడు", "आकाश को छूने वाले"], ["sarvadṛk", "సర్వదృక్", "Seeing all", "అన్నిటినీ చూసేవాడు", "सब देखने वाले"], ["vyāsaḥ", "వ్యాసః", "Vyāsa, who arranged the Veda", "వేదాలను విభజించిన వ్యాసుడు", "वेदों का विभाग करने वाले व्यास"], ["vāchaspatiḥ", "వాచస్పతిః", "Lord of speech and learning", "వాక్కుకూ విద్యకూ పతి", "वाणी और विद्या के स्वामी"], ["ayōnijaḥ", "అయోనిజః", "Not born from a womb", "గర్భంలో పుట్టనివాడు", "गर्भ से न जन्मे"]] },
"vsn_62_62": { "en": "Praised by the three Sāmans, the singer of Sāma, Sāma itself; liberation, the medicine and the physician; the one who established sannyāsa, calm, peaceful, the final rest, peace, the highest refuge.", "te": "మూడు సామాలతో స్తుతించబడేవాడు, సామగానం చేసేవాడు, సామవేదం తానే; నిర్వాణం, ఔషధం, వైద్యుడు; సన్న్యాసాన్ని ఏర్పరచినవాడు, శమం, శాంతుడు, నిష్ఠ, శాంతి, పరమ ఆశ్రయం.", "hi": "तीन सामों से स्तुत, साम-गायक, स्वयं साम; निर्वाण, औषधि, वैद्य; संन्यास के स्थापक, शम, शांत, निष्ठा, शांति, परम आश्रय।", "names": [["trisāmā", "త్రిసామా", "Praised by the three Sāma chants", "మూడు సామాలతో స్తుతించబడేవాడు", "तीन सामों से स्तुत"], ["sāmagaḥ", "సామగః", "Singer of the Sāma", "సామగానం చేసేవాడు", "साम-गान करने वाले"], ["sāma", "సామ", "The Sāmaveda itself", "సామవేదం తానే", "स्वयं सामवेद"], ["nirvāṇam", "నిర్వాణం", "Supreme bliss beyond all sorrow", "దుఃఖం లేని పరమానందం", "दुःख-रहित परमानंद"], ["bhēṣajam", "భేషజం", "The medicine for worldly suffering", "సంసార వ్యాధికి మందు", "संसार-रोग की दवा"], ["bhiṣak", "భిషక్", "The physician (who taught the Gītā)", "వైద్యుడు (గీతను బోధించినవాడు)", "वैद्य (गीता के उपदेशक)"], ["sannyāsakṛt", "సన్న్యాసకృత్", "Founder of the path of renunciation", "సన్న్యాస ఆశ్రమాన్ని ఏర్పరచినవాడు", "संन्यास-मार्ग के स्थापक"], ["śamaḥ", "శమః", "Calm — teacher of inner restraint", "శమం — మనో నిగ్రహం నేర్పేవాడు", "शम — मन के संयम के उपदेशक"], ["śāntaḥ", "శాంతః", "Peaceful", "శాంతుడు", "शांत"], ["niṣṭhā", "నిష్ఠా", "The final resting place of all", "అన్నిటికీ అంతిమ స్థానం", "सबका अंतिम स्थान"], ["śāntiḥ", "శాంతిః", "Peace itself", "శాంతి స్వరూపుడు", "स्वयं शांति"], ["parāyaṇam", "పరాయణం", "The supreme refuge", "పరమ ఆశ్రయం", "परम आश्रय"]] },
"vsn_63_63": { "en": "Of beautiful limbs, giver of peace, the creator, delighting the earth, resting on the waters; friend of cows, lord of cows, the protector, bull-eyed, fond of dharma.", "te": "అందమైన అవయవాలవాడు, శాంతినిచ్చేవాడు, సృష్టికర్త, భూమికి ఆనందం ఇచ్చేవాడు, జలాలపై శయనించేవాడు; గోవుల హితుడు, గోపతి, రక్షకుడు, వృషభ నేత్రుడు, ధర్మప్రియుడు.", "hi": "सुंदर अंगों वाले, शांति देने वाले, सृष्टा, पृथ्वी को आनंद देने वाले, जल में शयन करने वाले; गौ-हितैषी, गोपति, रक्षक, वृषभ-नेत्र, धर्मप्रिय।", "names": [["śubhāṅgaḥ", "శుభాంగః", "Of beautiful form", "అందమైన రూపం గలవాడు", "सुंदर रूप वाले"], ["śāntidaḥ", "శాంతిదః", "Giver of peace", "శాంతిని ఇచ్చేవాడు", "शांति देने वाले"], ["sraṣṭā", "స్రష్టా", "Creator of all", "సర్వ సృష్టికర్త", "सबके सृष्टा"], ["kumudaḥ", "కుముదః", "Rejoicing in the earth", "భూమిలో ఆనందించేవాడు", "पृथ्वी में आनंदित"], ["kuvalēśayaḥ", "కువలేశయః", "Resting on the waters around the earth (on Śeṣa)", "భూమిని చుట్టిన జలాలపై శేషునిపై శయనించేవాడు", "पृथ्वी को घेरे जल पर शेष पर शयन करने वाले"], ["gōhitaḥ", "గోహితః", "Well-wisher of cows", "గోవుల హితుడు", "गौओं के हितैषी"], ["gōpatiḥ", "గోపతిః", "Lord of cows / of the earth", "గోపతి / భూపతి", "गोपति / भूपति"], ["gōptā", "గోప్తా", "Protector of the universe", "విశ్వాన్ని రక్షించేవాడు", "विश्व के रक्षक"], ["vṛṣabhākṣaḥ", "వృషభాక్షః", "Whose eyes shower blessings", "చూపుతో వరాలు కురిపించేవాడు", "दृष्टि से वर बरसाने वाले"], ["vṛṣapriyaḥ", "వృషప్రియః", "Lover of dharma", "ధర్మాన్ని ప్రేమించేవాడు", "धर्म-प्रेमी"]] },
"vsn_64_64": { "en": "Never turning back from battle or from dharma, yet turned away from the senses; the one who contracts all, doer of welfare, auspicious; with the Śrīvatsa on His chest, the abode, lord and best of Śrī.", "te": "యుద్ధం నుండి, ధర్మం నుండి వెనుదిరగనివాడు, విషయాల నుండి వెనుదిరిగినవాడు; ప్రళయంలో అన్నిటినీ సంక్షిప్తం చేసేవాడు, క్షేమం కలిగించేవాడు, శివుడు; శ్రీవత్స వక్షస్థలుడు, శ్రీ నివాసం, శ్రీపతి, శ్రీమంతులలో శ్రేష్ఠుడు.", "hi": "युद्ध और धर्म से कभी न लौटने वाले, विषयों से निवृत्त; प्रलय में सबको संक्षिप्त करने वाले, कल्याणकारी, शिव; श्रीवत्स-वक्ष, श्री के निवास, श्रीपति, श्रीमानों में श्रेष्ठ।", "names": [["anivartī", "అనివర్తీ", "Never retreating from battle or dharma", "యుద్ధం, ధర్మం నుండి వెనుదిరగనివాడు", "युद्ध और धर्म से न लौटने वाले"], ["nivṛttātmā", "నివృత్తాత్మా", "Whose mind is turned away from sense-objects", "విషయాల నుండి మనసు మరలించినవాడు", "विषयों से विमुख मन वाले"], ["saṅkṣēptā", "సంక్షేప్తా", "The one who draws the vast world back into the subtle", "విశాల ప్రపంచాన్ని సూక్ష్మంలోకి ఇముడ్చుకునేవాడు", "विशाल जगत को सूक्ष्म में समेटने वाले"], ["kṣēmakṛt", "క్షేమకృత్", "Protector of what has been gained", "పొందినదాన్ని కాపాడేవాడు", "प्राप्त की रक्षा करने वाले"], ["śivaḥ", "శివః", "The auspicious, purifying by His name", "నామంతోనే పవిత్రం చేసే మంగళకరుడు", "नाम से ही पवित्र करने वाले मंगलमय"], ["śrīvatsavakṣāḥ", "శ్రీవత్సవక్షాః", "With the Śrīvatsa mark on His chest", "వక్షస్థలంపై శ్రీవత్స చిహ్నం గలవాడు", "वक्ष पर श्रीवत्स चिह्न वाले"], ["śrīvāsaḥ", "శ్రీవాసః", "Abode of Śrī", "శ్రీకి నివాసం", "श्री के निवास"], ["śrīpatiḥ", "శ్రీపతిః", "Lord of Śrī", "శ్రీపతి", "श्रीपति"], ["śrīmatāṃ varaḥ", "శ్రీమతాం వరః", "Best of the glorious", "శ్రీమంతులలో శ్రేష్ఠుడు", "श्रीमानों में श्रेष्ठ"]] },
"vsn_65_65": { "en": "Giver of Śrī, lord of Śrī, in whom Śrī dwells, treasure of Śrī, who gives Śrī by deeds; bearer of Śrī, maker of Śrī, the highest good, glorious, refuge of the three worlds.", "te": "శ్రీని ఇచ్చేవాడు, శ్రీకి ఈశుడు, శ్రీనివాసుడు, శ్రీనిధి, కర్మలకు తగిన శ్రీని పంచేవాడు; శ్రీధరుడు, శ్రీకరుడు, శ్రేయస్సు, శ్రీమంతుడు, మూడు లోకాలకు ఆశ్రయం.", "hi": "श्री देने वाले, श्री के ईश, श्रीनिवास, श्रीनिधि, कर्मों के अनुसार श्री बाँटने वाले; श्रीधर, श्रीकर, श्रेय, श्रीमान, तीनों लोकों के आश्रय।", "names": [["śrīdaḥ", "శ్రీదః", "Giver of prosperity to devotees", "భక్తులకు శ్రీని ఇచ్చేవాడు", "भक्तों को श्री देने वाले"], ["śrīśaḥ", "శ్రీశః", "Lord of Śrī", "శ్రీకి ఈశ్వరుడు", "श्री के ईश"], ["śrīnivāsaḥ", "శ్రీనివాసః", "Dwelling in the virtuous, who have Śrī", "శ్రీమంతులైన సజ్జనులలో నివసించేవాడు", "श्रीयुक्त सज्जनों में बसने वाले"], ["śrīnidhiḥ", "శ్రీనిధిః", "Treasure-house of all glory", "సమస్త శ్రీకి నిధి", "सब श्री का भंडार"], ["śrīvibhāvanaḥ", "శ్రీవిభావనః", "Who distributes fortune by each one's deeds", "కర్మానుసారం శ్రీని పంచేవాడు", "कर्मानुसार श्री बाँटने वाले"], ["śrīdharaḥ", "శ్రీధరః", "Bearing Śrī on His chest", "వక్షంలో శ్రీని ధరించినవాడు", "वक्ष पर श्री धारण करने वाले"], ["śrīkaraḥ", "శ్రీకరః", "Maker of prosperity", "శ్రీని కలిగించేవాడు", "श्री उत्पन्न करने वाले"], ["śrēyaḥ", "శ్రేయః", "The highest good — liberation", "పరమ శ్రేయస్సు — మోక్షం", "परम श्रेय — मोक्ष"], ["śrīmān", "శ్రీమాన్", "Glorious", "శ్రీమంతుడు", "श्रीमान"], ["lōkatrayāśrayaḥ", "లోకత్రయాశ్రయః", "Refuge of the three worlds", "మూడు లోకాలకు ఆశ్రయం", "तीनों लोकों के आश्रय"]] },
"vsn_66_66": { "en": "Fair-eyed, fair-limbed, of a hundred joys, the joyful, the light, lord of the hosts; self-mastered, ruled by none, of true fame, the dispeller of doubt.", "te": "అందమైన కన్నులు, అందమైన అవయవాలు గలవాడు, అనంత ఆనందం గలవాడు, నంది, జ్యోతి, గణాలకు ఈశ్వరుడు; మనసును జయించినవాడు, ఎవరికీ లొంగనివాడు, సత్కీర్తి గలవాడు, సందేహాలను పోగొట్టేవాడు.", "hi": "सुंदर नेत्रों और सुंदर अंगों वाले, अनंत आनंद वाले, नंदी, ज्योति, गणों के ईश्वर; मन को जीतने वाले, किसी के अधीन नहीं, सत्कीर्ति वाले, संशय मिटाने वाले।", "names": [["svakṣaḥ", "స్వక్షః", "Beautiful-eyed", "అందమైన కన్నులవాడు", "सुंदर नेत्रों वाले"], ["svaṅgaḥ", "స్వంగః", "Beautiful-limbed", "అందమైన అవయవాలవాడు", "सुंदर अंगों वाले"], ["śatānandaḥ", "శతానందః", "Of countless joys", "అనంత ఆనందాలు గలవాడు", "अनंत आनंदों वाले"], ["nandiḥ", "నందిః", "Supreme bliss", "పరమానందం", "परम आनंद"], ["jyōtirgaṇēśvaraḥ", "జ్యోతిర్గణేశ్వరః", "Lord of the hosts of lights (stars)", "జ్యోతిర్గణాలకు ఈశ్వరుడు", "ज्योतिर्गणों के ईश्वर"], ["vijitātmā", "విజితాత్మా", "Master of His own mind", "మనసును జయించినవాడు", "मन को जीतने वाले"], ["avidhēyātmā", "అవిధేయాత్మా", "Subject to no one's command", "ఎవరి ఆజ్ఞకూ లొంగనివాడు", "किसी के आदेश के अधीन नहीं"], ["satkīrtiḥ", "సత్కీర్తిః", "Of true renown", "సత్యమైన కీర్తి గలవాడు", "सच्ची कीर्ति वाले"], ["chinnasaṃśayaḥ", "చిన్నసంశయః", "Free of all doubt", "సందేహాలు లేనివాడు", "सब संशयों से रहित"]] },
"vsn_67_67": { "en": "Exalted above all, with eyes on every side, with no master over Him, eternal and steady; lying on the earth, adorning it, the glory, free from grief and the destroyer of grief.", "te": "అందరికంటే ఉన్నతుడు, అన్ని వైపులా కన్నులు గలవాడు, తనకు ఈశుడు లేనివాడు, శాశ్వతుడు, స్థిరుడు; భూమిపై శయనించినవాడు, భూమిని అలంకరించేవాడు, విభూతి, శోకం లేనివాడు, శోకాన్ని నాశనం చేసేవాడు.", "hi": "सबसे ऊँचे, सब ओर नेत्रों वाले, जिनका कोई स्वामी नहीं, शाश्वत और स्थिर; पृथ्वी पर शयन करने वाले, पृथ्वी के आभूषण, विभूति, शोक-रहित, शोक नाशक।", "names": [["udīrṇaḥ", "ఉదీర్ణః", "Raised above all beings", "అందరికంటే ఉన్నతుడు", "सबसे ऊपर उठे हुए"], ["sarvataśchakṣuḥ", "సర్వతశ్చక్షుః", "With eyes on every side", "అన్ని వైపులా కన్నులు గలవాడు", "सब ओर नेत्रों वाले"], ["anīśaḥ", "అనీశః", "Having no lord over Him", "తనకు ప్రభువు లేనివాడు", "जिनका कोई स्वामी नहीं"], ["śāśvatasthiraḥ", "శాశ్వతస్థిరః", "Eternal and unchanging", "శాశ్వతుడు, మార్పు లేనివాడు", "शाश्वत और अपरिवर्तनशील"], ["bhūśayaḥ", "భూశయః", "Who lay on the ground (Rāma at the sea-shore)", "సముద్ర తీరంలో నేలపై పడుకున్నవాడు (శ్రీరాముడు)", "समुद्र-तट पर भूमि पर सोने वाले (श्रीराम)"], ["bhūṣaṇaḥ", "భూషణః", "Who adorns the world with His avatāras", "అవతారాలతో లోకాన్ని అలంకరించేవాడు", "अवतारों से जगत को सजाने वाले"], ["bhūtiḥ", "భూతిః", "Glory itself; existence", "విభూతి; సత్తా", "विभूति; सत्ता"], ["viśōkaḥ", "విశోకః", "Beyond grief", "శోకం లేనివాడు", "शोक-रहित"], ["śōkanāśanaḥ", "శోకనాశనః", "Destroyer of devotees' grief", "భక్తుల శోకాన్ని నశింపజేసేవాడు", "भक्तों के शोक का नाश करने वाले"]] },
"vsn_68_68": { "en": "Radiant, worshipped, the pot that holds all, of pure Self, the purifier; Aniruddha, unrivalled in battle, Pradyumna, of boundless valour.", "te": "తేజోమయుడు, పూజించబడేవాడు, అన్నిటినీ తనలో నిలుపుకున్న కుంభం, విశుద్ధాత్మ, పవిత్రం చేసేవాడు; అనిరుద్ధుడు, ఎదురులేనివాడు, ప్రద్యుమ్నుడు, అపరిమిత పరాక్రమం గలవాడు.", "hi": "तेजस्वी, पूजित, सबको अपने में रखने वाले कुंभ, विशुद्धात्मा, शुद्ध करने वाले; अनिरुद्ध, जिनका कोई प्रतिद्वंद्वी नहीं, प्रद्युम्न, असीम पराक्रमी।", "names": [["archiṣmān", "అర్చిష్మాన్", "From whom the sun and moon get their rays", "సూర్యచంద్రులకు కాంతినిచ్చేవాడు", "सूर्य-चंद्र को किरणें देने वाले"], ["architaḥ", "అర్చితః", "Worshipped in all the worlds", "అన్ని లోకాలలో పూజించబడేవాడు", "सब लोकों में पूजित"], ["kumbhaḥ", "కుంభః", "Holding everything within, like a pot", "కుండలా అన్నిటినీ తనలో ఉంచుకున్నవాడు", "घड़े की तरह सबको अपने में रखने वाले"], ["viśuddhātmā", "విశుద్ధాత్మా", "Pure, beyond the three guṇas", "త్రిగుణాతీతుడు, విశుద్ధుడు", "त्रिगुणातीत, विशुद्ध"], ["viśōdhanaḥ", "విశోధనః", "Who cleanses sin by remembrance", "స్మరణతో పాపాలను శుద్ధి చేసేవాడు", "स्मरण से पाप धोने वाले"], ["aniruddhaḥ", "అనిరుద్ధః", "Unstoppable (one of the four vyūhas)", "ఎవరూ ఆపలేనివాడు (చతుర్వ్యూహాలలో ఒకరు)", "जिन्हें रोका न जा सके (चतुर्व्यूह में एक)"], ["apratirathaḥ", "అప్రతిరథః", "Without any rival", "ప్రత్యర్థి లేనివాడు", "जिनका कोई प्रतिद्वंद्वी नहीं"], ["pradyumnaḥ", "ప్రద్యుమ్నః", "Of great wealth and splendour (one of the vyūhas)", "గొప్ప సంపద, తేజస్సు గలవాడు (వ్యూహాలలో ఒకరు)", "महान धन और तेज वाले (व्यूह में एक)"], ["amitavikramaḥ", "అమితవిక్రమః", "Of boundless prowess", "అపరిమిత పరాక్రముడు", "असीम पराक्रमी"]] },
"vsn_69_69": { "en": "Slayer of Kālanemi, the hero, Śauri, lord of heroes and people; the Self and lord of the three worlds, Keśava, slayer of Keśī, Hari.", "te": "కాలనేమిని సంహరించినవాడు, వీరుడు, శౌరి, శూరులకూ జనులకూ ఈశ్వరుడు; మూడు లోకాలకు ఆత్మ, మూడు లోకాలకు ఈశుడు, కేశవుడు, కేశిని సంహరించినవాడు, హరి.", "hi": "कालनेमि के संहारक, वीर, शौरि, शूरों और जनों के ईश्वर; तीनों लोकों की आत्मा और स्वामी, केशव, केशी के वधकर्ता, हरि।", "names": [["kālanēminihā", "కాలనేమినిహా", "Slayer of the demon Kālanemi", "కాలనేమిని సంహరించినవాడు", "कालनेमि दैत्य के संहारक"], ["vīraḥ", "వీరః", "The hero", "వీరుడు", "वीर"], ["śauriḥ", "శౌరిః", "Born in the line of Śūra", "శూరుని వంశంలో పుట్టినవాడు", "शूर-वंश में जन्मे"], ["śūrajanēśvaraḥ", "శూరజనేశ్వరః", "Lord of the mighty, even of Indra", "శూరులకు, ఇంద్రాదులకు ఈశ్వరుడు", "शूरों और इंद्रादि के ईश्वर"], ["trilōkātmā", "త్రిలోకాత్మా", "The Self of the three worlds", "మూడు లోకాలకు ఆత్మ", "तीनों लोकों की आत्मा"], ["trilōkēśaḥ", "త్రిలోకేశః", "Lord of the three worlds", "మూడు లోకాలకు ఈశుడు", "तीनों लोकों के ईश"], ["kēśavaḥ", "కేశవః", "Whose rays are His hair; lord of Brahmā and Śiva", "కిరణాలే కేశాలుగా గలవాడు; బ్రహ్మ శివులకు ప్రభువు", "किरणें ही जिनके केश हैं; ब्रह्मा-शिव के स्वामी"], ["kēśihā", "కేశిహా", "Slayer of the horse-demon Keśī", "అశ్వ రాక్షసుడు కేశిని సంహరించినవాడు", "अश्व-दैत्य केशी के संहारक"], ["hariḥ", "హరిః", "Who removes saṃsāra and its cause", "సంసారాన్నీ దాని కారణాన్నీ హరించేవాడు", "संसार और उसके कारण को हरने वाले"]] },
"vsn_70_70": { "en": "The god of love, protector of desires, the lover, the lovely, maker of the scriptures; of indescribable form, Viṣṇu, the hero, the endless, Dhanañjaya (Arjuna).", "te": "కామదేవుడు, కోరికలను కాపాడేవాడు, కామి, కాంతుడు, ఆగమాలను రచించినవాడు; వర్ణించలేని రూపం గలవాడు, విష్ణువు, వీరుడు, అనంతుడు, ధనంజయుడు.", "hi": "कामदेव, कामनाओं के रक्षक, कामी, कांत, आगमों के रचयिता; अवर्णनीय रूप वाले, विष्णु, वीर, अनंत, धनंजय।", "names": [["kāmadēvaḥ", "కామదేవః", "Desired by those seeking all four goals", "నాలుగు పురుషార్థాలు కోరేవారు కోరుకునే దేవుడు", "चारों पुरुषार्थ चाहने वालों के काम्य देव"], ["kāmapālaḥ", "కామపాలః", "Protector of what devotees desire", "భక్తుల కోరికలను కాపాడేవాడు", "भक्तों की कामनाओं के रक्षक"], ["kāmī", "కామీ", "One whose desires are all fulfilled", "కోరికలన్నీ నెరవేరినవాడు", "जिनकी सब कामनाएँ पूर्ण हैं"], ["kāntaḥ", "కాంతః", "Of enchanting beauty", "మనోహర సౌందర్యం గలవాడు", "मोहक सौंदर्य वाले"], ["kṛtāgamaḥ", "కృతాగమః", "Author of the scriptures (āgamas)", "ఆగమాలను రచించినవాడు", "आगमों के रचयिता"], ["anirdēśyavapuḥ", "అనిర్దేశ్యవపుః", "Whose form cannot be defined", "నిర్వచించలేని రూపం గలవాడు", "जिनका रूप परिभाषित नहीं हो सकता"], ["viṣṇuḥ", "విష్ణుః", "Pervading heaven and earth", "భూమ్యాకాశాలలో వ్యాపించినవాడు", "पृथ्वी और आकाश में व्याप्त"], ["vīraḥ", "వీరః", "Ever in motion, the hero", "నిరంతరం కదిలే వీరుడు", "सदा गतिशील वीर"], ["anantaḥ", "అనంతః", "Without end", "అంతం లేనివాడు", "अंत-रहित"], ["dhanañjayaḥ", "ధనంజయః", "Arjuna, who won wealth — a form of Him", "ధనాన్ని జయించిన అర్జునుడు — ఆయన విభూతి", "धन जीतने वाले अर्जुन — उनकी विभूति"]] },
"vsn_71_71": { "en": "Devoted to Brahman (tapas, Veda, the knowers), its maker, Brahmā, Brahman itself, the one who increases it; knower of the Veda, the brāhmaṇa, holder of Brahman, knower of Brahman, dear to the brāhmaṇas.", "te": "బ్రహ్మకు (తపస్సు, వేదం, బ్రాహ్మణులు) హితుడు, బ్రహ్మను సృష్టించేవాడు, బ్రహ్మ, పరబ్రహ్మ, బ్రహ్మను వృద్ధి చేసేవాడు; వేదవిదుడు, బ్రాహ్మణుడు, బ్రహ్మి, బ్రహ్మజ్ఞుడు, బ్రాహ్మణ ప్రియుడు.", "hi": "ब्रह्म (तप, वेद, ब्राह्मण) के हितैषी, ब्रह्म के कर्ता, ब्रह्मा, परब्रह्म, ब्रह्म को बढ़ाने वाले; वेदवेत्ता, ब्राह्मण, ब्रह्मी, ब्रह्मज्ञ, ब्राह्मण-प्रिय।", "names": [["brahmaṇyaḥ", "బ్రహ్మణ్యః", "Friend of tapas, the Veda and the wise", "తపస్సుకు, వేదానికి, జ్ఞానులకు హితుడు", "तप, वेद और ज्ञानियों के हितैषी"], ["brahmakṛt", "బ్రహ్మకృత్", "Doer of tapas and the Vedic rites", "తపస్సును, వైదిక కర్మలను చేసేవాడు", "तप और वैदिक कर्मों के कर्ता"], ["brahmā", "బ్రహ్మా", "Brahmā, the creator", "సృష్టికర్త బ్రహ్మ", "सृष्टिकर्ता ब्रह्मा"], ["brahma", "బ్రహ్మ", "Brahman — infinite truth, knowledge and bliss", "పరబ్రహ్మ — సత్యం జ్ఞానం ఆనందం", "परब्रह्म — सत्य, ज्ञान, आनंद"], ["brahmavivardhanaḥ", "బ్రహ్మవివర్ధనః", "Who makes tapas and dharma grow", "తపస్సును ధర్మాన్ని వృద్ధి చేసేవాడు", "तप और धर्म को बढ़ाने वाले"], ["brahmavit", "బ్రహ్మవిత్", "Knower of the Veda", "వేదాన్ని తెలిసినవాడు", "वेद के ज्ञाता"], ["brāhmaṇaḥ", "బ్రాహ్మణః", "The teacher of the Veda (as a brāhmaṇa)", "బ్రాహ్మణునిగా వేదాన్ని బోధించేవాడు", "ब्राह्मण रूप में वेद के उपदेशक"], ["brahmī", "బ్రహ్మీ", "In whom all that is Brahman rests", "బ్రహ్మకు సంబంధించినవన్నీ ఆయనలోనే", "ब्रह्म-संबंधी सब जिनमें स्थित है"], ["brahmajñaḥ", "బ్రహ్మజ్ఞః", "Knower of the Veda as His own Self", "వేదాన్ని తన స్వరూపంగా తెలిసినవాడు", "वेद को अपना स्वरूप जानने वाले"], ["brāhmaṇapriyaḥ", "బ్రాహ్మణప్రియః", "Dear to the wise, and loving them", "జ్ఞానులకు ప్రియుడు, వారిని ప్రేమించేవాడు", "ज्ञानियों के प्रिय और उनसे प्रेम करने वाले"]] },
"vsn_72_72": { "en": "Of great strides and great deeds, of great brilliance, the great serpent; the great rite, the great sacrificer, the great yajña, the great offering.", "te": "గొప్ప అడుగులు, గొప్ప కర్మలు, గొప్ప తేజస్సు గలవాడు, మహా సర్పం; మహా క్రతువు, మహా యజ్వ (యజ్ఞకర్త), మహా యజ్ఞం, మహా హవిస్సు.", "hi": "महान पग और महान कर्मों वाले, महातेजस्वी, महासर्प; महाक्रतु, महायज्वा, महायज्ञ, महाहवि।", "names": [["mahākramaḥ", "మహాక్రమః", "Of great strides", "గొప్ప అడుగులవాడు", "महान पगों वाले"], ["mahākarmā", "మహాకర్మా", "Doer of great works — creating the world", "జగత్సృష్టి వంటి మహా కర్మలు చేసేవాడు", "जगत-सृष्टि जैसे महान कर्म करने वाले"], ["mahātējāḥ", "మహాతేజాః", "Of great brilliance", "మహా తేజస్సు గలవాడు", "महातेजस्वी"], ["mahōragaḥ", "మహోరగః", "The great serpent (Vāsuki)", "మహా సర్పం (వాసుకి)", "महासर्प (वासुकि)"], ["mahākratuḥ", "మహాక్రతుః", "The great rite (aśvamedha)", "మహా క్రతువు (అశ్వమేధం)", "महाक्रतु (अश्वमेध)"], ["mahāyajvā", "మహాయజ్వా", "The great performer of yajña", "గొప్ప యజ్ఞకర్త", "महान यज्ञकर्ता"], ["mahāyajñaḥ", "మహాయజ్ఞః", "The great yajña of japa", "జపయజ్ఞమనే మహా యజ్ఞం", "जपयज्ञ रूपी महायज्ञ"], ["mahāhaviḥ", "మహాహవిః", "The great offering", "మహా హవిస్సు", "महाहवि"]] },
"vsn_73_73": { "en": "Worthy of praise, fond of praise, the hymn, the praise, the one who praises, fond of battle; complete, the one who fills, holy, of holy fame, free from illness.", "te": "స్తుతించదగినవాడు, స్తోత్రప్రియుడు, స్తోత్రం, స్తుతి, స్తుతించేవాడు, యుద్ధప్రియుడు; పూర్ణుడు, నింపేవాడు, పుణ్యుడు, పుణ్యకీర్తి, రోగం లేనివాడు.", "hi": "स्तुति योग्य, स्तुति-प्रिय, स्तोत्र, स्तुति, स्तुति करने वाले, युद्ध-प्रिय; पूर्ण, पूर्ण करने वाले, पुण्य, पुण्यकीर्ति, निरोग।", "names": [["stavyaḥ", "స్తవ్యః", "Worthy of all praise", "అందరిచేత స్తుతించదగినవాడు", "सबसे स्तुत्य"], ["stavapriyaḥ", "స్తవప్రియః", "Pleased by praise", "స్తోత్రాలకు ప్రసన్నుడయ్యేవాడు", "स्तुति से प्रसन्न"], ["stōtram", "స్తోత్రం", "The hymn itself", "స్తోత్రం తానే", "स्वयं स्तोत्र"], ["stutiḥ", "స్తుతిః", "The act of praise", "స్తుతి", "स्तुति"], ["stōtā", "స్తోతా", "The one who praises", "స్తుతించేవాడు", "स्तुति करने वाले"], ["raṇapriyaḥ", "రణప్రియః", "Fond of battle (against evil)", "అధర్మంపై యుద్ధాన్ని ఇష్టపడేవాడు", "अधर्म के विरुद्ध युद्ध-प्रिय"], ["pūrṇaḥ", "పూర్ణః", "Complete in every way", "అన్ని విధాలా పూర్ణుడు", "हर प्रकार से पूर्ण"], ["pūrayitā", "పూరయితా", "Who fills devotees with all they need", "భక్తులకు కావలసినవన్నీ నింపేవాడు", "भक्तों को सब कुछ देकर पूर्ण करने वाले"], ["puṇyaḥ", "పుణ్యః", "Holy, making holy", "పుణ్యుడు, పవిత్రం చేసేవాడు", "पुण्य, पवित्र करने वाले"], ["puṇyakīrtiḥ", "పుణ్యకీర్తిః", "Whose fame is holy", "పవిత్రమైన కీర్తి గలవాడు", "पवित्र कीर्ति वाले"], ["anāmayaḥ", "అనామయః", "Free from all illness", "ఏ రోగమూ లేనివాడు", "सब रोगों से रहित"]] },
"vsn_74_74": { "en": "Swift as the mind, maker of the sacred fords (learning), whose seed is gold, giver of wealth; giver of liberation, Vāsudeva, the dwelling, the generous-minded, the offering.", "te": "మనోవేగం గలవాడు, తీర్థాలను (విద్యలను) ఏర్పరచినవాడు, బంగారు బీజం గలవాడు, ధనం ఇచ్చేవాడు; మోక్షాన్ని ఇచ్చేవాడు, వాసుదేవుడు, వసువు, ఉదార మనస్కుడు, హవిస్సు.", "hi": "मन के समान वेग वाले, तीर्थों (विद्याओं) के रचयिता, स्वर्ण-बीज वाले, धन देने वाले; मोक्ष देने वाले, वासुदेव, वसु, उदार मन वाले, हवि।", "names": [["manōjavaḥ", "మనోజవః", "Swift as the mind", "మనసు వంటి వేగం గలవాడు", "मन के समान वेगवान"], ["tīrthakaraḥ", "తీర్థకరః", "Founder of the fourteen branches of learning", "పద్నాలుగు విద్యలకు ప్రవర్తకుడు", "चौदह विद्याओं के प्रवर्तक"], ["vasurētāḥ", "వసురేతాః", "Whose seed is gold", "బంగారమే బీజంగా గలవాడు", "स्वर्ण ही जिनका बीज है"], ["vasupradaḥ", "వసుప్రదః", "Giver of wealth", "ధనాన్ని ఇచ్చేవాడు", "धन देने वाले"], ["vasupradaḥ", "వసుప్రదః", "Giver of the highest wealth — liberation", "మోక్షమనే పరమ ధనాన్ని ఇచ్చేవాడు", "मोक्ष रूपी परम धन देने वाले"], ["vāsudēvaḥ", "వాసుదేవః", "Son of Vasudeva", "వసుదేవుని కుమారుడు", "वसुदेव-पुत्र"], ["vasuḥ", "వసుః", "In whom all dwell", "అందరూ నివసించే ఆధారం", "जिनमें सब बसते हैं"], ["vasumanāḥ", "వసుమనాః", "Whose mind dwells equally in all", "అందరిలో సమంగా ఉండే మనసు గలవాడు", "जिनका मन सबमें समान है"], ["haviḥ", "హవిః", "The offering", "హవిస్సు", "हवि"]] },
"vsn_75_75": { "en": "The good goal, the good deed, existence itself, the true glory, the refuge of the good; leader of the Śūra army, best of the Yadus, dwelling place of the good, with the fine people of the Yamunā.", "te": "సద్గతి, సత్కర్మ, సత్తా, సద్విభూతి, సజ్జనుల ఆశ్రయం; శూరసేనుడు, యదువంశ శ్రేష్ఠుడు, సజ్జనులకు నివాసం, యమునా తీరవాసులతో కూడినవాడు.", "hi": "सद्गति, सत्कर्म, सत्ता, सद्विभूति, सज्जनों के आश्रय; शूरसेन, यदुश्रेष्ठ, सज्जनों के निवास, यमुना-तट वासियों से घिरे।", "names": [["sadgatiḥ", "సద్గతిః", "The goal reached by the good", "సజ్జనులు చేరే గమ్యం", "सज्जनों का गंतव्य"], ["satkṛtiḥ", "సత్కృతిః", "Whose deeds are good", "మంచి కర్మలు చేసేవాడు", "जिनके कर्म उत्तम हैं"], ["sattā", "సత్తా", "Pure existence", "శుద్ధ సత్తా", "शुद्ध सत्ता"], ["sadbhūtiḥ", "సద్భూతిః", "True being, ever shining", "సత్యమైన విభూతి", "सच्ची विभूति"], ["satparāyaṇaḥ", "సత్పరాయణః", "Refuge of the good", "సజ్జనుల ఆశ్రయం", "सज्जनों का आश्रय"], ["śūrasēnaḥ", "శూరసేనః", "With an army of heroes (like Hanumān)", "హనుమంతుని వంటి వీరుల సేన గలవాడు", "हनुमान जैसे वीरों की सेना वाले"], ["yaduśrēṣṭhaḥ", "యదుశ్రేష్ఠః", "Best of the Yadus", "యదువంశ శ్రేష్ఠుడు", "यदुवंश में श्रेष्ठ"], ["sannivāsaḥ", "సన్నివాసః", "Abode of the wise", "జ్ఞానులకు నివాసం", "ज्ञानियों के निवास"], ["suyāmunaḥ", "సుయామునః", "Surrounded by the good people of the Yamunā", "యమునా తీరంలోని సజ్జనులతో కూడినవాడు", "यमुना-तट के सज्जनों से घिरे"]] }
});
